function normalizarArrayJsonNFE(
    valor
) {

    if (
        Array.isArray(
            valor
        )
    ) {

        return valor;
    }


    if (
        typeof valor ===
        'string'
    ) {

        try {

            const convertido =
                JSON.parse(
                    valor
                );


            return Array.isArray(
                convertido
            )
                ? convertido
                : [];

        } catch (
            error
        ) {

            return [];
        }
    }


    return [];
}


function consolidarSnapshotsEstoqueAnuncioNFE(
    lista
) {

    const itens =
        normalizarArrayJsonNFE(
            lista
        );


    const mapa =
        new Map();


    itens.forEach(
        item => {

            if (
                !item ||
                typeof item !==
                    'object'
            ) {

                return;
            }


            const itemId =
                String(
                    item.item_id ||
                    ''
                )
                    .trim()
                    .toUpperCase();


            const variationId =
                item.variation_id ??
                '';


            const sku =
                String(
                    item.sku ||
                    ''
                )
                    .trim();


            const chave =
                `${itemId}|${variationId}|${sku}`;


            const anterior =
                mapa.get(
                    chave
                );


            if (
                !anterior
            ) {

                mapa.set(
                    chave,
                    item
                );

                return;
            }


            const dataAnterior =
                anterior.capturado_em
                    ? new Date(
                        anterior.capturado_em
                    )
                        .getTime()
                    : 0;


            const dataAtual =
                item.capturado_em
                    ? new Date(
                        item.capturado_em
                    )
                        .getTime()
                    : 0;


            if (
                dataAtual >=
                dataAnterior
            ) {

                mapa.set(
                    chave,
                    item
                );
            }
        }
    );


    return Array.from(
        mapa.values()
    );
}

async function enriquecerSnapshotCadastroInternoNFE(
    snapshot
) {
    const skuAnuncio =
        String(
            snapshot?.sku ||
            ''
        ).trim();

    let componentes = [];

    try {
        componentes =
            decomporSkuCompostoNFE(
                skuAnuncio,
                1
            ) || [];
    } catch (error) {
        console.warn(
            `⚠️ Não foi possível decompor o SKU ${skuAnuncio}:`,
            error
        );
    }

    if (componentes.length === 0) {
        componentes = [
            {
                sku:
                    skuAnuncio,

                quantidade_venda:
                    1
            }
        ];
    }

    const cadastroItens = [];

    for (
        const componente
        of componentes
    ) {
        const skuComponente =
            String(
                componente?.sku ||
                ''
            ).trim();

        if (
            !skuComponente ||
            skuComponente === 'SEM_SKU' ||
            skuComponente === 'N/A'
        ) {
            cadastroItens.push({
                sku:
                    skuComponente ||
                    'SEM_SKU',

                encontrado:
                    false,

                motivo:
                    'Venda sem SKU'
            });

            continue;
        }

        try {
            const {
                produto,
                error
            } =
                await buscarProdutoEstoquePorSkuNFE(
                    skuComponente
                );

            if (
                error ||
                !produto
            ) {
                cadastroItens.push({
                    sku:
                        skuComponente,

                    encontrado:
                        false,

                    motivo:
                        'Não cadastrado no estoque'
                });

                continue;
            }

            cadastroItens.push({
                sku:
                    produto.sku,

                nome:
                    produto.nome ||
                    '',

                produto_id:
                    produto.id,

                encontrado:
                    true,

                estoque_atual:
                    Number(
                        produto.quantidade ||
                        0
                    ),

                quantidade_por_anuncio:
                    Math.max(
                        1,
                        Number(
                            componente
                                .quantidade_venda ||
                            1
                        )
                    )
            });
        } catch (error) {
            cadastroItens.push({
                sku:
                    skuComponente,

                encontrado:
                    false,

                motivo:
                    error.message ||
                    'Erro consultando cadastro'
            });
        }
    }

    return {
        ...snapshot,

        cadastro_consultado:
            true,

        tem_cadastro:
            cadastroItens.some(
                cadastro =>
                    cadastro.encontrado === true
            ),

        todos_cadastrados:
            cadastroItens.length > 0 &&
            cadastroItens.every(
                cadastro =>
                    cadastro.encontrado === true
            ),

        cadastro_itens:
            cadastroItens
    };
}

function montarEstoqueAnuncioPosVendaHtmlNFE(venda) {
    const dados =
        Array.isArray(
            venda?._estoque_anuncio_pos_venda
        )
            ? venda._estoque_anuncio_pos_venda
            : [];

    if (dados.length === 0) {
        return `
            <span
                style="
                    color:#adb5bd;
                    font-size:10px;
                "
            >
                Não capturado
            </span>
        `;
    }

    return dados
        .map(item => {
            const quantidadeAnuncio =
                item.quantidade_anuncio_restante ??
                item.quantidade_restante;

            const possuiQuantidadeAnuncio =
                quantidadeAnuncio !== null &&
                quantidadeAnuncio !== undefined &&
                Number.isFinite(
                    Number(quantidadeAnuncio)
                );

            const numeroAnuncio =
                possuiQuantidadeAnuncio
                    ? Number(quantidadeAnuncio)
                    : null;

            const quantidadeFull =
                item.quantidade_full_restante;

            const possuiQuantidadeFull =
                quantidadeFull !== null &&
                quantidadeFull !== undefined &&
                Number.isFinite(
                    Number(quantidadeFull)
                );

            const numeroFull =
                possuiQuantidadeFull
                    ? Number(quantidadeFull)
                    : null;

            const ehFull =
                    item
                        ?.oferecendo_full ===
                        true;

            function obterCorEstoque(numero) {
                if (numero === null) {
                    return '#adb5bd';
                }

                if (numero === 0) {
                    return '#dc3545';
                }

                if (numero <= 2) {
                    return '#ffc107';
                }

                return '#28a745';
            }

            const corAnuncio =
                obterCorEstoque(
                    numeroAnuncio
                );

            const corFull =
                obterCorEstoque(
                    numeroFull
                );

            const exposicao =
                item.listing_type_nome ||
                nomeListingTypeFullNFE(
                    item.listing_type_id
                );

            const cadastroItens =
                Array.isArray(
                    item.cadastro_itens
                )
                    ? item.cadastro_itens
                    : [];

            const cadastrados =
                cadastroItens.filter(
                    cadastro =>
                        cadastro.encontrado === true
                );

            const naoCadastrados =
                cadastroItens.filter(
                    cadastro =>
                        cadastro.encontrado !== true
                );

            let cadastroHtml = '';

            if (
                item.cadastro_consultado === true
            ) {
                if (cadastrados.length > 0) {
                    cadastroHtml =
                        cadastrados
                            .map(cadastro => {
                                const nome =
                                    cadastro.nome ||
                                    cadastro.sku ||
                                    'Produto';

                                const estoqueInterno =
                                    Number(
                                        cadastro.estoque_atual ||
                                        0
                                    );

                                const quantidadePorAnuncio =
                                    Math.max(
                                        1,
                                        Number(
                                            cadastro
                                                .quantidade_por_anuncio ||
                                            1
                                        )
                                    );

                                return `
                                    <div
                                        style="
                                            margin-top:4px;
                                            padding-top:4px;
                                            border-top:1px solid #eeeeee;
                                        "
                                        title="${escaparHTMLNFE(
                                            nome
                                        )}"
                                    >
                                        <div
                                            style="
                                                color:#495057;
                                                font-size:9px;
                                            "
                                        >
                                            Estoque interno:
                                        </div>

                                        <div
                                            style="
                                                color:${
                                                    estoqueInterno > 0
                                                        ? '#28a745'
                                                        : '#dc3545'
                                                };
                                                font-size:11px;
                                                font-weight:700;
                                                white-space:nowrap;
                                            "
                                        >
                                            ${estoqueInterno} un.
                                        </div>

                                        ${
                                            cadastroItens.length > 1 ||
                                            quantidadePorAnuncio > 1
                                                ? `
                                                    <div
                                                        style="
                                                            color:#6c757d;
                                                            font-size:8px;
                                                            max-width:140px;
                                                            overflow:hidden;
                                                            text-overflow:ellipsis;
                                                            white-space:nowrap;
                                                        "
                                                        title="${escaparHTMLNFE(
                                                            nome
                                                        )}"
                                                    >
                                                        ${escaparHTMLNFE(
                                                            nome
                                                        )}
                                                    </div>

                                                    ${
                                                        quantidadePorAnuncio > 1
                                                            ? `
                                                                <div
                                                                    style="
                                                                        color:#6c757d;
                                                                        font-size:8px;
                                                                    "
                                                                >
                                                                    Usa ${quantidadePorAnuncio} por anúncio
                                                                </div>
                                                            `
                                                            : ''
                                                    }
                                                `
                                                : ''
                                        }
                                    </div>
                                `;
                            })
                            .join('');

                    if (naoCadastrados.length > 0) {
                        cadastroHtml += `
                            <div
                                style="
                                    color:#dc3545;
                                    font-size:9px;
                                    font-weight:700;
                                    margin-top:3px;
                                "
                            >
                                Cadastro incompleto
                            </div>
                        `;
                    }
                } else {
                    cadastroHtml = `
                        <div
                            style="
                                color:#dc3545;
                                font-size:9px;
                                font-weight:700;
                                margin-top:4px;
                            "
                        >
                            Sem cadastro
                        </div>
                    `;
                }
            }

            const estoqueFullHtml =
                ehFull
                    ? `
                        <div
                            style="
                                margin-top:4px;
                                padding:4px 5px;
                                background:#fff3f3;
                                border:1px solid #f5c6cb;
                                border-radius:4px;
                            "
                        >
                            <div
                                style="
                                    color:#721c24;
                                    font-size:8px;
                                    font-weight:700;
                                    white-space:nowrap;
                                "
                            >
                                ESTOQUE FULL
                            </div>

                            ${
                                possuiQuantidadeFull
                                    ? `
                                        <div
                                            style="
                                                color:${corFull};
                                                font-size:12px;
                                                font-weight:700;
                                                white-space:nowrap;
                                            "
                                        >
                                            ${numeroFull} un.
                                        </div>
                                    `
                                    : `
                                        <div
                                            style="
                                                color:#adb5bd;
                                                font-size:10px;
                                            "
                                        >
                                            N/I
                                        </div>
                                    `
                            }

                            <div
                                style="
                                    color:#adb5bd;
                                    font-size:8px;
                                    white-space:nowrap;
                                "
                            >
                                após a venda
                            </div>
                        </div>
                    `
                    : '';

            return `
                <div
                    style="
                        margin-bottom:7px;
                        min-width:115px;
                    "
                >
                    <div
                        style="
                            color:#495057;
                            font-size:8px;
                            font-weight:700;
                            white-space:nowrap;
                        "
                    >
                        ESTOQUE ANÚNCIO
                    </div>

                    ${
                        possuiQuantidadeAnuncio
                            ? `
                                <div
                                    style="
                                        font-weight:700;
                                        color:${corAnuncio};
                                        font-size:13px;
                                        white-space:nowrap;
                                    "
                                >
                                    ${numeroAnuncio} un.
                                </div>
                            `
                            : `
                                <div
                                    style="
                                        color:#adb5bd;
                                        font-size:10px;
                                    "
                                >
                                    N/I
                                </div>
                            `
                    }

                    <div
                        style="
                            color:#adb5bd;
                            font-size:8px;
                            white-space:nowrap;
                        "
                    >
                        após a venda
                    </div>

                    ${estoqueFullHtml}

                    <div
                        style="
                            display:inline-block;
                            margin-top:4px;
                            padding:2px 5px;
                            border-radius:4px;
                            background:${
                                String(exposicao)
                                    .toLowerCase()
                                    .includes('premium')
                                    ? '#6f42c1'
                                    : '#17a2b8'
                            };
                            color:#ffffff;
                            font-size:8px;
                            font-weight:700;
                            white-space:nowrap;
                        "
                    >
                        ${escaparHTMLNFE(exposicao)}
                    </div>

                    ${cadastroHtml}
                </div>
            `;
        })
        .join('');
}


// =========================================================
// IDENTIFICAR USUÁRIO
// =========================================================

function obterUsuarioPreferenciasColunasNFE() {

    // =====================================================
    // PRIMEIRA OPÇÃO:
    // USUÁRIO ATUAL DO SISTEMA
    // =====================================================

    if (
        window.currentUser?.username
    ) {

        return String(
            window.currentUser.username
        )
            .trim()
            .toLowerCase();
    }


    // =====================================================
    // FALLBACK:
    // USUÁRIO SALVO NA SESSÃO
    // =====================================================

    try {

        const usuarioSalvo =
            JSON.parse(
                localStorage.getItem(
                    'wheeltech_user'
                ) ||
                'null'
            );


        if (
            usuarioSalvo?.username
        ) {

            return String(
                usuarioSalvo.username
            )
                .trim()
                .toLowerCase();
        }


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Não foi possível identificar usuário para preferências NF-e:',
            error
        );
    }


    return 'padrao';
}


