// ORDEM PERSONALIZADA DAS COLUNAS
// =========================================================

function obterChaveOrdemColunasNFE() {

    return (
        `wheeltech_nfe_ordem_colunas_` +
        obterUsuarioPreferenciasColunasNFE()
    );
}


function carregarOrdemColunasNFE() {

    const padrao =
        COLUNAS_VENDAS_NFE.map(
            coluna =>
                coluna.id
        );


    try {

        const bruto =
            localStorage.getItem(
                obterChaveOrdemColunasNFE()
            );


        if (
            !bruto
        ) {

            return padrao;
        }


        const salva =
            JSON.parse(
                bruto
            );


        if (
            !Array.isArray(
                salva
            )
        ) {

            return padrao;
        }


        const validas =
            salva.filter(
                id =>
                    padrao.includes(
                        id
                    )
            );


        // =================================================
        // NOVAS COLUNAS ENTRAM AUTOMATICAMENTE
        // =================================================

        padrao.forEach(
            id => {

                if (
                    !validas.includes(
                        id
                    )
                ) {

                    validas.push(
                        id
                    );
                }
            }
        );


        return validas;


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Erro carregando ordem das colunas:',
            error
        );


        return padrao;
    }
}


function salvarOrdemColunasNFE(
    ordem
) {

    try {

        localStorage.setItem(

            obterChaveOrdemColunasNFE(),

            JSON.stringify(
                ordem
            )
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro salvando ordem das colunas:',
            error
        );
    }
}


function moverColunaNFE(
    colunaId,
    direcao
) {

    const ordem =
        carregarOrdemColunasNFE();


    const indice =
        ordem.indexOf(
            colunaId
        );


    if (
        indice <
        0
    ) {

        return;
    }


    const novoIndice =
        indice +
        Number(
            direcao
        );


    if (
        novoIndice <
            0 ||
        novoIndice >=
            ordem.length
    ) {

        return;
    }


    [
        ordem[indice],
        ordem[novoIndice]
    ] = [
        ordem[novoIndice],
        ordem[indice]
    ];


    salvarOrdemColunasNFE(
        ordem
    );


    reconstruirCabecalhoVendasNFE();


    aplicarPreferenciasColunasNFE();


    renderizarListaColunasNFE();
}


window.moverColunaNFE =
    moverColunaNFE;

    // =========================================================
// FILTRO E ORDENAÇÃO FRONT-END
// =========================================================

window._filtrosColunasNFE =
    window._filtrosColunasNFE ||
    {};


window._ordenacaoTabelaNFE =
    window._ordenacaoTabelaNFE ||
    {
        coluna:
            null,

        direcao:
            'asc'
    };


function normalizarTextoFiltroNFE(
    valor
) {

    return String(
        valor ||
        ''
    )
        .normalize(
            'NFD'
        )
        .replace(
            /[\u0300-\u036f]/g,
            ''
        )
        .trim()
        .toLowerCase();
}


function alterarFiltroColunaNFE(
    colunaId,
    valor
) {

    valor =
        String(
            valor ||
            ''
        );


    if (
        valor
    ) {

        window
            ._filtrosColunasNFE[
                colunaId
            ] =
            valor;

    } else {

        delete window
            ._filtrosColunasNFE[
                colunaId
            ];
    }


    aplicarFiltrosTabelaFrontendNFE();
}


function aplicarFiltrosTabelaFrontendNFE() {

    const tbody =
        document.getElementById(
            'vendasPendentesBody'
        );


    if (
        !tbody
    ) {

        return;
    }


    const filtros =
        window
            ._filtrosColunasNFE ||
        {};


    tbody
        .querySelectorAll(
            ':scope > tr'
        )
        .forEach(
            tr => {

                // =============================================
                // LINHA "NENHUMA VENDA"
                // =============================================

                if (
                    tr.querySelector(
                        'td[colspan]'
                    )
                ) {

                    tr.style.display =
                        '';

                    return;
                }


                let mostrar =
                    true;


                for (
                    const [
                        colunaId,
                        valorFiltro
                    ]
                    of Object.entries(
                        filtros
                    )
                ) {

                    if (
                        !valorFiltro
                    ) {

                        continue;
                    }


                    const td =
                        tr.querySelector(
                            `:scope > td[data-coluna-nfe="${colunaId}"]`
                        );


                    if (
                        !td
                    ) {

                        continue;
                    }


                    const texto =
                        normalizarTextoFiltroNFE(
                            td.textContent
                        );


                    const busca =
                        normalizarTextoFiltroNFE(
                            valorFiltro
                        );


                    if (
                        !texto.includes(
                            busca
                        )
                    ) {

                        mostrar =
                            false;

                        break;
                    }
                }


                tr.style.display =
                    mostrar
                        ? ''
                        : 'none';
            }
        );
}


function obterValorOrdenacaoCelulaNFE(
    td,
    colunaId
) {

    const texto =
        String(
            td?.textContent ||
            ''
        )
            .replace(
                /\s+/g,
                ' '
            )
            .trim();


    // =====================================================
    // VALOR
    // =====================================================

    if (
        colunaId ===
        'valor'
    ) {

        const match =
            texto.match(
                /R\$\s*([\d.,]+)/
            );


        if (
            match
        ) {

            let numero =
                match[1];


            if (
                numero.includes(
                    ','
                )
            ) {

                numero =
                    numero
                        .replace(
                            /\./g,
                            ''
                        )
                        .replace(
                            ',',
                            '.'
                        );
            }


            const valor =
                Number(
                    numero
                );


            if (
                Number.isFinite(
                    valor
                )
            ) {

                return valor;
            }
        }
    }


    // =====================================================
    // DATAS DD/MM/AAAA
    // =====================================================

    if (
        [
            'envio',
            'venda',
            'separado'
        ].includes(
            colunaId
        )
    ) {

        const match =
            texto.match(
                /(\d{2})\/(\d{2})\/(\d{4})(?:.*?(\d{2}):(\d{2}))?/
            );


        if (
            match
        ) {

            return new Date(
                Number(
                    match[3]
                ),
                Number(
                    match[2]
                ) -
                    1,
                Number(
                    match[1]
                ),
                Number(
                    match[4] ||
                    0
                ),
                Number(
                    match[5] ||
                    0
                )
            )
                .getTime();
        }
    }


    return normalizarTextoFiltroNFE(
        texto
    );
}


function aplicarOrdenacaoAtualNFE() {

    const configuracao =
        window
            ._ordenacaoTabelaNFE;


    if (
        !configuracao
            ?.coluna
    ) {

        return;
    }


    const tbody =
        document.getElementById(
            'vendasPendentesBody'
        );


    if (
        !tbody
    ) {

        return;
    }


    const colunaId =
        configuracao.coluna;


    const direcao =
        configuracao.direcao ===
            'desc'
            ? -1
            : 1;


    const linhas =
        Array.from(
            tbody.querySelectorAll(
                ':scope > tr'
            )
        )
            .filter(
                tr =>
                    !tr.querySelector(
                        'td[colspan]'
                    )
            );


    const collator =
        new Intl.Collator(
            'pt-BR',
            {
                numeric:
                    true,

                sensitivity:
                    'base'
            }
        );


    linhas.sort(
        (
            a,
            b
        ) => {

            const tdA =
                a.querySelector(
                    `:scope > td[data-coluna-nfe="${colunaId}"]`
                );


            const tdB =
                b.querySelector(
                    `:scope > td[data-coluna-nfe="${colunaId}"]`
                );


            const valorA =
                obterValorOrdenacaoCelulaNFE(
                    tdA,
                    colunaId
                );


            const valorB =
                obterValorOrdenacaoCelulaNFE(
                    tdB,
                    colunaId
                );


            if (
                typeof valorA ===
                    'number' &&
                typeof valorB ===
                    'number'
            ) {

                return (
                    valorA -
                    valorB
                ) *
                direcao;
            }


            return (
                collator.compare(
                    String(
                        valorA
                    ),
                    String(
                        valorB
                    )
                ) *
                direcao
            );
        }
    );


    linhas.forEach(
        tr =>
            tbody.appendChild(
                tr
            )
    );


    atualizarIndicadoresOrdenacaoNFE();
}


function ordenarTabelaVendasPorColunaNFE(
    colunaId
) {

    const atual =
        window
            ._ordenacaoTabelaNFE;


    if (
        atual.coluna ===
        colunaId
    ) {

        atual.direcao =
            atual.direcao ===
                'asc'
                ? 'desc'
                : 'asc';

    } else {

        atual.coluna =
            colunaId;

        atual.direcao =
            'asc';
    }


    aplicarOrdenacaoAtualNFE();
}


function atualizarIndicadoresOrdenacaoNFE() {

    document
        .querySelectorAll(
            '[data-sort-icon-nfe]'
        )
        .forEach(
            elemento => {

                const coluna =
                    elemento.dataset
                        .sortIconNfe;


                if (
                    window
                        ._ordenacaoTabelaNFE
                        .coluna !==
                    coluna
                ) {

                    elemento.textContent =
                        '↕';

                    return;
                }


                elemento.textContent =
                    window
                        ._ordenacaoTabelaNFE
                        .direcao ===
                        'asc'
                        ? '↑'
                        : '↓';
            }
        );
}


window.alterarFiltroColunaNFE =
    alterarFiltroColunaNFE;

window.ordenarTabelaVendasPorColunaNFE =
    ordenarTabelaVendasPorColunaNFE;

    // =========================================================
// CONTROLE DE SEPARAÇÃO
// =========================================================

function vendaEstaSeparadaNFE(
    venda
) {

    if (
        !venda
    ) {

        return false;
    }


    if (
        Array.isArray(
            venda._membros_pack
        ) &&
        venda._membros_pack.length >
            0
    ) {

        return venda
            ._membros_pack
            .every(
                membro =>
                    membro?._separado ===
                        true ||
                    membro?.separado ===
                        true
            );
    }


    return (
        venda._separado ===
            true ||
        venda.separado ===
            true
    );
}


function obterInfoSeparacaoNFE(
    venda
) {

    if (
        !venda
    ) {

        return {
            separado:
                false,

            separado_em:
                null,

            separado_por:
                null
        };
    }


    if (
        Array.isArray(
            venda._membros_pack
        ) &&
        venda._membros_pack.length >
            0
    ) {

        const todosSeparados =
            vendaEstaSeparadaNFE(
                venda
            );


        const datas =
            venda
                ._membros_pack
                .map(
                    membro =>
                        membro
                            ._separado_em ||
                        membro
                            .separado_em
                )
                .filter(Boolean)
                .sort();


        const nomes =
            [
                ...new Set(
                    venda
                        ._membros_pack
                        .map(
                            membro =>
                                membro
                                    ._separado_por_nome ||
                                membro
                                    .separado_por_nome
                        )
                        .filter(Boolean)
                )
            ];


        return {

            separado:
                todosSeparados,

            separado_em:
                todosSeparados
                    ? (
                        datas.at(
                            -1
                        ) ||
                        null
                    )
                    : null,

            separado_por:
                nomes.join(
                    ' / '
                ) ||
                null
        };
    }


    return {

        separado:
            vendaEstaSeparadaNFE(
                venda
            ),

        separado_em:
            venda._separado_em ||
            venda.separado_em ||
            null,

        separado_por:
            venda._separado_por_nome ||
            venda.separado_por_nome ||
            null
    };
}


function montarCelulaSeparadoNFE(
    venda
) {

    const isFull =
        Boolean(
            venda?._is_full
        );


    if (
        isFull
    ) {

        return `
            <div
                style="
                    color:#6c757d;
                    font-size:10px;
                    white-space:nowrap;
                "
            >
                <i class="fas fa-warehouse"></i>
                FULL
                <div
                    style="
                        font-size:8px;
                        margin-top:2px;
                    "
                >
                    Não se aplica
                </div>
            </div>
        `;
    }


    if (
        vendaEstaCanceladaNFE(
            venda
        )
    ) {

        return `
            <span
                style="
                    color:#dc3545;
                    font-size:10px;
                    font-weight:700;
                "
            >
                <i class="fas fa-ban"></i>
                Cancelada
            </span>
        `;
    }


    const info =
        obterInfoSeparacaoNFE(
            venda
        );


    if (
        info.separado
    ) {

        let dataFormatada =
            '';


        if (
            info.separado_em
        ) {

            try {

                dataFormatada =
                    new Date(
                        info.separado_em
                    )
                        .toLocaleString(
                            'pt-BR',
                            {
                                day:
                                    '2-digit',

                                month:
                                    '2-digit',

                                year:
                                    'numeric',

                                hour:
                                    '2-digit',

                                minute:
                                    '2-digit'
                            }
                        );

            } catch (
                error
            ) {}
        }


        return `
            <div>
                <span
                    style="
                        display:inline-block;
                        background:#28a745;
                        color:white;
                        padding:4px 8px;
                        border-radius:5px;
                        font-size:11px;
                        font-weight:700;
                        white-space:nowrap;
                    "
                >
                    <i class="fas fa-check"></i>
                    Separado
                </span>

                ${
                    dataFormatada
                        ? `
                            <div
                                style="
                                    margin-top:4px;
                                    font-size:9px;
                                    color:#495057;
                                    white-space:nowrap;
                                "
                            >
                                ${escaparHTMLNFE(
                                    dataFormatada
                                )}
                            </div>
                        `
                        : ''
                }

                ${
                    info.separado_por
                        ? `
                            <div
                                style="
                                    margin-top:2px;
                                    font-size:9px;
                                    color:#6c757d;
                                    white-space:nowrap;
                                "
                            >
                                por
                                <strong>
                                    ${escaparHTMLNFE(
                                        info.separado_por
                                    )}
                                </strong>
                            </div>
                        `
                        : ''
                }
            </div>
        `;
    }


    const vendaId =
        normalizarOrderIdML(
            venda.id_venda_ml ||
            venda.id
        );


    return `
        <div>
            <button
                type="button"
                class="btn btn-sm btn-primary"
                onclick="marcarVendaComoSeparadaNFE('${escaparHTMLNFE(
                    vendaId
                )}')"
            >
                <i class="fas fa-box-open"></i>
                Separado
            </button>

            <div
                style="
                    margin-top:3px;
                    font-size:9px;
                    color:#856404;
                    white-space:nowrap;
                "
            >
                Pendente separação
            </div>
        </div>
    `;
}


async function marcarVendaComoSeparadaNFE(
    vendaId
) {

    vendaId =
        normalizarOrderIdML(
            vendaId
        );


    if (
        !vendaId
    ) {

        showToast(
            '❌ Venda inválida.',
            'error'
        );

        return;
    }


    const venda =
        (
            Array.isArray(
                vendasPendentes
            )
                ? vendasPendentes
                : []
        )
            .find(
                item => {

                    const principal =
                        normalizarOrderIdML(
                            item.id_venda_ml ||
                            item.id
                        );


                    if (
                        principal ===
                        vendaId
                    ) {

                        return true;
                    }


                    return (
                        Array.isArray(
                            item._order_ids_pack
                        ) &&
                        item
                            ._order_ids_pack
                            .map(
                                normalizarOrderIdML
                            )
                            .includes(
                                vendaId
                            )
                    );
                }
            );


    if (
        !venda
    ) {

        showToast(
            '❌ Venda não encontrada.',
            'error'
        );

        return;
    }


    if (
        vendaEstaCanceladaNFE(
            venda
        )
    ) {

        showToast(
            '🚫 Venda cancelada.',
            'warning'
        );

        return;
    }


    if (
        venda._is_full
    ) {

        showToast(
            'ℹ️ Venda FULL não precisa de separação local.',
            'info'
        );

        return;
    }


    const ids =
        [
            ...new Set(
                (
                    Array.isArray(
                        venda._order_ids_pack
                    ) &&
                    venda._order_ids_pack.length >
                        0

                        ? venda._order_ids_pack

                        : [
                            vendaId
                        ]
                )
                    .map(
                        normalizarOrderIdML
                    )
                    .filter(Boolean)
            )
        ];


    const usuario =
        obterUsuarioOperacaoNFE();


    const agora =
        new Date()
            .toISOString();


    try {

        const {
            error
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_cache'
                )
                .update({

                    separado:
                        true,

                    separado_em:
                        agora,

                    separado_por_username:
                        usuario.username,

                    separado_por_nome:
                        usuario.nome
                })
                .in(
                    'id_venda_ml',
                    ids
                );


        if (
            error
        ) {

            throw error;
        }


        // =================================================
        // ATUALIZAR MEMÓRIA IMEDIATAMENTE
        // =================================================

        const atualizarVenda =
            item => {

                const id =
                    normalizarOrderIdML(
                        item.id_venda_ml ||
                        item.id
                    );


                if (
                    !ids.includes(
                        id
                    )
                ) {

                    return;
                }


                item._separado =
                    true;

                item.separado =
                    true;

                item._separado_em =
                    agora;

                item.separado_em =
                    agora;

                item._separado_por_username =
                    usuario.username;

                item.separado_por_username =
                    usuario.username;

                item._separado_por_nome =
                    usuario.nome;

                item.separado_por_nome =
                    usuario.nome;
            };


        (
            Array.isArray(
                window._vendasTabelaNFEBase
            )
                ? window._vendasTabelaNFEBase
                : []
        )
            .forEach(
                atualizarVenda
            );

            (
    Array.isArray(
        vendasPendentes
    )
        ? vendasPendentes
        : []
)
    .forEach(
        atualizarVenda
    );


        showToast(
            ids.length >
                1
                ? `✅ Pacote separado. ${ids.length} vendas marcadas.`
                : '✅ Produto marcado como separado.',
            'success'
        );


        renderizarVendasNFETabela(
            window._vendasTabelaNFEBase ||
            []
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro marcando separação:',
            error
        );


        showToast(
            `❌ Não foi possível marcar como separado: ${error.message}`,
            'error'
        );
    }
}


window.marcarVendaComoSeparadaNFE =
    marcarVendaComoSeparadaNFE;

    async function enriquecerVendasComSeparacaoNFE(
    vendas
) {

    if (
        !Array.isArray(
            vendas
        ) ||
        vendas.length ===
            0
    ) {

        return [];
    }


    const ids =
        [
            ...new Set(
                vendas
                    .map(
                        venda =>
                            normalizarOrderIdML(
                                venda.id_venda_ml ||
                                venda.id
                            )
                    )
                    .filter(Boolean)
            )
        ];


    const mapa =
        new Map();


    const TAMANHO_LOTE =
        200;


    for (
        let i = 0;
        i < ids.length;
        i += TAMANHO_LOTE
    ) {

        const lote =
            ids.slice(
                i,
                i +
                    TAMANHO_LOTE
            );


        const {
            data,
            error
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_cache'
                )
                .select(`
                    id_venda_ml,
                    separado,
                    separado_em,
                    separado_por_username,
                    separado_por_nome
                `)
                .in(
                    'id_venda_ml',
                    lote
                );


        if (
            error
        ) {

            console.warn(
                '⚠️ Erro carregando separação:',
                error
            );

            continue;
        }


        (
            data ||
            []
        )
            .forEach(
                registro => {

                    mapa.set(
                        normalizarOrderIdML(
                            registro.id_venda_ml
                        ),
                        registro
                    );
                }
            );
    }


    return vendas.map(
        venda => {

            const id =
                normalizarOrderIdML(
                    venda.id_venda_ml ||
                    venda.id
                );


            const registro =
                mapa.get(
                    id
                );


            return {

                ...venda,

                _separado:
                    Boolean(
                        registro
                            ?.separado
                    ),

                separado:
                    Boolean(
                        registro
                            ?.separado
                    ),

                _separado_em:
                    registro
                        ?.separado_em ||
                    null,

                separado_em:
                    registro
                        ?.separado_em ||
                    null,

                _separado_por_username:
                    registro
                        ?.separado_por_username ||
                    null,

                separado_por_username:
                    registro
                        ?.separado_por_username ||
                    null,

                _separado_por_nome:
                    registro
                        ?.separado_por_nome ||
                    null,

                separado_por_nome:
                    registro
                        ?.separado_por_nome ||
                    null
            };
        }
    );
}

// =========================================================
// PERÍODO NF-E
// =========================================================

function obterChavePeriodoNFE() {

    return (
        `wheeltech_nfe_periodo_` +
        obterUsuarioPreferenciasColunasNFE()
    );
}


function salvarPeriodoSelecionadoNFE(
    inicio,
    fim
) {

    try {

        localStorage.setItem(
            obterChavePeriodoNFE(),
            JSON.stringify({
                inicio,
                fim
            })
        );

    } catch (
        error
    ) {}
}


function carregarPeriodoSalvoNFE() {

    const hoje =
        obterDataHojeLocal();


    try {

        const bruto =
            localStorage.getItem(
                obterChavePeriodoNFE()
            );


        if (
            bruto
        ) {

            const dados =
                JSON.parse(
                    bruto
                );


            if (
                dados?.inicio &&
                dados?.fim
            ) {

                return dados;
            }
        }

    } catch (
        error
    ) {}


    return {
        inicio:
            hoje,

        fim:
            hoje
    };
}


function obterPeriodoSelecionadoNFE() {

    const inicio =
        document.getElementById(
            'filtroDataInicioNFE'
        )?.value ||
        obterDataHojeLocal();


    const fim =
        document.getElementById(
            'filtroDataFimNFE'
        )?.value ||
        inicio;


    if (
        inicio >
        fim
    ) {

        return {
            inicio:
                fim,

            fim:
                inicio
        };
    }


    return {
        inicio,
        fim
    };
}


function listarDatasPeriodoNFE(
    inicio,
    fim
) {

    const resultado =
        [];


    const atual =
        new Date(
            `${inicio}T12:00:00`
        );


    const limite =
        new Date(
            `${fim}T12:00:00`
        );


    while (
        atual <=
        limite
    ) {

        const ano =
            atual.getFullYear();


        const mes =
            String(
                atual.getMonth() +
                1
            )
                .padStart(
                    2,
                    '0'
                );


        const dia =
            String(
                atual.getDate()
            )
                .padStart(
                    2,
                    '0'
                );


        resultado.push(
            `${ano}-${mes}-${dia}`
        );


        atual.setDate(
            atual.getDate() +
            1
        );
    }


    return resultado;
}


function obterDataReferenciaVendaPeriodoNFE(
    venda
) {

    const isFull =
        Boolean(
            venda?._is_full ||
            venda?.is_full
        );


    const bruto =
        isFull

            ? (
                venda.data_venda ||
                venda.date_created
            )

            : (
                venda._data_envio ||
                venda.data_envio ||
                venda.date_created
            );


    return normalizarDataEnvioML(
        bruto
    );
}


async function carregarVendasCachePeriodoNFE(
    inicio = null,
    fim = null
) {

    let vendas =
        await carregarVendasCacheNFE(
            null
        );


    if (
        inicio ||
        fim
    ) {

        inicio =
            inicio ||
            fim;


        fim =
            fim ||
            inicio;


        vendas =
            vendas.filter(
                venda => {

                    const data =
                        obterDataReferenciaVendaPeriodoNFE(
                            venda
                        );


                    if (
                        !data
                    ) {

                        return false;
                    }


                    return (
                        data >=
                            inicio &&
                        data <=
                            fim
                    );
                }
            );
    }


    vendas =
        await enriquecerVendasComSeparacaoNFE(
            vendas
        );


    return vendas;
}

function montarFiltroCabecalhoNFE(
    coluna
) {

    const valorAtual =
        window
            ._filtrosColunasNFE[
                coluna.id
            ] ||
        '';


    if (
        coluna.id ===
        'modalidade'
    ) {

        const atual =
            window
                ._filtroModalidadeNFE ||
            'todas';


        return `
            <select
                class="form-control"
                onclick="event.stopPropagation()"
                onchange="
                    alterarFiltroModalidadeNFE(
                        this.value
                    )
                "
                style="
                    height:27px;
                    padding:2px 4px !important;
                    font-size:10px !important;
                    margin-top:4px;
                    min-width:95px;
                "
            >
                <option
                    value="todas"
                    ${
                        atual ===
                            'todas'
                            ? 'selected'
                            : ''
                    }
                >
                    Todas
                </option>

                <option
                    value="full"
                    ${
                        atual ===
                            'full'
                            ? 'selected'
                            : ''
                    }
                >
                    FULL
                </option>

                <option
                    value="me"
                    ${
                        atual ===
                            'me'
                            ? 'selected'
                            : ''
                    }
                >
                    ME
                </option>
            </select>
        `;
    }


    if (
        coluna.id ===
        'separado'
    ) {

        return `
            <select
                class="form-control"
                onclick="event.stopPropagation()"
                onchange="
                    alterarFiltroColunaNFE(
                        'separado',
                        this.value
                    )
                "
                style="
                    height:27px;
                    padding:2px 4px !important;
                    font-size:10px !important;
                    margin-top:4px;
                    min-width:100px;
                "
            >
                <option value="">
                    Todos
                </option>

                <option
                    value="separado"
                    ${
                        valorAtual ===
                            'separado'
                            ? 'selected'
                            : ''
                    }
                >
                    Separados
                </option>

                <option
                    value="pendente"
                    ${
                        valorAtual ===
                            'pendente'
                            ? 'selected'
                            : ''
                    }
                >
                    Pendentes
                </option>
            </select>
        `;
    }


    if (
        [
            'foto',
            'acoes'
        ].includes(
            coluna.id
        )
    ) {

        return '';
    }


    return `
        <input
            type="text"
            class="form-control"
            value="${escaparHTMLNFE(
                valorAtual
            )}"
            placeholder="Filtrar..."
            onclick="event.stopPropagation()"
            oninput="
                alterarFiltroColunaNFE(
                    '${coluna.id}',
                    this.value
                )
            "
            style="
                height:27px;
                padding:2px 5px !important;
                font-size:10px !important;
                margin-top:4px;
                min-width:75px;
            "
        >
    `;
}


