function alternarPainelColunasNFE() {

    const painel =
        document.getElementById(
            'painelColunasNFE'
        );


    if (!painel) {

        return;
    }


    const aberto =
        painel.style.display ===
        'block';


    painel.style.display =
        aberto
            ? 'none'
            : 'block';


    if (
        !aberto
    ) {

        aplicarPreferenciasColunasNFE();
    }
}


