// =========================================================
// IDENTIFICAR MODALIDADE DA VENDA
// =========================================================

function obterModalidadeFiltroNFE(
    venda
) {

    const tipo =
        `${venda?._logistic_type || ''} ` +
        `${venda?._shipping_mode || ''} ` +
        `${venda?.tipo_envio || ''}`
            .toUpperCase();


    // =====================================================
    // FULL
    // =====================================================

    if (
        venda?._is_full ||
        tipo.includes(
            'FULL'
        ) ||
        tipo.includes(
            'FULFILLMENT'
        )
    ) {

        return 'full';
    }


    // =====================================================
    // MERCADO ENVIOS
    //
    // Mesma lógica usada atualmente pelo badge "ME"
    // =====================================================

    if (
        tipo.includes(
            'CROSS_DOCKING'
        ) ||
        tipo.includes(
            'MERCADO'
        ) ||
        tipo.includes(
            'ME2'
        )
    ) {

        return 'me';
    }


    // FLEX / OUTROS
    return 'outros';
}


