// ALTERAR FILTRO
// =========================================================

function alterarFiltroModalidadeNFE(
    valor
) {

    valor =
        String(
            valor ||
            'todas'
        )
            .trim()
            .toLowerCase();


    if (
        ![
            'todas',
            'full',
            'me'
        ].includes(
            valor
        )
    ) {

        valor =
            'todas';
    }


    window._filtroModalidadeNFE =
        valor;


    console.log(
        '🚚 Filtro modalidade NF-e:',
        valor
    );


    // =====================================================
    // RENDERIZAR NOVAMENTE USANDO TODAS AS VENDAS ORIGINAIS
    // =====================================================

    const vendas =
        Array.isArray(
            window._vendasTabelaNFEBase
        )
            ? window._vendasTabelaNFEBase
            : [];


    renderizarVendasNFETabela(
        vendas
    );
}


