async function mostrarTodasVendasCacheNFE() {

    window._nfeFiltroTodas =
        true;


    const status =
        document.getElementById(
            'statusAtualizacaoNFE'
        );


    if (
        status
    ) {

        status.textContent =
            'Exibindo todas as vendas salvas';
    }


    const vendas =
        await carregarVendasCachePeriodoNFE(
            null,
            null
        );


    renderizarVendasNFETabela(
        vendas
    );


    aplicarPreferenciasColunasNFE();
}

async function atualizarVendasDataSelecionada() {

    window._nfeFiltroTodas =
        false;


    const {
        inicio,
        fim
    } =
        obterPeriodoSelecionadoNFE();


    salvarPeriodoSelecionadoNFE(
        inicio,
        fim
    );


    const datas =
        listarDatasPeriodoNFE(
            inicio,
            fim
        );


    const status =
        document.getElementById(
            'statusAtualizacaoNFE'
        );


    const btn =
        document.getElementById(
            'btnAtualizarDataNFE'
        );


    const textoOriginal =
        btn?.innerHTML ||
        '';


    try {

        if (
            btn
        ) {

            btn.disabled =
                true;


            btn.innerHTML =
                '<span class="spinner"></span> Atualizando...';
        }


        if (
            status
        ) {

            status.textContent =
                'Carregando período...';
        }


        // =====================================================
        // CACHE IMEDIATO
        // =====================================================

        const cache =
            await carregarVendasCachePeriodoNFE(
                inicio,
                fim
            );


        renderizarVendasNFETabela(
            cache
        );


        // =====================================================
        // SINCRONIZAR CADA DIA DO PERÍODO
        // =====================================================

        let processadas =
            0;


        const erros =
            [];


        for (
            const data
            of datas
        ) {

            processadas++;


            if (
                status
            ) {

                status.textContent =
                    `Sincronizando ${processadas}/${datas.length}: ${formatarDataNFE(
                        data
                    )}`;
            }


            try {

                await sincronizarVendasPendentesML(
                    data,
                    true
                );


                localStorage.setItem(
                    `nfe_sync_${data}`,
                    String(
                        Date.now()
                    )
                );


            } catch (
                error
            ) {

                console.warn(
                    `⚠️ Erro sincronizando ${data}:`,
                    error
                );


                erros.push({
                    data,
                    error:
                        error.message
                });
            }
        }


        // =====================================================
        // CANCELAMENTOS
        // =====================================================

        await verificarCancelamentosVendasNFE();


        // =====================================================
        // RECARREGAR PERÍODO
        // =====================================================

        const atualizado =
            await carregarVendasCachePeriodoNFE(
                inicio,
                fim
            );


        renderizarVendasNFETabela(
            atualizado
        );


        aplicarPreferenciasColunasNFE();


        if (
            status
        ) {

            status.textContent =
                `Período ${formatarDataNFE(
                    inicio
                )} a ${formatarDataNFE(
                    fim
                )} — ${atualizado.length} venda(s)`;
        }


        showToast(
            `✅ ${atualizado.length} venda(s) carregada(s) no período.`,
            'success'
        );


        // =====================================================
        // MONITOR DE ESTOQUE / ALERTAS
        // SOMENTE CONSULTA, COMO DEFINIMOS
        // =====================================================

        if (
            typeof verificarMonitorFullVendasNFE ===
            'function'
        ) {

            verificarMonitorFullVendasNFE({
                forcar:
                    true
            })
                .catch(
                    error => {

                        console.warn(
                            '⚠️ Conferência de estoques:',
                            error
                        );
                    }
                );
        }


        if (
            erros.length >
            0
        ) {

            console.warn(
                '⚠️ Datas com erro:',
                erros
            );
        }


    } catch (
        error
    ) {

        console.error(
            '❌ Erro atualizando período:',
            error
        );


        if (
            status
        ) {

            status.textContent =
                'Erro na atualização';
        }


        showToast(
            `❌ Erro ao atualizar período: ${error.message}`,
            'error'
        );


    } finally {

        if (
            btn
        ) {

            btn.disabled =
                false;


            btn.innerHTML =
                textoOriginal ||
                '<i class="fas fa-sync-alt"></i> Atualizar período';
        }
    }
}


function inicializarFiltroDataNFE() {

    garantirControlesVendasNFE();


    const periodo =
        carregarPeriodoSalvoNFE();


    const inicio =
        document.getElementById(
            'filtroDataInicioNFE'
        );


    const fim =
        document.getElementById(
            'filtroDataFimNFE'
        );


    if (
        inicio &&
        !inicio.value
    ) {

        inicio.value =
            periodo.inicio;
    }


    if (
        fim &&
        !fim.value
    ) {

        fim.value =
            periodo.fim;
    }


    const legado =
        document.getElementById(
            'filtroDataEnvioNFE'
        );


    if (
        legado
    ) {

        legado.value =
            inicio?.value ||
            periodo.inicio;
    }
}

// =========================================================
// NORMALIZAR DATA
// =========================================================

function normalizarDataEnvioML(valor) {

    if (!valor) {
        return null;
    }

    const match =
        String(valor).match(
            /(\d{4}-\d{2}-\d{2})/
        );

    return match
        ? match[1]
        : null;
}

async function verificarEstoqueVenda(
    venda
) {

    try {

        console.log(
            '🔎 [NFE] Verificando estoque da venda:',
            {
                id:
                    venda.id_venda_ml ||
                    venda.id,

                sku:
                    venda.sku,

                eh_kit:
                    venda.eh_kit,

                skus_kit:
                    venda.skus_kit
            }
        );


        let itensParaVerificar =
            [];


        // =====================================================
        // FUNÇÃO INTERNA
        //
        // RECEBE UM SKU QUE PODE SER:
        //
        // 00100972ROLCXDIR45,3-35-7,3
        //
        // OU:
        //
        // 00100872ROL-S16250000.00200972ROLCXDIR45,3-35-7,3
        //
        // E TRANSFORMA EM PRODUTOS FÍSICOS.
        // =====================================================

        const adicionarSku =
            (
                skuOriginal,
                quantidadeBase = 1
            ) => {

                quantidadeBase =
                    Number(
                        quantidadeBase ||
                        1
                    );


                if (
                    !skuOriginal ||
                    skuOriginal ===
                        'SEM_SKU' ||
                    skuOriginal ===
                        'N/A'
                ) {

                    itensParaVerificar.push({

                        sku:
                            'SEM_SKU',

                        sku_original:
                            skuOriginal ||
                            'SEM_SKU',

                        quantidade_venda:
                            quantidadeBase
                    });

                    return;
                }


                // =============================================
                // ESTA FUNÇÃO JÁ EXISTE NO SEU CÓDIGO
                //
                // Ela:
                // - separa pelo ponto
                // - lê os 3 primeiros caracteres
                // - remove o prefixo
                // - calcula a quantidade
                // =============================================

                const componentes =
                    decomporSkuCompostoNFE(
                        skuOriginal,
                        quantidadeBase
                    );


                if (
                    componentes.length ===
                    0
                ) {

                    itensParaVerificar.push({

                        sku:
                            'SEM_SKU',

                        sku_original:
                            skuOriginal,

                        quantidade_venda:
                            quantidadeBase
                    });

                    return;
                }


                for (
                    const componente
                    of componentes
                ) {

                    itensParaVerificar.push({

                        ...componente,

                        quantidade_venda:
                            Number(
                                componente
                                    .quantidade_venda ||
                                1
                            )
                    });
                }
            };


        // =====================================================
        // 1. KIT JÁ CONFIGURADO NA ABA VENDAS ML
        // =====================================================

        if (
            venda.eh_kit &&
            Array.isArray(
                venda.skus_kit
            ) &&
            venda.skus_kit.length >
                0
        ) {

            console.log(
                `📦 [NFE] KIT configurado com ${venda.skus_kit.length} item(ns)`
            );


            for (
                const item
                of venda.skus_kit
            ) {

                const quantidadeBase =
                    Number(
                        item.estoque ||
                        item.quantidade ||
                        1
                    ) *
                    Number(
                        venda.quantidade ||
                        venda.quantity ||
                        1
                    );


                adicionarSku(
                    item.sku,
                    quantidadeBase
                );
            }


        // =====================================================
        // 2. SKU DIRETO DA VENDA
        //
        // PODE SER SIMPLES OU COMPOSTO.
        // =====================================================

        } else if (
            venda.sku &&
            venda.sku !==
                'SEM_SKU'
        ) {

            adicionarSku(

                venda.sku,

                Number(
                    venda.quantidade ||
                    venda.quantity ||
                    1
                )
            );


        // =====================================================
        // 3. FALLBACK PARA ORDER_ITEMS DO MERCADO LIVRE
        // =====================================================

        } else if (
            Array.isArray(
                venda.order_items
            ) &&
            venda.order_items.length >
                0
        ) {

            for (
                const item
                of venda.order_items
            ) {

                adicionarSku(

                    item.item
                        ?.seller_sku,

                    Number(
                        item.quantity ||
                        1
                    )
                );
            }
        }


        console.log(
            '🧩 [NFE] Componentes identificados:',
            itensParaVerificar
        );


        // =====================================================
        // NENHUM PRODUTO IDENTIFICADO
        // =====================================================

        if (
            itensParaVerificar.length ===
            0
        ) {

            return {

                status:
                    'sem_cadastro',

                produtos:
                    []
            };
        }


        // =====================================================
        // CONSOLIDAR PRODUTOS REPETIDOS
        //
        // A CHAVE É SEMPRE OS 8 PRIMEIROS CARACTERES.
        //
        // Ex.:
        // 001ABC...
        // 001ABC...
        //
        // Soma as quantidades.
        // =====================================================

        const mapaProdutos =
            new Map();


        let contadorSemSku =
            0;


        for (
            const item
            of itensParaVerificar
        ) {

            if (
                !item.sku ||
                item.sku ===
                    'SEM_SKU' ||
                item.sku ===
                    'N/A'
            ) {

                mapaProdutos.set(
                    `SEM_SKU_${contadorSemSku++}`,
                    {
                        ...item
                    }
                );

                continue;
            }


            const chave =
                chaveCadastroSkuNFE(
                    item.sku
                );


            if (
                mapaProdutos.has(
                    chave
                )
            ) {

                const existente =
                    mapaProdutos.get(
                        chave
                    );


                existente
                    .quantidade_venda +=
                    Number(
                        item.quantidade_venda ||
                        0
                    );


                existente
                    .skus_origem =
                    [
                        ...(
                            existente
                                .skus_origem ||
                            [
                                existente
                                    .sku_original
                            ]
                        ),

                        item.sku_original
                    ];


            } else {

                mapaProdutos.set(
                    chave,
                    {
                        ...item,

                        chave_cadastro:
                            chave,

                        quantidade_venda:
                            Number(
                                item.quantidade_venda ||
                                1
                            ),

                        skus_origem:
                            [
                                item.sku_original
                            ]
                    }
                );
            }
        }


        const itensConsolidados =
            [
                ...mapaProdutos.values()
            ];


        console.log(
            '📦 [NFE] Produtos físicos consolidados:',
            itensConsolidados
        );


        // =====================================================
        // CONSULTAR CADA PRODUTO NO CADASTRO
        // =====================================================

        const resultado =
            [];


        for (
            const item
            of itensConsolidados
        ) {

            // =============================================
            // SEM SKU
            // =============================================

            if (
                !item.sku ||
                item.sku ===
                    'SEM_SKU' ||
                item.sku ===
                    'N/A'
            ) {

                resultado.push({

                    ...item,

                    encontrado:
                        false,

                    motivo:
                        'Venda sem SKU'
                });

                continue;
            }


            // =============================================
            // BUSCAR PELOS 8 PRIMEIROS CARACTERES
            // =============================================

            const {
                produto,
                error
            } =
                await buscarProdutoEstoquePorSkuNFE(
                    item.sku
                );


            if (
                error ||
                !produto
            ) {

                resultado.push({

                    ...item,

                    encontrado:
                        false,

                    motivo:
                        `SKU não cadastrado pela chave ${chaveCadastroSkuNFE(item.sku)}`
                });

                continue;
            }


            // =============================================
            // PRODUTO ENCONTRADO
            //
            // IMPORTANTE:
            // "sku" passa a ser o SKU REAL DO CADASTRO.
            //
            // Isso deixa a baixa, histórico e sync trabalhando
            // com o produto correto.
            // =============================================

            resultado.push({

                ...item,

                sku_detectado:
                    item.sku,

                sku:
                    produto.sku,

                chave_cadastro:
                    chaveCadastroSkuNFE(
                        produto.sku
                    ),

                encontrado:
                    true,

                produto_id:
                    produto.id,

                nome:
                    produto.nome,

                estoque_atual:
                    Number(
                        produto.quantidade ||
                        0
                    ),

                quantidade_venda:
                    Number(
                        item.quantidade_venda ||
                        1
                    )
            });
        }


        // =====================================================
        // TODOS PRECISAM ESTAR CADASTRADOS
        // =====================================================

        const todosEncontrados =
            resultado.length >
                0 &&
            resultado.every(
                item =>
                    item.encontrado ===
                    true
            );


        console.log(
            '✅ [NFE] Resultado final da verificação:',
            {
                status:
                    todosEncontrados
                        ? 'disponivel'
                        : 'sem_cadastro',

                produtos:
                    resultado
            }
        );


        return {

            status:
                todosEncontrados
                    ? 'disponivel'
                    : 'sem_cadastro',

            produtos:
                resultado
        };


    } catch (
        error
    ) {

        console.error(
            '❌ Erro ao verificar estoque:',
            error
        );


        return {

            status:
                'erro',

            produtos:
                []
        };
    }
}

function fecharModalEdicaoProdutos() {
    const modal =
        document.getElementById(
            'modalEdicaoProdutos'
        );
    if (modal) {
        modal.remove();
    }
}

async function confirmarProdutosEditados() {

    console.log(
        '🔵 [confirmarProdutosEditados] MODAL ÚNICO'
    );


    // =====================================================
    // TRAVA IMEDIATA DE CLIQUE
    //
    // IMPORTANTE:
    // Esta trava acontece ANTES de qualquer await.
    // Portanto dois cliques rápidos não conseguem iniciar
    // dois processos.
    // =====================================================

    if (
        window._nfeConfirmacaoCliqueTravada
    ) {

        console.warn(
            '🚫 Clique duplicado bloqueado - confirmação já em andamento'
        );


        showToast(
            '⏳ A emissão já está sendo processada. Aguarde.',
            'warning'
        );


        return;
    }


    window._nfeConfirmacaoCliqueTravada =
        true;


    // =====================================================
    // BOTÃO
    // =====================================================

    const btnConfirmar =
        document.getElementById(
            'confirmarProdutosFinalBtn'
        );


    let textoOriginalBotao =
        '';


    if (
        btnConfirmar
    ) {

        textoOriginalBotao =
            btnConfirmar.innerHTML;


        // Guardar texto original
        if (
            !btnConfirmar.dataset
                .textoOriginalNfe
        ) {

            btnConfirmar.dataset
                .textoOriginalNfe =
                textoOriginalBotao;
        }


        // BLOQUEAR IMEDIATAMENTE
        btnConfirmar.disabled =
            true;


        btnConfirmar.style.pointerEvents =
            'none';


        btnConfirmar.setAttribute(
            'aria-busy',
            'true'
        );


        btnConfirmar.innerHTML = `
            <span class="spinner"></span>
            Processando...
        `;
    }


    try {

        // =====================================================
        // VENDA
        // =====================================================

        const vendaId =
            vendaIdParaEdicao ||
            pendingEmitOrderId;


        if (!vendaId) {

            showToast(
                '❌ ID da venda não encontrado',
                'error'
            );


            return;
        }


        // =====================================================
        // CAPTURAR VALORES VISÍVEIS DA TABELA
        // =====================================================

        document
            .querySelectorAll(
                '#modalEdicaoProdutos #produtosEditaveisBody tr'
            )
            .forEach(
                (
                    row,
                    index
                ) => {

                    if (
                        !produtosEditados[
                            index
                        ]
                    ) {

                        return;
                    }


                    produtosEditados[
                        index
                    ].nome =
                        row.querySelector(
                            '.nome-produto'
                        )?.value.trim() ||
                        'Produto';


                    produtosEditados[
                        index
                    ].sku =
                        row.querySelector(
                            '.sku-produto'
                        )?.value.trim() ||
                        'SEM_SKU';


                    produtosEditados[
                        index
                    ].quantidade =
                        parseFloat(
                            row.querySelector(
                                '.qtd-produto'
                            )?.value
                        ) ||
                        0;


                    produtosEditados[
                        index
                    ].valor_unitario =
                        parseFloat(
                            row.querySelector(
                                '.valor-produto'
                            )?.value
                        ) ||
                        0;


                    produtosEditados[
                        index
                    ].ncm =
                        row.querySelector(
                            '.ncm-produto'
                        )?.value.trim() ||
                        '87149990';
                }
            );


        // =====================================================
        // VALIDAR PRODUTOS
        // =====================================================

        if (
            !produtosEditados ||
            produtosEditados.length ===
                0
        ) {

            showToast(
                '❌ Nenhum produto para emitir',
                'error'
            );


            return;
        }


        const produtoInvalido =
            produtosEditados.find(
                p =>
                    !p.nome ||
                    p.quantidade <=
                        0 ||
                    p.valor_unitario <
                        0
            );


        if (
            produtoInvalido
        ) {

            showToast(
                '⚠️ Revise nome, quantidade e valor dos produtos.',
                'warning'
            );


            return;
        }


        // =====================================================
        // SALVAR NCM
        // =====================================================

        const ncmPromises =
            produtosEditados.map(
                p => {

                    if (
                        p.sku &&
                        p.sku !==
                            'SEM_SKU' &&
                        p.ncm
                    ) {

                        return window
                            .supabaseClient
                            .from(
                                'produto_ncm'
                            )
                            .upsert(
                                {
                                    sku:
                                        p.sku,

                                    ncm:
                                        p.ncm
                                },
                                {
                                    onConflict:
                                        'sku'
                                }
                            );
                    }


                    return Promise
                        .resolve();
                }
            );


        await Promise.all(
            ncmPromises
        );


        // =====================================================
        // PRODUTOS PARA NF-E
        // =====================================================

        window.produtosParaEmissao =
            produtosEditados.map(
                p => ({

                    nome:
                        p.nome ||
                        'Produto',

                    quantidade:
                        p.quantidade ||
                        1,

                    valor_unitario:
                        p.valor_unitario ||
                        0,

                    sku:
                        p.sku ||
                        'SEM_SKU',

                    ncm:
                        p.ncm ||
                        '87149990'
                })
            );


        pendingEmitOrderId =
            vendaId;


        // =====================================================
        // ALTERAR VISUAL PARA EMISSÃO
        // =====================================================

        const btnAtual =
            document.getElementById(
                'confirmarProdutosFinalBtn'
            );


        if (
            btnAtual
        ) {

            btnAtual.disabled =
                true;


            btnAtual.style.pointerEvents =
                'none';


            btnAtual.innerHTML = `
                <span class="spinner"></span>
                Emitindo NF-e...
            `;
        }


        console.log(
            `🔒 Emissão da venda ${vendaId} bloqueada contra clique duplicado`
        );


        // =====================================================
        // EMITIR
        // =====================================================

        await confirmarEmissaoNFE();


    } catch (
        error
    ) {

        console.error(
            '❌ Erro em confirmarProdutosEditados:',
            error
        );


        showToast(
            '❌ Erro ao confirmar produtos: ' +
            error.message,
            'error'
        );


    } finally {

        // =====================================================
        // LIBERAR TRAVA DE CLIQUE
        //
        // Se emitiu com sucesso, o modal já terá sido removido.
        // Se deu erro antes da emissão, o botão volta ao normal.
        // =====================================================

        window._nfeConfirmacaoCliqueTravada =
            false;


        const btnAtual =
            document.getElementById(
                'confirmarProdutosFinalBtn'
            );


        if (
            btnAtual
        ) {

            btnAtual.disabled =
                false;


            btnAtual.style.pointerEvents =
                '';


            btnAtual.setAttribute(
                'aria-busy',
                'false'
            );


            btnAtual.innerHTML =
                btnAtual.dataset
                    .textoOriginalNfe ||
                textoOriginalBotao ||
                `
                    <i class="fas fa-file-invoice"></i>
                    Confirmar e Emitir NF-e
                `;
        }
    }
}

// =========================================================
// EMITIR DEVOLUÇÃO A PARTIR DE UMA NF-E JÁ EMITIDA
// =========================================================

window._abrindoDevolucaoNFE =
    false;


async function abrirDevolucaoNFE(
    chaveAcesso
) {

    // =====================================================
    // EVITAR CLIQUE DUPLO
    // =====================================================

    if (
        window._abrindoDevolucaoNFE
    ) {

        showToast(
            'Aguarde, a devolução já está sendo preparada...',
            'warning'
        );

        return;
    }


    window._abrindoDevolucaoNFE =
        true;


    try {

        // =====================================================
        // CHAVE
        // =====================================================

        const chave =
            String(
                chaveAcesso ||
                ''
            )
                .replace(
                    /\D/g,
                    ''
                );


        if (
            chave.length !==
            44
        ) {

            throw new Error(
                'Chave da NF-e original inválida'
            );
        }


        console.log(
            '↩️ Preparando devolução da NF-e:',
            chave
        );


        showToast(
            'Preparando NF-e de devolução...',
            'info'
        );


        // =====================================================
        // BUSCAR XML DA NF-E ORIGINAL
        // =====================================================

        const responseXML =
            await fetch(
                `${window.API_BASE_URL}/nfe/buscar-xml?chave=${encodeURIComponent(
                    chave
                )}`,
                {
                    method:
                        'GET',

                    headers: {
                        'Accept':
                            'application/json'
                    },

                    cache:
                        'no-store'
                }
            );


        const dadosXML =
            await responseXML
                .json()
                .catch(
                    () => ({})
                );


        if (
            !responseXML.ok ||
            !dadosXML.xml
        ) {

            throw new Error(
                dadosXML.error ||
                'Não foi possível localizar o XML da NF-e original'
            );
        }


        // =====================================================
        // LER XML
        // =====================================================

        const parser =
            new DOMParser();


        const xmlDoc =
            parser.parseFromString(
                dadosXML.xml,
                'application/xml'
            );


        if (
            xmlDoc.querySelector(
                'parsererror'
            )
        ) {

            throw new Error(
                'XML da NF-e original inválido'
            );
        }


        const infNFe =
            xmlDoc.querySelector(
                'infNFe'
            );


        if (!infNFe) {

            throw new Error(
                'Tag infNFe não encontrada no XML'
            );
        }


        // =====================================================
        // NÃO GERAR DEVOLUÇÃO DE UMA DEVOLUÇÃO
        // =====================================================

        const naturezaOriginal =
            infNFe
                .querySelector(
                    'natOp'
                )
                ?.textContent
                ?.trim() ||
            '';


        const finalidadeOriginal =
            infNFe
                .querySelector(
                    'finNFe'
                )
                ?.textContent
                ?.trim() ||
            '1';


        const tpNFOriginal =
            infNFe
                .querySelector(
                    'tpNF'
                )
                ?.textContent
                ?.trim() ||
            '1';


        const naturezaOriginalNormalizada =
            String(
                naturezaOriginal
            )
                .normalize(
                    'NFD'
                )
                .replace(
                    /[\u0300-\u036f]/g,
                    ''
                )
                .toLowerCase();


        if (
            finalidadeOriginal ===
                '4' ||
            naturezaOriginalNormalizada
                .includes(
                    'devolucao'
                ) ||
            tpNFOriginal ===
                '0'
        ) {

            throw new Error(
                'Esta NF-e já é uma nota de entrada/devolução. Selecione a NF-e de venda original.'
            );
        }


        // =====================================================
        // CLIENTE DO XML
        // =====================================================

        const dest =
            infNFe.querySelector(
                'dest'
            );


        if (!dest) {

            throw new Error(
                'Destinatário não encontrado na NF-e original'
            );
        }


        const destEndereco =
            dest.querySelector(
                'enderDest'
            );


        const clienteXML = {

            nome:
                dest
                    .querySelector(
                        'xNome'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            documento:
                String(
                    dest
                        .querySelector(
                            'CPF'
                        )
                        ?.textContent ||

                    dest
                        .querySelector(
                            'CNPJ'
                        )
                        ?.textContent ||

                    ''
                )
                    .replace(
                        /\D/g,
                        ''
                    ),

            logradouro:
                destEndereco
                    ?.querySelector(
                        'xLgr'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            numero:
                destEndereco
                    ?.querySelector(
                        'nro'
                    )
                    ?.textContent
                    ?.trim() ||
                'S/N',

            bairro:
                destEndereco
                    ?.querySelector(
                        'xBairro'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            cidade:
                destEndereco
                    ?.querySelector(
                        'xMun'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            uf:
                String(
                    destEndereco
                        ?.querySelector(
                            'UF'
                        )
                        ?.textContent ||
                    ''
                )
                    .trim()
                    .toUpperCase(),

            cep:
                String(
                    destEndereco
                        ?.querySelector(
                            'CEP'
                        )
                        ?.textContent ||
                    ''
                )
                    .replace(
                        /\D/g,
                        ''
                    )
        };


        if (
            !clienteXML.documento
        ) {

            throw new Error(
                'CPF/CNPJ do cliente não encontrado na NF-e original'
            );
        }


        if (
            !clienteXML.uf ||
            clienteXML.uf.length !==
                2
        ) {

            throw new Error(
                'UF do cliente não encontrada na NF-e original'
            );
        }


        // =====================================================
        // CFOP DA DEVOLUÇÃO
        //
        // Mantém exatamente a regra que seu backend atual
        // já utiliza.
        // =====================================================

        const cfopDevolucao =
            clienteXML.uf ===
                'PR'
                ? '1202'
                : '2202';


        // =====================================================
        // TRANSPORTADORA DO XML
        // =====================================================

        const transp =
            infNFe.querySelector(
                'transp'
            );


        const modFreteOriginal =
            String(
                transp
                    ?.querySelector(
                        'modFrete'
                    )
                    ?.textContent ||
                '9'
            );


        const transporta =
            transp?.querySelector(
                'transporta'
            );


        const transportadoraXML = {

            cnpj:
                String(
                    transporta
                        ?.querySelector(
                            'CNPJ'
                        )
                        ?.textContent ||
                    ''
                )
                    .replace(
                        /\D/g,
                        ''
                    ),

            nome:
                transporta
                    ?.querySelector(
                        'xNome'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            ie:
                transporta
                    ?.querySelector(
                        'IE'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            endereco:
                transporta
                    ?.querySelector(
                        'xEnder'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            cidade:
                transporta
                    ?.querySelector(
                        'xMun'
                    )
                    ?.textContent
                    ?.trim() ||
                '',

            uf:
                transporta
                    ?.querySelector(
                        'UF'
                    )
                    ?.textContent
                    ?.trim() ||
                ''
        };


        // =====================================================
        // PRODUTOS DA NF-E ORIGINAL
        // =====================================================

        const dets =
            Array.from(
                infNFe.querySelectorAll(
                    'det'
                )
            );


        if (
            dets.length ===
            0
        ) {

            throw new Error(
                'Nenhum produto encontrado na NF-e original'
            );
        }


        const produtosXML =
            dets
                .map(
                    det => {

                        const prod =
                            det.querySelector(
                                'prod'
                            );


                        if (!prod) {
                            return null;
                        }


                        const quantidade =
                            parseFloat(
                                prod
                                    .querySelector(
                                        'qCom'
                                    )
                                    ?.textContent ||
                                '0'
                            );


                        const valorUnitario =
                            parseFloat(
                                prod
                                    .querySelector(
                                        'vUnCom'
                                    )
                                    ?.textContent ||
                                '0'
                            );


                        return {

                            nome:
                                prod
                                    .querySelector(
                                        'xProd'
                                    )
                                    ?.textContent
                                    ?.trim() ||
                                'Produto',

                            sku:
                                prod
                                    .querySelector(
                                        'cProd'
                                    )
                                    ?.textContent
                                    ?.trim() ||
                                'SEM_SKU',

                            quantidade:
                                Number.isFinite(
                                    quantidade
                                )
                                    ? quantidade
                                    : 1,

                            valor_unitario:
                                Number.isFinite(
                                    valorUnitario
                                )
                                    ? valorUnitario
                                    : 0,

                            ncm:
                                String(
                                    prod
                                        .querySelector(
                                            'NCM'
                                        )
                                        ?.textContent ||
                                    '87149990'
                                )
                                    .replace(
                                        /\D/g,
                                        ''
                                    )
                                    .substring(
                                        0,
                                        8
                                    ) ||
                                '87149990'
                        };
                    }
                )
                .filter(
                    Boolean
                );


        if (
            produtosXML.length ===
            0
        ) {

            throw new Error(
                'Não foi possível extrair os produtos da NF-e original'
            );
        }


        console.log(
            '📦 Dados extraídos da NF-e original:',
            {
                chave,
                clienteXML,
                cfopDevolucao,
                transportadoraXML,
                modFreteOriginal,
                produtosXML
            }
        );


        // =====================================================
        // ABRIR ABA DE EMISSÃO AVULSA
        //
        // mostrarAbaNFE já chama prepararEmissaoAvulsaNFE(),
        // portanto aguardar até selects/clientes/produtos
        // estarem carregados.
        // =====================================================

        await mostrarAbaNFE(
            'avulsa'
        );


        // =====================================================
        // CLIENTE
        // =====================================================

        let clientes =
            Array.isArray(
                window._clientesAvulsaNFE
            )
                ? window._clientesAvulsaNFE
                : [];


        let clienteCadastro =
            clientes.find(
                cliente => {

                    const documento =
                        String(
                            cliente.documento ||
                            ''
                        )
                            .replace(
                                /\D/g,
                                ''
                            );


                    return (
                        documento ===
                        clienteXML.documento
                    );
                }
            );


        // =====================================================
        // SE O CLIENTE DA NF-E ANTIGA NÃO ESTIVER CADASTRADO,
        // CADASTRAR AUTOMATICAMENTE COM OS DADOS DO XML
        // =====================================================

        if (
            !clienteCadastro
        ) {

            console.log(
                '👤 Cliente não encontrado no cadastro. Criando automaticamente...',
                clienteXML
            );


            const responseCliente =
                await fetch(
                    `${window.API_BASE_URL}/nfe/clientes`,
                    {
                        method:
                            'POST',

                        headers: {
                            'Content-Type':
                                'application/json'
                        },

                        body:
                            JSON.stringify(
                                clienteXML
                            )
                    }
                );


            const resultadoCliente =
                await responseCliente
                    .json()
                    .catch(
                        () => ({})
                    );


            if (
                !responseCliente.ok ||
                resultadoCliente.success ===
                    false
            ) {

                throw new Error(
                    resultadoCliente.error ||
                    'Não foi possível cadastrar automaticamente o cliente da devolução'
                );
            }


            // Recarregar a lista local
            await carregarClientesAvulsaNFE();


            clientes =
                Array.isArray(
                    window._clientesAvulsaNFE
                )
                    ? window._clientesAvulsaNFE
                    : [];


            clienteCadastro =
                clientes.find(
                    cliente =>

                        String(
                            cliente.documento ||
                            ''
                        )
                            .replace(
                                /\D/g,
                                ''
                            ) ===
                        clienteXML.documento
                );
        }


        if (
            !clienteCadastro
        ) {

            throw new Error(
                `Cliente ${clienteXML.nome} não pôde ser localizado no cadastro`
            );
        }


        selecionarClienteAvulsaNFE(
            clienteCadastro.id
        );


        // =====================================================
        // NATUREZA DA OPERAÇÃO
        // =====================================================

        const naturezaSelect =
            document.getElementById(
                'avulsaNatOp'
            );


        if (!naturezaSelect) {

            throw new Error(
                'Campo Natureza da Operação não encontrado'
            );
        }


        const opcaoDevolucao =
            Array
                .from(
                    naturezaSelect.options
                )
                .find(
                    option => {

                        const texto =
                            String(
                                option.value ||
                                option.textContent ||
                                ''
                            )
                                .normalize(
                                    'NFD'
                                )
                                .replace(
                                    /[\u0300-\u036f]/g,
                                    ''
                                )
                                .trim()
                                .toLowerCase();


                        return (
                            texto ===
                            'entrada de devolucao'
                        );
                    }
                );


        if (
            !opcaoDevolucao
        ) {

            throw new Error(
                'Natureza "Entrada de Devolução" não encontrada. Cadastre/ative essa Natureza na aba Cadastros.'
            );
        }


        naturezaSelect.value =
            opcaoDevolucao.value;


        naturezaSelect.dispatchEvent(
            new Event(
                'change',
                {
                    bubbles:
                        true
                }
            )
        );


        // =====================================================
        // CFOP
        // =====================================================

        const cfopSelect =
            document.getElementById(
                'avulsaCfop'
            );


        if (!cfopSelect) {

            throw new Error(
                'Campo CFOP não encontrado'
            );
        }


        const opcaoCFOP =
            Array
                .from(
                    cfopSelect.options
                )
                .find(
                    option =>

                        String(
                            option.value ||
                            ''
                        )
                            .replace(
                                /\D/g,
                                ''
                            ) ===
                        cfopDevolucao
                );


        if (
            !opcaoCFOP
        ) {

            throw new Error(
                `CFOP ${cfopDevolucao} não encontrado. Cadastre/ative esse CFOP na aba Cadastros.`
            );
        }


        cfopSelect.value =
            opcaoCFOP.value;


        // =====================================================
        // CHAVE DA NF-E ORIGINAL
        // =====================================================

        garantirCampoReferenciaDevolucaoAvulsaNFE();


        atualizarCampoReferenciaDevolucaoAvulsaNFE();


        const campoChave =
            document.getElementById(
                'avulsaChaveNFeReferenciada'
            );


        if (!campoChave) {

            throw new Error(
                'Campo da chave da NF-e referenciada não encontrado'
            );
        }


        campoChave.value =
            chave;


        campoChave.dispatchEvent(
            new Event(
                'input',
                {
                    bubbles:
                        true
                }
            )
        );


        // =====================================================
        // MODALIDADE DE FRETE
        // =====================================================

        const modFreteSelect =
            document.getElementById(
                'avulsaModFrete'
            );


        if (
            modFreteSelect
        ) {

            const valoresPermitidos =
                [
                    '0',
                    '1',
                    '2',
                    '9'
                ];


            modFreteSelect.value =
                valoresPermitidos.includes(
                    modFreteOriginal
                )
                    ? modFreteOriginal
                    : '9';
        }


        // =====================================================
        // TRANSPORTADORA
        // =====================================================

        const transportadoraSelect =
            document.getElementById(
                'avulsaTransportadoraId'
            );


        let transportadoraEncontrada =
            null;


        if (
            transportadoraSelect &&
            (
                transportadoraXML.cnpj ||
                transportadoraXML.nome
            )
        ) {

            try {

                const responseTransportadoras =
                    await fetch(
                        `${window.API_BASE_URL}/nfe/transportadoras`,
                        {
                            cache:
                                'no-store'
                        }
                    );


                const dadosTransportadoras =
                    await responseTransportadoras
                        .json();


                const transportadoras =
                    Array.isArray(
                        dadosTransportadoras
                            .transportadoras
                    )
                        ? dadosTransportadoras
                            .transportadoras
                        : [];


                // Primeiro por CNPJ
                if (
                    transportadoraXML.cnpj
                ) {

                    transportadoraEncontrada =
                        transportadoras.find(
                            transportadora =>

                                String(
                                    transportadora.cnpj ||
                                    ''
                                )
                                    .replace(
                                        /\D/g,
                                        ''
                                    ) ===
                                transportadoraXML.cnpj
                        );
                }


                // Fallback pelo nome
                if (
                    !transportadoraEncontrada &&
                    transportadoraXML.nome
                ) {

                    const nomeXML =
                        String(
                            transportadoraXML.nome
                        )
                            .trim()
                            .toLowerCase();


                    transportadoraEncontrada =
                        transportadoras.find(
                            transportadora =>

                                String(
                                    transportadora.nome ||
                                    ''
                                )
                                    .trim()
                                    .toLowerCase() ===
                                nomeXML
                        );
                }


                if (
                    transportadoraEncontrada
                ) {

                    transportadoraSelect.value =
                        String(
                            transportadoraEncontrada.id
                        );


                    console.log(
                        '🚚 Transportadora da devolução selecionada:',
                        transportadoraEncontrada.nome
                    );

                } else {

                    transportadoraSelect.value =
                        '';


                    console.warn(
                        '⚠️ Transportadora da NF-e original não encontrada no cadastro:',
                        transportadoraXML
                    );
                }


            } catch (
                error
            ) {

                console.warn(
                    '⚠️ Não foi possível localizar automaticamente a transportadora:',
                    error
                );
            }
        }


        // =====================================================
        // PRODUTOS
        // =====================================================

        const produtosEstoque =
            Array.isArray(
                window._produtosEstoqueAvulsaNFE
            )
                ? window._produtosEstoqueAvulsaNFE
                : [];


        window._itensAvulsaNFE =
            produtosXML.map(
                produtoXML => {

                    const skuXML =
                        String(
                            produtoXML.sku ||
                            ''
                        )
                            .trim();


                    const produtoCadastro =
                        produtosEstoque.find(
                            produto =>

                                String(
                                    produto.sku ||
                                    ''
                                )
                                    .trim() ===
                                skuXML
                        );


                    return {

                        produto_id:
                            produtoCadastro
                                ?.id ||
                            null,

                        nome:
                            produtoXML.nome,

                        sku:
                            produtoXML.sku,

                        quantidade:
                            produtoXML.quantidade,

                        valor_unitario:
                            produtoXML.valor_unitario,

                        ncm:
                            produtoXML.ncm,

                        estoque_atual:
                            Number(
                                produtoCadastro
                                    ?.quantidade ||
                                0
                            )
                    };
                }
            );


        renderizarProdutosAvulsaNFE();


        atualizarProdutosJSONAvulsaNFE();


        // =====================================================
        // LOG FINAL
        // =====================================================

        console.log(
            '✅ DEVOLUÇÃO PREENCHIDA AUTOMATICAMENTE:',
            {
                chave_original:
                    chave,

                cliente:
                    clienteCadastro,

                natureza:
                    naturezaSelect.value,

                cfop:
                    cfopSelect.value,

                modalidade_frete:
                    modFreteSelect
                        ?.value,

                transportadora:
                    transportadoraEncontrada
                        ?.nome ||
                    null,

                produtos:
                    window
                        ._itensAvulsaNFE
            }
        );


        // =====================================================
        // ROLAR PARA O TOPO DO FORMULÁRIO
        // =====================================================

        document
            .getElementById(
                'abaAvulsa'
            )
            ?.scrollIntoView({
                behavior:
                    'smooth',

                block:
                    'start'
            });


        showToast(
            '✅ Devolução preparada. Confira os dados e clique em Emitir NF-e.',
            'success'
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro preparando devolução:',
            error
        );


        showToast(
            `Erro ao preparar devolução: ${error.message}`,
            'error'
        );


    } finally {

        window._abrindoDevolucaoNFE =
            false;
    }
}


window.abrirDevolucaoNFE =
    abrirDevolucaoNFE;

// =========================================================
// NCM POR SKU
// =========================================================

async function buscarNCMporSKU(sku) {
    if (!sku || sku === 'SEM_SKU' || sku === 'N/A') return null;
    try {
        const { data, error } = await window.supabaseClient
            .from('produto_ncm')
            .select('ncm')
            .eq('sku', sku)
            .maybeSingle();
        if (error) throw error;
        return data?.ncm || null;
    } catch (error) {
        console.warn(`⚠️ Erro ao buscar NCM para SKU ${sku}:`, error.message);
        return null;
    }
}

async function salvarNCMporSKU(sku, ncm) {
    if (!sku || sku === 'SEM_SKU' || sku === 'N/A' || !ncm) return;
    try {
        const { error } = await window.supabaseClient
            .from('produto_ncm')
            .upsert({ sku, ncm }, { onConflict: 'sku' });
        if (error) throw error;
        console.log(`✅ NCM ${ncm} salvo para SKU ${sku}`);
    } catch (error) {
        console.warn(`⚠️ Erro ao salvar NCM para SKU ${sku}:`, error.message);
    }
}

function extrairSkuEQuantidade(
    skuComPrefixo
) {

    if (
        !skuComPrefixo ||
        skuComPrefixo === 'SEM_SKU' ||
        skuComPrefixo === 'N/A'
    ) {

        return {
            sku: skuComPrefixo,
            multiplicador: 1,
            skuOriginal: skuComPrefixo
        };
    }

    const texto =
        String(
            skuComPrefixo
        ).trim();

    const match =
        texto.match(/^(\d{3})(.+)$/);

    if (match) {
        let multiplicador =
            parseInt(
                match[1],
                10
            );

        let skuReal =
            String(match[2] || '').trim();

        if (
            !Number.isFinite(
                multiplicador) ||
            multiplicador <= 0
        ) {

            multiplicador = 1;
        }

        if (
            skuReal.startsWith('/') ||
            skuReal.startsWith('\\')
        ) {

            skuReal = skuReal.substring(1
                );
        }

        return {
            sku: skuReal,
            multiplicador,
            skuOriginal: texto
        };
    }

        return {
            sku: texto,
            multiplicador: 1,
            skuOriginal: texto
        };
}

function decomporSkuCompostoNFE(
    skuOriginal,
    quantidadeVenda = 1
) {

    if (
        !skuOriginal ||
        skuOriginal === 'SEM_SKU' ||
        skuOriginal === 'N/A'
    ) {

        return [];
    }

    const quantidadeAnuncio =
        Number(
            quantidadeVenda ||
            1
        );

    const partes =
        String(
            skuOriginal
        )
            .split('.')
            .map(
                parte =>
                    parte.trim()
            )
            .filter(Boolean);

    const resultado =
        [];

    for (
        const parte
        of partes
    ) {

        const {
            sku,
            multiplicador
        } =
            extrairSkuEQuantidade(
                parte
            );

        if (
            !sku ||
            sku === 'SEM_SKU' ||
            sku === 'N/A'
        ) {

            continue;
        }


        resultado.push({

            sku,
            sku_original: parte,
            sku_anuncio:
                String(
                    skuOriginal
                ),

            multiplicador:
                Number(
                    multiplicador ||
                    1
                ),

            quantidade_venda:
                quantidadeAnuncio *
                Number(multiplicador || 1
                )
        });
    }

    return resultado;
}

// =========================================================
// NORMALIZAR SKU PARA CONSULTA NO CADASTRO
// =========================================================

function normalizarSkuCadastroNFE(sku) {

    return String(
        sku || ''
    )
        .trim()
        .toUpperCase();
}


// =========================================================
// CHAVE DO PRODUTO = 8 PRIMEIROS CARACTERES DO SKU REAL
// =========================================================

function chaveCadastroSkuNFE(sku) {

    return normalizarSkuCadastroNFE(
        sku
    ).substring(
        0,
        8
    );
}


// =========================================================
// BUSCAR PRODUTO NO ESTOQUE PELOS 8 PRIMEIROS CARACTERES
// =========================================================

async function buscarProdutoEstoquePorSkuNFE(
    skuFisico
) {

    const skuNormalizado =
        normalizarSkuCadastroNFE(
            skuFisico
        );


    const chave =
        chaveCadastroSkuNFE(
            skuFisico
        );


    if (!chave) {

        return {
            produto: null,
            error: null
        };
    }


    console.log(
        `🔎 [NFE] Buscando produto: SKU=${skuFisico} | chave=${chave}`
    );


    try {

        const {
            data,
            error
        } =
            await window
                .supabaseClient
                .from(
                    'produtos_estoque'
                )
                .select(`
                    id,
                    sku,
                    nome,
                    quantidade
                `)
                .ilike(
                    'sku',
                    `${chave}%`
                )
                .limit(
                    50
                );


        if (error) {

            console.error(
                `❌ [NFE] Erro buscando SKU ${skuFisico}:`,
                error
            );

            return {
                produto: null,
                error
            };
        }


        // =====================================================
        // GARANTIR QUE OS 8 PRIMEIROS CARACTERES SÃO IGUAIS
        // =====================================================

        const candidatos =
            (
                Array.isArray(data)
                    ? data
                    : []
            )
                .filter(
                    produto =>
                        chaveCadastroSkuNFE(
                            produto.sku
                        ) ===
                        chave
                );


        if (
            candidatos.length ===
            0
        ) {

            console.warn(
                `⚠️ [NFE] Nenhum produto encontrado para a chave ${chave}`
            );

            return {
                produto: null,
                error: null
            };
        }


        // =====================================================
        // SE EXISTIR O SKU COMPLETO EXATO, ELE TEM PRIORIDADE
        // =====================================================

        const produtoExato =
            candidatos.find(
                produto =>
                    normalizarSkuCadastroNFE(
                        produto.sku
                    ) ===
                    skuNormalizado
            );


        const produto =
            produtoExato ||
            candidatos[0];


        if (
            candidatos.length >
                1 &&
            !produtoExato
        ) {

            console.warn(
                `⚠️ [NFE] Mais de um produto possui a chave ${chave}. Utilizando:`,
                produto
            );
        }


        console.log(
            `✅ [NFE] Produto encontrado pela chave ${chave}:`,
            {
                skuVenda:
                    skuFisico,

                skuCadastro:
                    produto.sku,

                produtoId:
                    produto.id,

                nome:
                    produto.nome,

                quantidade:
                    produto.quantidade
            }
        );


        return {
            produto,
            error: null
        };


    } catch (
        error
    ) {

        console.error(
            `❌ [NFE] Erro inesperado buscando ${skuFisico}:`,
            error
        );


        return {
            produto: null,
            error
        };
    }
}

// =========================================================
// FUNÇÃO PARA ENVIAR XML PARA O MERCADO LIVRE
// =========================================================

async function enviarXMLparaMercadoLivre(orderId, xmlContent, token) {
    console.log(`📤 Enviando XML da NF-e para venda ${orderId}...`);
    
    try {
        if (!token) {
            token = localStorage.getItem('ml_access_token');
            if (!token && typeof window.getValidToken === 'function') {
                const tokenData = await window.getValidToken();
                token = tokenData?.access_token;
            }
        }
        
        if (!token) {
            console.warn('⚠️ Token ML não disponível');
            return { success: false, error: 'Token ML não disponível' };
        }

        // 🔥 VERIFICAR SE JÁ EXISTE INVOICE
        const checkUrl = `https://api.mercadolibre.com/users/415176739/invoices/orders/${orderId}`;
        const checkProxyUrl = `${window.WORKER_URL}/api/ml/proxy?url=${encodeURIComponent(checkUrl)}&token=${encodeURIComponent(token)}`;
        
        try {
            const checkResponse = await fetch(checkProxyUrl);
            if (checkResponse.ok) {
                const existing = await checkResponse.json();
                if (Array.isArray(existing) && existing.length > 0) {
                    const authorized = existing.find(inv => inv.status === 'authorized' || inv.status === 'AUTHORIZED');
                    if (authorized) {
                        console.log('ℹ️ Já existe NF-e autorizada para esta venda.');
                        return { success: true, message: 'NF-e já vinculada', existing: true };
                    }
                }
            }
        } catch (e) {
            console.warn('⚠️ Erro ao verificar invoice existente:', e);
        }

        const invoiceUrl = `https://api.mercadolibre.com/users/415176739/invoices`;
        
        const payload = {
            order_id: parseInt(orderId),
            transaction_type: 'SALE',
            xml: xmlContent
        };
        
        console.log('📤 Enviando para:', invoiceUrl);
        console.log('📤 Order ID:', orderId);
        console.log('📤 Tamanho do XML:', xmlContent?.length || 0);
        
        // TENTATIVA 1: JSON via Worker
        try {
            const proxyUrl = `${window.WORKER_URL}/api/ml/proxy?url=${encodeURIComponent(invoiceUrl)}&token=${encodeURIComponent(token)}&method=POST`;
            
            const response = await fetch(proxyUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify(payload)
            });
            
            if (response.ok) {
                const result = await response.json();
                console.log('✅ NF-e enviada com sucesso!', result);
                return { success: true, invoice: result };
            } else {
                const errorText = await response.text();
                console.warn('⚠️ JSON falhou:', response.status, errorText);
                
                // TENTATIVA 2: FormData
                console.log('🔄 Tentando método alternativo (FormData)...');
                
                const formData = new FormData();
                const xmlBlob = new Blob([xmlContent], { type: 'application/xml' });
                formData.append('invoice', xmlBlob, `NFE_${orderId}.xml`);
                formData.append('order_id', orderId);
                
                const formProxyUrl = `${window.WORKER_URL}/api/ml/proxy?url=${encodeURIComponent(invoiceUrl)}&token=${encodeURIComponent(token)}&method=POST`;
                const formResponse = await fetch(formProxyUrl, {
                    method: 'POST',
                    body: formData
                });
                
                if (formResponse.ok) {
                    const result = await formResponse.json();
                    console.log('✅ NF-e enviada via FormData!', result);
                    return { success: true, invoice: result };
                } else {
                    const formError = await formResponse.text();
                    console.error('❌ FormData falhou:', formError);
                    return { success: false, error: `FormData falhou: ${formError}` };
                }
            }
        } catch (error) {
            console.error('❌ Erro ao enviar NF-e:', error);
            return { success: false, error: error.message };
        }
        
    } catch (error) {
        console.error('❌ Erro ao enviar NF-e para ML:', error);
        return { success: false, error: error.message };
    }
}

async function mostrarAbaNFE(
    aba
) {

    garantirEstruturaCadastrosNFE();


    // =====================================================
    // CLIENTES / TRANSPORTADORAS SÃO SOMENTE CONSULTA
    // =====================================================

    removerBotoesCadastroAbasConsultaNFE();


    const nomesAbas = [
        'Vendas',
        'Emitidas',
        'Avulsa',
        'Transportadoras',
        'Clientes',
        'Cadastros'
    ];


    // =====================================================
    // ESCONDER TODAS
    // =====================================================

    nomesAbas.forEach(
        nome => {

            const elemento =
                document.getElementById(
                    `aba${nome}`
                );


            if (
                elemento
            ) {

                elemento
                    .classList
                    .add(
                        'hidden'
                    );
            }
        }
    );


    // =====================================================
    // MOSTRAR ABA
    // =====================================================

    const nomeCapitalizado =
        aba.charAt(0)
            .toUpperCase() +
        aba.slice(1);


    const target =
        document.getElementById(
            `aba${nomeCapitalizado}`
        );


    if (
        target
    ) {

        target
            .classList
            .remove(
                'hidden'
            );
    }


    // =====================================================
    // BOTÕES SUPERIORES
    // =====================================================

    nomesAbas.forEach(
        nome => {

            const btn =
                document.getElementById(
                    `tab${nome}Btn`
                );


            if (!btn) {

                return;
            }


            if (
                nome.toLowerCase() ===
                aba
            ) {

                btn.classList.remove(
                    'btn-outline-primary'
                );

                btn.classList.add(
                    'btn-primary'
                );


            } else {

                btn.classList.remove(
                    'btn-primary'
                );

                btn.classList.add(
                    'btn-outline-primary'
                );
            }
        }
    );


    // =====================================================
    // VENDAS
    // =====================================================

    if (
        aba ===
        'vendas'
    ) {

        inicializarFiltroDataNFE();


        await carregarVendasPendentes(
            false
        );


        return;
    }


    // =====================================================
    // PARAR MONITOR
    // =====================================================

    if (
        typeof pararMonitorVendasNovasNFE ===
        'function'
    ) {

        pararMonitorVendasNovasNFE();
    }


    // =====================================================
    // EMITIDAS
    // =====================================================

    if (
        aba ===
        'emitidas'
    ) {

        await carregarNFesEmitidas();

        return;
    }


    // =====================================================
    // AVULSA
    // =====================================================

    if (
        aba ===
        'avulsa'
    ) {

        await prepararEmissaoAvulsaNFE();

        return;
    }


    // =====================================================
    // TRANSPORTADORAS
    // =====================================================

    if (
        aba ===
        'transportadoras'
    ) {

        await carregarTransportadoras();

        removerBotoesCadastroAbasConsultaNFE();

        return;
    }


    // =====================================================
    // CLIENTES
    // =====================================================

    if (
        aba ===
        'clientes'
    ) {

        await carregarClientes();

        removerBotoesCadastroAbasConsultaNFE();

        return;
    }


    // =====================================================
    // CADASTROS
    // =====================================================

    if (
        aba ===
        'cadastros'
    ) {

        await carregarCadastrosNFE();

        return;
    }
}

// =========================================================
// NF-e AVULSA - ESTRUTURA E CARREGAMENTOS
// =========================================================

window._clientesAvulsaNFE =
    window._clientesAvulsaNFE ||
    [];


// =========================================================
// ESCAPAR HTML
// Independente das funções de Cadastros
// =========================================================

function escaparHTMLAvulsaNFE(valor) {

    return String(
        valor ??
        ''
    )
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}


function garantirEstruturaAvulsaNFE() {

    const aba =
        document.getElementById(
            'abaAvulsa'
        );


    if (!aba) {

        console.error(
            '❌ abaAvulsa não encontrada'
        );

        return false;
    }


    // =====================================================
    // CLIENTE PESQUISÁVEL
    // =====================================================

    let campoBusca =
        aba.querySelector(
            '#avulsaClienteBusca'
        );


    if (!campoBusca) {

        const campoClienteAntigo =
            aba.querySelector(
                '#avulsaClienteId'
            );


        if (campoClienteAntigo) {

            const wrapper =
                document.createElement(
                    'div'
                );


            wrapper.id =
                'avulsaClientePesquisaWrapper';


            wrapper.style.cssText = `
                position:relative;
                width:100%;
            `;


            wrapper.innerHTML = `

                <input
                    type="text"
                    id="avulsaClienteBusca"
                    class="form-control"
                    placeholder="Digite o nome, CPF ou CNPJ do cliente..."
                    autocomplete="off"
                >

                <input
                    type="hidden"
                    id="avulsaClienteId"
                    value=""
                >

                <div
                    id="avulsaClienteResultados"
                    style="
                        display:none;
                        position:absolute;
                        top:100%;
                        left:0;
                        right:0;
                        z-index:12000;
                        background:#fff;
                        border:1px solid #ced4da;
                        border-top:none;
                        border-radius:0 0 6px 6px;
                        max-height:300px;
                        overflow-y:auto;
                        box-shadow:0 5px 15px rgba(0,0,0,.15);
                    "
                ></div>

                <div
                    id="avulsaClienteSelecionado"
                    style="
                        display:none;
                        margin-top:8px;
                        padding:10px 12px;
                        background:#eaf7ee;
                        border:1px solid #b9dfc3;
                        border-radius:6px;
                    "
                ></div>
            `;


            campoClienteAntigo.replaceWith(
                wrapper
            );

        } else {

            console.warn(
                '⚠️ Campo de cliente não encontrado'
            );
        }
    }


    // =====================================================
    // CFOP
    //
    // Se atualmente for INPUT, será convertido em SELECT.
    // =====================================================

    garantirSelectAvulsaNFE(
        'avulsaCfop',
        'CFOP *',
        'Carregando CFOPs...'
    );


    // =====================================================
    // NATUREZA DA OPERAÇÃO
    //
    // Se atualmente for INPUT, será convertido em SELECT.
    // =====================================================

    garantirSelectAvulsaNFE(
        'avulsaNatOp',
        'Natureza da Operação *',
        'Carregando Naturezas...'
    );

    // =====================================================
    // CAMPO DE NF-E REFERENCIADA PARA DEVOLUÇÃO
    // =====================================================

    garantirCampoReferenciaDevolucaoAvulsaNFE();


    // =====================================================
    // TRANSPORTADORA
    // =====================================================

    garantirSelectAvulsaNFE(
        'avulsaTransportadoraId',
        'Transportadora',
        'Carregando transportadoras...'
    );


    // =====================================================
    // MODALIDADE DE FRETE
    // =====================================================

    let modalidade =
        aba.querySelector(
            '#avulsaModFrete'
        );


    if (
        modalidade &&
        modalidade.tagName !==
            'SELECT'
    ) {

        const select =
            document.createElement(
                'select'
            );


        select.id =
            'avulsaModFrete';

        select.className =
            modalidade.className ||
            'form-control';


        select.innerHTML = `

            <option value="9">
                9 - Sem ocorrência de transporte
            </option>

            <option value="0">
                0 - Frete por conta do emitente
            </option>

            <option value="1">
                1 - Frete por conta do destinatário
            </option>

            <option value="2">
                2 - Frete por conta de terceiros
            </option>
        `;


        modalidade.replaceWith(
            select
        );


        modalidade =
            select;
    }


    if (!modalidade) {

        const grupo =
            document.createElement(
                'div'
            );


        grupo.className =
            'form-group';


        grupo.innerHTML = `

            <label>
                Modalidade do Frete
            </label>

            <select
                id="avulsaModFrete"
                class="form-control"
            >

                <option value="9">
                    9 - Sem ocorrência de transporte
                </option>

                <option value="0">
                    0 - Frete por conta do emitente
                </option>

                <option value="1">
                    1 - Frete por conta do destinatário
                </option>

                <option value="2">
                    2 - Frete por conta de terceiros
                </option>

            </select>
        `;


        const produtos =
            aba.querySelector(
                '#avulsaProdutos'
            );


        const grupoProdutos =
            produtos?.closest(
                '.form-group'
            ) ||
            produtos?.parentElement;


        if (
            grupoProdutos &&
            grupoProdutos.parentElement
        ) {

            grupoProdutos
                .parentElement
                .insertBefore(
                    grupo,
                    grupoProdutos
                );

        } else {

            aba.appendChild(
                grupo
            );
        }
    }


    console.log(
        '✅ Estrutura da NF-e avulsa pronta:',
        {
            cliente:
                Boolean(
                    document.getElementById(
                        'avulsaClienteBusca'
                    )
                ),

            cfop:
                document.getElementById(
                    'avulsaCfop'
                )?.tagName,

            natureza:
                document.getElementById(
                    'avulsaNatOp'
                )?.tagName,

            transportadora:
                document.getElementById(
                    'avulsaTransportadoraId'
                )?.tagName
        }
    );


    return true;
}


// =========================================================
// CARREGAR CLIENTES
// =========================================================

async function carregarClientesAvulsaNFE() {

    const busca =
        document.getElementById(
            'avulsaClienteBusca'
        );


    const campoId =
        document.getElementById(
            'avulsaClienteId'
        );


    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );


    if (
        !busca ||
        !campoId ||
        !resultados
    ) {

        console.error(
            '❌ Estrutura do cliente avulso não encontrada'
        );

        return false;
    }


    try {

        busca.disabled =
            true;


        busca.placeholder =
            'Carregando clientes...';


        const response =
            await fetch(
                `${window.API_BASE_URL}/nfe/clientes`,
                {
                    method:
                        'GET',

                    headers: {
                        'Accept':
                            'application/json'
                    },

                    cache:
                        'no-store'
                }
            );


        if (!response.ok) {

            throw new Error(
                `HTTP ${response.status}`
            );
        }


        const data =
            await response.json();


        if (
            data.success ===
            false
        ) {

            throw new Error(
                data.error ||
                'Erro ao carregar clientes'
            );
        }


        window._clientesAvulsaNFE =
            Array.isArray(
                data.clientes
            )
                ? data.clientes
                : [];


        busca.disabled =
            false;


        busca.placeholder =
            'Digite o nome, CPF ou CNPJ do cliente...';


        // Remove evento anterior
        busca.oninput =
            null;


        busca.onfocus =
            null;


        // Pesquisa
        busca.oninput =
            function () {

                // Se começar a digitar depois de selecionar,
                // limpar ID selecionado.
                campoId.value =
                    '';


                const selecionado =
                    document.getElementById(
                        'avulsaClienteSelecionado'
                    );


                if (selecionado) {

                    selecionado.style.display =
                        'none';

                    selecionado.innerHTML =
                        '';
                }


                pesquisarClienteAvulsaNFE(
                    this.value
                );
            };


        busca.onfocus =
            function () {

                if (
                    this.value.trim()
                ) {

                    pesquisarClienteAvulsaNFE(
                        this.value
                    );
                }
            };


        console.log(
            `✅ ${window._clientesAvulsaNFE.length} cliente(s) carregado(s)`
        );


        return true;


    } catch (error) {

        console.error(
            '❌ Erro carregando clientes da NF-e avulsa:',
            error
        );


        busca.disabled =
            false;


        busca.placeholder =
            'Erro ao carregar clientes';


        return false;
    }
}


// =========================================================
// PESQUISAR CLIENTE
// =========================================================

function pesquisarClienteAvulsaNFE(
    termo
) {

    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );


    if (!resultados) {

        return;
    }


    const texto =
        String(
            termo ||
            ''
        )
            .trim()
            .toLowerCase();


    if (
        texto.length ===
        0
    ) {

        resultados.style.display =
            'none';


        resultados.innerHTML =
            '';


        return;
    }


    const numeros =
        texto.replace(
            /\D/g,
            ''
        );


    const clientes =
        Array.isArray(
            window._clientesAvulsaNFE
        )
            ? window._clientesAvulsaNFE
            : [];


    const filtrados =
        clientes
            .filter(
                cliente => {

                    const nome =
                        String(
                            cliente.nome ||
                            ''
                        )
                            .toLowerCase();


                    const documento =
                        String(
                            cliente.documento ||
                            ''
                        )
                            .replace(
                                /\D/g,
                                ''
                            );


                    const cidade =
                        String(
                            cliente.cidade ||
                            ''
                        )
                            .toLowerCase();


                    return (

                        nome.includes(
                            texto
                        ) ||

                        cidade.includes(
                            texto
                        ) ||

                        (
                            numeros.length >
                                0 &&
                            documento.includes(
                                numeros
                            )
                        )
                    );
                }
            )
            .slice(
                0,
                20
            );


    if (
        filtrados.length ===
        0
    ) {

        resultados.innerHTML = `

            <div
                style="
                    padding:12px;
                    text-align:center;
                    color:#6c757d;
                "
            >
                Nenhum cliente encontrado
            </div>
        `;


        resultados.style.display =
            'block';


        return;
    }


    resultados.innerHTML =
        filtrados
            .map(
                cliente => `

                    <div
                        style="
                            padding:10px 12px;
                            cursor:pointer;
                            border-bottom:1px solid #eee;
                        "
                        onmouseover="
                            this.style.background='#f5f5f5'
                        "
                        onmouseout="
                            this.style.background='#fff'
                        "
                        onclick="
                            selecionarClienteAvulsaNFE(
                                ${Number(cliente.id)}
                            )
                        "
                    >

                        <div
                            style="
                                font-weight:600;
                            "
                        >
                            ${escaparHTMLAvulsaNFE(
                                cliente.nome ||
                                'Cliente'
                            )}
                        </div>


                        <div
                            style="
                                font-size:12px;
                                color:#6c757d;
                            "
                        >

                            ${
                                escaparHTMLAvulsaNFE(
                                    cliente.documento ||
                                    'Sem documento'
                                )
                            }

                            ${
                                cliente.cidade
                                    ? ` • ${escaparHTMLAvulsaNFE(
                                        cliente.cidade
                                    )}/${escaparHTMLAvulsaNFE(
                                        cliente.uf ||
                                        ''
                                    )}`
                                    : ''
                            }

                        </div>

                    </div>
                `
            )
            .join(
                ''
            );


    resultados.style.display =
        'block';
}


// =========================================================
// SELECIONAR CLIENTE
// =========================================================

function selecionarClienteAvulsaNFE(
    clienteId
) {

    const cliente =
        window._clientesAvulsaNFE
            .find(
                item =>
                    String(
                        item.id
                    ) ===
                    String(
                        clienteId
                    )
            );


    if (!cliente) {

        showToast(
            'Cliente não encontrado',
            'warning'
        );

        return;
    }


    const campoId =
        document.getElementById(
            'avulsaClienteId'
        );


    const busca =
        document.getElementById(
            'avulsaClienteBusca'
        );


    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );


    const selecionado =
        document.getElementById(
            'avulsaClienteSelecionado'
        );


    if (campoId) {

        campoId.value =
            String(
                cliente.id
            );
    }


    if (busca) {

        busca.value =
            cliente.nome ||
            '';
    }


    if (resultados) {

        resultados.innerHTML =
            '';

        resultados.style.display =
            'none';
    }


    if (selecionado) {

        selecionado.innerHTML = `

            <div
                style="
                    display:flex;
                    align-items:center;
                    justify-content:space-between;
                    gap:10px;
                "
            >

                <div>

                    <strong>
                        <i class="fas fa-check-circle"></i>
                        ${escaparHTMLAvulsaNFE(
                            cliente.nome ||
                            ''
                        )}
                    </strong>

                    <div
                        style="
                            margin-top:3px;
                            color:#6c757d;
                            font-size:12px;
                        "
                    >

                        ${escaparHTMLAvulsaNFE(
                            cliente.documento ||
                            ''
                        )}

                        ${
                            cliente.cidade
                                ? ` • ${escaparHTMLAvulsaNFE(
                                    cliente.cidade
                                )}/${escaparHTMLAvulsaNFE(
                                    cliente.uf ||
                                    ''
                                )}`
                                : ''
                        }

                    </div>

                </div>


                <button
                    type="button"
                    class="btn btn-sm btn-secondary"
                    onclick="limparClienteSelecionadoAvulsaNFE()"
                >
                    Trocar
                </button>

            </div>
        `;


        selecionado.style.display =
            'block';
    }


    console.log(
        '✅ Cliente selecionado:',
        cliente.nome,
        cliente.id
    );
}


// =========================================================
// LIMPAR CLIENTE
// =========================================================

function limparClienteSelecionadoAvulsaNFE() {

    const campoId =
        document.getElementById(
            'avulsaClienteId'
        );


    const busca =
        document.getElementById(
            'avulsaClienteBusca'
        );


    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );


    const selecionado =
        document.getElementById(
            'avulsaClienteSelecionado'
        );


    if (campoId) {

        campoId.value =
            '';
    }


    if (busca) {

        busca.value =
            '';

        busca.focus();
    }


    if (resultados) {

        resultados.innerHTML =
            '';

        resultados.style.display =
            'none';
    }


    if (selecionado) {

        selecionado.innerHTML =
            '';

        selecionado.style.display =
            'none';
    }
}


// =========================================================
// CFOP - EXCLUSIVO DA EMISSÃO AVULSA
//
// NÃO DEPENDE DE preencherSelectCFOPNFE()
// =========================================================

async function preencherSelectCFOPAvulsaNFE() {

    const select =
        document.getElementById(
            'avulsaCfop'
        );


    if (!select) {

        console.error(
            '❌ avulsaCfop não encontrado'
        );

        return false;
    }


    try {

        select.disabled =
            true;

            // =====================================================
            // MOSTRAR/OCULTAR CHAVE REFERENCIADA
            // =====================================================

            select.onchange =
                function () {

                    atualizarCampoReferenciaDevolucaoAvulsaNFE();
                };


            atualizarCampoReferenciaDevolucaoAvulsaNFE();


        select.innerHTML = `

            <option value="">
                Carregando CFOPs...
            </option>
        `;


        const {
            data,
            error
        } =
            await window
                .supabaseClient
                .from(
                    'nfe_cfops'
                )
                .select(`
                    id,
                    codigo,
                    descricao,
                    ativo,
                    padrao_avulsa
                `)
                .eq(
                    'ativo',
                    true
                )
                .order(
                    'codigo',
                    {
                        ascending:
                            true
                    }
                );


        if (error) {

            throw error;
        }


        const cfops =
            Array.isArray(
                data
            )
                ? data
                : [];


        if (
            cfops.length ===
            0
        ) {

            select.innerHTML = `

                <option value="">
                    Nenhum CFOP ativo cadastrado
                </option>
            `;


            select.disabled =
                false;


            return false;
        }


        select.innerHTML =
            '<option value="">Selecione o CFOP</option>' +

            cfops
                .map(
                    cfop => `

                        <option
                            value="${escaparHTMLAvulsaNFE(
                                cfop.codigo
                            )}"
                        >
                            ${escaparHTMLAvulsaNFE(
                                cfop.codigo
                            )}
                            -
                            ${escaparHTMLAvulsaNFE(
                                cfop.descricao ||
                                ''
                            )}
                        </option>
                    `
                )
                .join(
                    ''
                );


        const padrao =
            cfops.find(
                cfop =>
                    cfop.padrao_avulsa ===
                    true
            ) ||
            cfops[0];


        select.value =
            padrao.codigo;


        select.disabled =
            false;


        console.log(
            '✅ CFOPs avulsos carregados:',
            cfops.length,
            'Padrão:',
            padrao.codigo
        );


        return true;


    } catch (error) {

        console.error(
            '❌ Erro carregando CFOPs avulsos:',
            error
        );


        select.innerHTML = `

            <option value="">
                Erro ao carregar CFOPs
            </option>
        `;


        select.disabled =
            false;


        return false;
    }
}

// =========================================================
// DEVOLUÇÃO - NF-E REFERENCIADA
// =========================================================

function normalizarTextoAvulsaNFE(valor) {

    return String(
        valor || ''
    )
        .normalize('NFD')
        .replace(
            /[\u0300-\u036f]/g,
            ''
        )
        .trim()
        .toLowerCase();
}


// =========================================================
// VERIFICA SE A NATUREZA É ENTRADA DE DEVOLUÇÃO
// =========================================================

function ehEntradaDevolucaoAvulsaNFE() {

    const natureza =
        document
            .getElementById(
                'avulsaNatOp'
            )
            ?.value ||
        '';


    const texto =
        normalizarTextoAvulsaNFE(
            natureza
        );


    return (
        texto.includes(
            'entrada'
        ) &&
        texto.includes(
            'devolucao'
        )
    );
}


// =========================================================
// GARANTIR CAMPO DA CHAVE REFERENCIADA
// =========================================================

function garantirCampoReferenciaDevolucaoAvulsaNFE() {

    const aba =
        document.getElementById(
            'abaAvulsa'
        );


    if (!aba) {

        console.error(
            '❌ abaAvulsa não encontrada'
        );

        return null;
    }


    // =====================================================
    // SE JÁ EXISTIR, NÃO DUPLICAR
    // =====================================================

    let grupo =
        document.getElementById(
            'avulsaReferenciaDevolucaoGrupo'
        );


    if (grupo) {

        atualizarCampoReferenciaDevolucaoAvulsaNFE();

        return grupo;
    }


    // =====================================================
    // CRIAR CAMPO
    // =====================================================

    grupo =
        document.createElement(
            'div'
        );


    grupo.id =
        'avulsaReferenciaDevolucaoGrupo';


    grupo.className =
        'form-group';


    grupo.style.cssText = `
        display:none;
        margin-top:15px;
        margin-bottom:15px;
    `;


    grupo.innerHTML = `

        <label
            for="avulsaChaveNFeReferenciada"
            style="
                display:block;
                margin-bottom:7px;
                font-weight:500;
            "
        >
            Chave de acesso da NF-e de saída *
        </label>

        <input
            type="text"
            id="avulsaChaveNFeReferenciada"
            class="form-control"
            maxlength="44"
            inputmode="numeric"
            autocomplete="off"
            placeholder="Digite os 44 números da chave da NF-e original"
        >

        <small
            style="
                display:block;
                margin-top:5px;
                color:#6c757d;
            "
        >
            Informe a chave da NF-e de saída referente a esta devolução.
        </small>

        <div
            id="avulsaChaveNFeReferenciadaContador"
            style="
                margin-top:4px;
                font-size:12px;
                color:#6c757d;
            "
        >
            0 / 44 dígitos
        </div>
    `;


    // =====================================================
    // COLOCAR LOGO DEPOIS DA NATUREZA
    // =====================================================

    const selectNatureza =
        document.getElementById(
            'avulsaNatOp'
        );


    let grupoNatureza =
        selectNatureza
            ?.closest(
                '.form-group'
            );


    // Caso o HTML não use .form-group
    if (!grupoNatureza) {

        grupoNatureza =
            selectNatureza
                ?.parentElement;
    }


    if (
        grupoNatureza &&
        grupoNatureza.parentElement
    ) {

        grupoNatureza.insertAdjacentElement(
            'afterend',
            grupo
        );

    } else {

        // =================================================
        // FALLBACK:
        // colocar antes da modalidade de frete
        // =================================================

        const modalidade =
            document.getElementById(
                'avulsaModFrete'
            );


        const grupoModalidade =
            modalidade
                ?.closest(
                    '.form-group'
                ) ||
            modalidade
                ?.parentElement;


        if (
            grupoModalidade &&
            grupoModalidade.parentElement
        ) {

            grupoModalidade
                .parentElement
                .insertBefore(
                    grupo,
                    grupoModalidade
                );

        } else {

            aba.appendChild(
                grupo
            );
        }
    }


    // =====================================================
    // PERMITIR APENAS NÚMEROS
    // =====================================================

    const input =
        document.getElementById(
            'avulsaChaveNFeReferenciada'
        );


    if (input) {

        input.oninput =
            function () {

                this.value =
                    String(
                        this.value || ''
                    )
                        .replace(
                            /\D/g,
                            ''
                        )
                        .substring(
                            0,
                            44
                        );


                const contador =
                    document.getElementById(
                        'avulsaChaveNFeReferenciadaContador'
                    );


                if (contador) {

                    contador.textContent =
                        `${this.value.length} / 44 dígitos`;


                    contador.style.color =
                        this.value.length === 44
                            ? '#198754'
                            : '#6c757d';
                }
            };
    }


    atualizarCampoReferenciaDevolucaoAvulsaNFE();


    console.log(
        '✅ Campo de NF-e referenciada criado'
    );


    return grupo;
}


// =========================================================
// MOSTRAR / ESCONDER CAMPO
// =========================================================

function atualizarCampoReferenciaDevolucaoAvulsaNFE() {

    const grupo =
        document.getElementById(
            'avulsaReferenciaDevolucaoGrupo'
        );


    const input =
        document.getElementById(
            'avulsaChaveNFeReferenciada'
        );


    if (
        !grupo ||
        !input
    ) {

        return;
    }


    const ehDevolucao =
        ehEntradaDevolucaoAvulsaNFE();


    console.log(
        '🔎 Natureza NF-e avulsa:',
        document
            .getElementById(
                'avulsaNatOp'
            )
            ?.value,
        '| É devolução:',
        ehDevolucao
    );


    if (ehDevolucao) {

        grupo.style.display =
            'block';

        input.required =
            true;

    } else {

        grupo.style.display =
            'none';

        input.required =
            false;

        input.value =
            '';


        const contador =
            document.getElementById(
                'avulsaChaveNFeReferenciadaContador'
            );


        if (contador) {

            contador.textContent =
                '0 / 44 dígitos';

            contador.style.color =
                '#6c757d';
        }
    }
}


