window.handleEmitirNFEClick = handleEmitirNFEClick;
window.handleVerNFEClick = handleVerNFEClick;
window.handleCancelarNFEClick = handleCancelarNFEClick;

function obterPackIdNFE(venda) {

    if (!venda) {
        return null;
    }

    let dadosCompletos =
        venda.dados_completos ||
        venda.venda_json ||
        {};

    if (
        typeof dadosCompletos ===
        'string'
    ) {

        try {
            dadosCompletos =
                JSON.parse(
                    dadosCompletos
                );
        } catch {
            dadosCompletos = {};
        }
    }

    const packId =
        venda._pack_id ||
        venda.pack_id ||
        dadosCompletos.pack_id ||
        dadosCompletos.order?.pack_id ||
        null;

    if (
        packId === null ||
        packId === undefined ||
        packId === ''
    ) {
        return null;
    }

    return String(
        packId
    );
}


function obterShipmentIdNFE(venda) {

    if (!venda) {
        return null;
    }

    const info =
        typeof parseInformacoesEnvioNFE ===
            'function'
            ? parseInformacoesEnvioNFE(
                venda
            )
            : {};

    let dadosCompletos =
        venda.dados_completos ||
        venda.venda_json ||
        {};

    if (
        typeof dadosCompletos ===
        'string'
    ) {

        try {
            dadosCompletos =
                JSON.parse(
                    dadosCompletos
                );
        } catch {
            dadosCompletos = {};
        }
    }

    const shipmentId =
        venda._shipment_id ||
        venda.shipment_id ||
        venda.id_envio ||
        venda.shipping?.id ||
        info?.id ||
        dadosCompletos?.shipping?.id ||
        dadosCompletos?.shipment_id ||
        null;

    if (
        shipmentId === null ||
        shipmentId === undefined ||
        shipmentId === ''
    ) {
        return null;
    }

    return String(
        shipmentId
    );
}


function obterChaveAgrupamentoNFE(
    venda
) {

    const vendaId =
        normalizarOrderIdML(
            venda?.id_venda_ml ||
            venda?.id
        );

    if (!vendaId) {
        return null;
    }

    // FULL não deve entrar no agrupamento manual
    if (
        detectarVendaFullNFE(
            venda
        )
    ) {

        return `order:${vendaId}`;
    }

    const packId =
        obterPackIdNFE(
            venda
        );

    if (packId) {

        return `pack:${packId}`;
    }

    const shipmentId =
        obterShipmentIdNFE(
            venda
        );

    if (shipmentId) {

        return `shipment:${shipmentId}`;
    }

    return `order:${vendaId}`;
}


function obterItensVendaParaPackNFE(
    venda
) {

    const vendaId =
        normalizarOrderIdML(
            venda.id_venda_ml ||
            venda.id
        );

    let items =
        Array.isArray(
            venda.order_items
        )
            ? venda.order_items
            : [];

    // =====================================================
    // FALLBACK
    // =====================================================

    if (
        items.length === 0 &&
        venda.sku
    ) {

        items = [
            {
                quantity:
                    Number(
                        venda.quantidade ||
                        venda.quantity ||
                        1
                    ),

                unit_price:
                    Number(
                        venda._valor_produto ||
                        venda.valor_total ||
                        0
                    ) /
                    Math.max(
                        Number(
                            venda.quantidade ||
                            venda.quantity ||
                            1
                        ),
                        1
                    ),

                item: {
                    seller_sku:
                        venda.sku,

                    title:
                        venda.titulo ||
                        venda.title ||
                        'Produto'
                }
            }
        ];
    }

    // =====================================================
    // VALOR REAL DESTA ORDER
    // =====================================================

    const valorVenda =
        Number(
            venda._valor_produto ??
            venda.valor_produto ??
            venda.valor_total ??
            venda.total_amount ??
            0
        );

    const totalOriginal =
        items.reduce(
            (
                total,
                item
            ) => {

                return (
                    total +
                    (
                        Number(
                            item.unit_price ||
                            0
                        ) *
                        Number(
                            item.quantity ||
                            1
                        )
                    )
                );
            },
            0
        );

    const quantidadeTotal =
        items.reduce(
            (
                total,
                item
            ) =>
                total +
                Number(
                    item.quantity ||
                    1
                ),
            0
        );

    return items.map(
        item => {

            let valorUnitarioCorrigido =
                Number(
                    item.unit_price ||
                    0
                );

            if (
                valorVenda > 0
            ) {

                if (
                    totalOriginal > 0
                ) {

                    const proporcao =
                        (
                            Number(
                                item.unit_price ||
                                0
                            ) *
                            Number(
                                item.quantity ||
                                1
                            )
                        ) /
                        totalOriginal;

                    const valorLinha =
                        valorVenda *
                        proporcao;

                    valorUnitarioCorrigido =
                        valorLinha /
                        Math.max(
                            Number(
                                item.quantity ||
                                1
                            ),
                            1
                        );

                } else if (
                    quantidadeTotal > 0
                ) {

                    valorUnitarioCorrigido =
                        valorVenda /
                        quantidadeTotal;
                }
            }

            return {

                ...item,

                _order_id:
                    vendaId,

                _valor_unitario_corrigido:
                    valorUnitarioCorrigido
            };
        }
    );
}


function agruparVendasEmPacksNFE(
    vendas
) {

    if (
        !Array.isArray(
            vendas
        ) ||
        vendas.length ===
            0
    ) {

        return [];
    }


    const grupos =
        new Map();


    for (
        const venda
        of vendas
    ) {

        const chave =
            obterChaveAgrupamentoNFE(
                venda
            );


        if (!chave) {
            continue;
        }


        if (
            !grupos.has(
                chave
            )
        ) {

            grupos.set(
                chave,
                []
            );
        }


        grupos
            .get(
                chave
            )
            .push(
                venda
            );
    }


    const resultado =
        [];


    for (
        const [
            chave,
            membros
        ]
        of grupos.entries()
    ) {

        // =====================================================
        // VENDA NORMAL
        // =====================================================

        if (
            membros.length ===
            1
        ) {

            resultado.push(
                membros[0]
            );

            continue;
        }


        // =====================================================
        // PACK
        // =====================================================

        const principal =
            membros[0];


        const orderIds =
            [
                ...new Set(

                    membros
                        .map(
                            venda =>
                                normalizarOrderIdML(
                                    venda.id_venda_ml ||
                                    venda.id
                                )
                        )
                        .filter(Boolean)
                )
            ];


        const todosItems =
            membros.flatMap(
                venda =>
                    obterItensVendaParaPackNFE(
                        venda
                    )
            );


        const valorProduto =
            membros.reduce(
                (
                    total,
                    venda
                ) =>
                    total +
                    Number(
                        venda._valor_produto ??
                        venda.valor_produto ??
                        venda.valor_total ??
                        venda.total_amount ??
                        0
                    ),
                0
            );


        const valorFrete =
            membros.reduce(
                (
                    total,
                    venda
                ) =>
                    total +
                    Number(
                        venda._valor_frete ??
                        venda.valor_frete ??
                        0
                    ),
                0
            );


        const totalPago =
            membros.reduce(
                (
                    total,
                    venda
                ) =>
                    total +
                    Number(
                        venda._total_pago ??
                        venda.total_pago ??
                        venda._valor_produto ??
                        venda.valor_total ??
                        0
                    ),
                0
            );


        // =====================================================
        // NF-E
        // =====================================================

        const temNfe =
            membros.some(
                venda =>
                    Boolean(
                        venda._tem_nfe
                    )
            );


        const emissoresUsername =
            [
                ...new Set(

                    membros
                        .map(
                            venda =>
                                venda
                                    ._nfe_emitida_por_username
                        )
                        .filter(Boolean)
                )
            ];


        const emissoresNome =
            [
                ...new Set(

                    membros
                        .map(
                            venda =>
                                venda
                                    ._nfe_emitida_por_nome
                        )
                        .filter(Boolean)
                )
            ];


        // =====================================================
        // ESTOQUE
        // =====================================================

        const todosBaixados =
            membros.every(
                venda =>
                    Boolean(
                        venda._estoque_baixado
                    )
            );


        const responsaveisBaixaUsername =
            [
                ...new Set(

                    membros
                        .map(
                            venda =>
                                venda
                                    ._estoque_baixado_por_username
                        )
                        .filter(Boolean)
                )
            ];


        const responsaveisBaixaNome =
            [
                ...new Set(

                    membros
                        .map(
                            venda =>
                                venda
                                    ._estoque_baixado_por_nome
                        )
                        .filter(Boolean)
                )
            ];


        const algumRestaurado =
            membros.some(
                venda =>
                    Boolean(
                        venda
                            ._estoque_restaurado_cancelamento
                    ) ||
                    venda
                        ._estoque_status ===
                        'restaurado_cancelamento'
            );


        const algumRestauradoSyncPendente =
            membros.some(
                venda =>
                    venda
                        ._estoque_status ===
                    'restaurado_cancelamento_sync_pendente'
            );


        let estoqueStatus =
            'nao_verificado';


        if (
            algumRestauradoSyncPendente
        ) {

            estoqueStatus =
                'restaurado_cancelamento_sync_pendente';

        } else if (
            algumRestaurado
        ) {

            estoqueStatus =
                'restaurado_cancelamento';

        } else if (
            membros.some(
                venda =>
                    venda._estoque_status ===
                    'sem_cadastro'
            )
        ) {

            estoqueStatus =
                'sem_cadastro';

        } else if (
            todosBaixados
        ) {

            estoqueStatus =
                membros.some(
                    venda =>
                        venda._estoque_status ===
                        'baixado_sync_pendente'
                )
                    ? 'baixado_sync_pendente'
                    : 'baixado';

        } else if (
            membros.every(
                venda =>
                    venda._estoque_status ===
                    'disponivel'
            )
        ) {

            estoqueStatus =
                'disponivel';

        } else if (
            membros.some(
                venda =>
                    venda._estoque_status ===
                    'processando'
            )
        ) {

            estoqueStatus =
                'processando';
        }


        const detalhesEstoque =
            membros.flatMap(
                venda =>
                    Array.isArray(
                        venda._estoque_detalhes
                    )
                        ? venda._estoque_detalhes
                        : []
            );


        // =====================================================
        // ESTOQUE DOS ANÚNCIOS APÓS A VENDA
        // =====================================================

        const estoqueAnuncioPosVenda =
            consolidarSnapshotsEstoqueAnuncioNFE(

                membros.flatMap(
                    venda =>
                        normalizarArrayJsonNFE(
                            venda
                                ._estoque_anuncio_pos_venda
                        )
                )
            );


        // =====================================================
        // CANCELAMENTO
        // =====================================================

        const vendaCancelada =
            membros.some(
                venda =>
                    Boolean(
                        venda._venda_cancelada
                    ) ||
                    String(
                        venda._ml_status ||
                        venda.status ||
                        ''
                    )
                        .toLowerCase() ===
                        'cancelled'
            );


        const vendaCanceladaEm =
            membros
                .map(
                    venda =>
                        venda
                            ._venda_cancelada_em
                )
                .filter(Boolean)
                .sort()
                .at(-1) ||
            null;


        const estoqueRestauradoCancelamento =
            membros.some(
                venda =>
                    Boolean(
                        venda
                            ._estoque_restaurado_cancelamento
                    )
            );


        const estoqueRestauradoCancelamentoEm =
            membros
                .map(
                    venda =>
                        venda
                            ._estoque_restaurado_cancelamento_em
                )
                .filter(Boolean)
                .sort()
                .at(-1) ||
            null;


        const packId =
            obterPackIdNFE(
                principal
            );


        const shipmentId =
            obterShipmentIdNFE(
                principal
            );


        const agrupada = {

            ...principal,

            // =============================================
            // IDENTIFICAÇÃO
            // =============================================

            _eh_pack:
                true,

            _pack_key:
                chave,

            _pack_id:
                packId,

            _shipment_id:
                shipmentId,

            _order_ids_pack:
                orderIds,

            _membros_pack:
                membros,


            // =============================================
            // PRODUTOS
            // =============================================

            order_items:
                todosItems,


            // =============================================
            // VALORES
            // =============================================

            _valor_produto:
                valorProduto,

            _valor_frete:
                valorFrete,

            _total_pago:
                totalPago,

            total_amount:
                totalPago,


            // =============================================
            // NF-E
            // =============================================

            _tem_nfe:
                temNfe,

            _nfe_emitida_por_username:
                emissoresUsername.join(
                    ' / '
                ) ||
                null,

            _nfe_emitida_por_nome:
                emissoresNome.join(
                    ' / '
                ) ||
                null,


            // =============================================
            // ESTOQUE
            // =============================================

            _estoque_baixado:
                todosBaixados,

            _estoque_status:
                estoqueStatus,

            _estoque_detalhes:
                detalhesEstoque,

            _estoque_baixado_por_username:
                responsaveisBaixaUsername.join(
                    ' / '
                ) ||
                null,

            _estoque_baixado_por_nome:
                responsaveisBaixaNome.join(
                    ' / '
                ) ||
                null,

            _estoque_anuncio_pos_venda:
                estoqueAnuncioPosVenda,


            // =============================================
            // CANCELAMENTO
            // =============================================

            _venda_cancelada:
                vendaCancelada,

            _venda_cancelada_em:
                vendaCanceladaEm,

            _estoque_restaurado_cancelamento:
                estoqueRestauradoCancelamento,

            _estoque_restaurado_cancelamento_em:
                estoqueRestauradoCancelamentoEm
        };


        console.log(
            '📦 PACK ML AGRUPADO:',
            {
                chave,
                packId,
                shipmentId,
                orderIds,

                produtos:
                    todosItems.map(
                        item =>
                            item.item
                                ?.seller_sku
                    ),

                valor:
                    valorProduto,

                emitidoPor:
                    agrupada
                        ._nfe_emitida_por_nome,

                baixaPor:
                    agrupada
                        ._estoque_baixado_por_nome,

                estoqueAnuncio:
                    agrupada
                        ._estoque_anuncio_pos_venda
            }
        );


        resultado.push(
            agrupada
        );
    }


    return resultado;
}


function obterOrderIdsVendaAtualNFE(
    orderId
) {

    const principal =
        normalizarOrderIdML(
            orderId
        );


    const atual =
        window._nfeVendaAtual;


    if (
        atual &&
        Array.isArray(
            atual._order_ids_pack
        ) &&
        atual._order_ids_pack.length >
            0
    ) {

        return [
            ...new Set(

                atual._order_ids_pack
                    .map(
                        normalizarOrderIdML
                    )
                    .filter(Boolean)
            )
        ];
    }


    if (
        Array.isArray(
            window._nfeOrderIdsAtuais
        ) &&
        window._nfeOrderIdsAtuais
            .length >
            0
    ) {

        return [
            ...new Set(

                window._nfeOrderIdsAtuais
                    .map(
                        normalizarOrderIdML
                    )
                    .filter(Boolean)
            )
        ];
    }


    return principal
        ? [
            principal
        ]
        : [];
}

