function obterUsuarioAtualComentariosNFE() {

    let usuario =
        window.currentUser ||
        null;


    // =====================================================
    // FALLBACK DA SESSÃO
    // =====================================================

    if (!usuario) {

        try {

            usuario =
                JSON.parse(
                    localStorage.getItem(
                        'wheeltech_user'
                    ) ||
                    'null'
                );

        } catch (
            error
        ) {

            usuario =
                null;
        }
    }


    const username =
        String(
            usuario?.username ||
            ''
        )
            .trim()
            .toLowerCase();


    const nome =
        String(
            usuario?.name ||
            usuario?.nome ||
            username ||
            'Usuário'
        )
            .trim();


    return {
        username,
        nome
    };
}


