function formatarDataComentarioNFE(
    valor
) {

    if (!valor) {

        return '';
    }


    try {

        return new Date(
            valor
        )
            .toLocaleString(
                'pt-BR',
                {
                    day:
                        '2-digit',

                    month:
                        '2-digit',

                    year:
                        'numeric',

                    hour:
                        '2-digit',

                    minute:
                        '2-digit'
                }
            );

    } catch (
        error
    ) {

        return '';
    }
}


