function renderizarResumoComentariosVendaNFE(
    vendaId,
    comentarios = []
) {

    const elementos =
        document.querySelectorAll(
            '#vendasPendentesBody [data-resumo-comentarios-nfe]'
        );


    elementos.forEach(
        elemento => {

            if (
                String(
                    elemento.dataset
                        .vendaId
                ) !==
                String(
                    vendaId
                )
            ) {

                return;
            }


            const quantidade =
                comentarios.length;


            // =================================================
            // SEM COMENTÁRIOS
            // =================================================

            if (
                quantidade ===
                0
            ) {

                elemento.innerHTML = `

                    <button
                        type="button"
                        class="btn btn-sm btn-secondary"
                        onclick="abrirComentariosVendaNFE('${escaparHTMLNFE(vendaId)}')"
                        style="
                            white-space:nowrap;
                        "
                    >
                        <i class="far fa-comment"></i>
                        Adicionar
                    </button>


                    <div
                        style="
                            color:#adb5bd;
                            font-size:10px;
                            margin-top:4px;
                        "
                    >
                        Sem comentários
                    </div>
                `;


                return;
            }


            // =================================================
            // TODOS OS COMENTÁRIOS
            // =================================================

            const comentariosHtml =
                comentarios
                    .map(
                        comentario => {

                            const texto =
                                String(
                                    comentario.comentario ||
                                    ''
                                );


                            const nomeUsuario =
                                comentario.usuario_nome ||
                                comentario.usuario_username ||
                                'Usuário';


                            const data =
                                formatarDataComentarioNFE(
                                    comentario.criado_em
                                );


                            const editado =
                                comentario.editado_em
                                    ? `
                                        <span
                                            style="
                                                color:#adb5bd;
                                                font-size:9px;
                                            "
                                        >
                                            • editado
                                        </span>
                                    `
                                    : '';


                            return `

                                <div
                                    style="
                                        border-left:3px solid #17a2b8;
                                        padding:6px 7px;
                                        margin-bottom:6px;
                                        background:#f8f9fa;
                                        border-radius:4px;
                                        max-width:230px;
                                    "
                                >

                                    <div
                                        style="
                                            font-size:10px;
                                            font-weight:700;
                                            color:#343a40;
                                            margin-bottom:2px;
                                        "
                                    >
                                        <i class="fas fa-user-circle"></i>

                                        ${escaparHTMLNFE(
                                            nomeUsuario
                                        )}
                                    </div>


                                    <div
                                        style="
                                            font-size:10px;
                                            line-height:1.35;
                                            color:#495057;
                                            white-space:pre-wrap;
                                            word-break:break-word;
                                        "
                                    >
                                        ${escaparHTMLNFE(
                                            texto
                                        )}
                                    </div>


                                    <div
                                        style="
                                            font-size:9px;
                                            color:#868e96;
                                            margin-top:3px;
                                        "
                                    >
                                        ${escaparHTMLNFE(
                                            data
                                        )}

                                        ${editado}
                                    </div>

                                </div>
                            `;
                        }
                    )
                    .join(
                        ''
                    );


            elemento.innerHTML = `

                <div
                    style="
                        min-width:190px;
                        max-width:240px;
                    "
                >

                    <div
                        style="
                            display:flex;
                            justify-content:space-between;
                            align-items:center;
                            gap:6px;
                            margin-bottom:6px;
                        "
                    >

                        <button
                            type="button"
                            class="btn btn-sm btn-info"
                            onclick="abrirComentariosVendaNFE('${escaparHTMLNFE(vendaId)}')"
                            style="
                                white-space:nowrap;
                            "
                            title="Abrir comentários"
                        >
                            <i class="fas fa-comments"></i>

                            ${quantidade}

                            ${
                                quantidade ===
                                    1
                                    ? 'comentário'
                                    : 'comentários'
                            }
                        </button>


                        <button
                            type="button"
                            class="btn btn-sm btn-success"
                            onclick="abrirComentariosVendaNFE('${escaparHTMLNFE(vendaId)}')"
                            title="Adicionar comentário"
                            style="
                                padding:4px 7px !important;
                            "
                        >
                            <i class="fas fa-plus"></i>
                        </button>

                    </div>


                    <div
                        style="
                            max-height:220px;
                            overflow-y:auto;
                            padding-right:3px;
                        "
                    >
                        ${comentariosHtml}
                    </div>

                </div>
            `;
        }
    );
}


// =========================================================
// CARREGAR RESUMOS DE TODAS AS VENDAS DA TABELA
// =========================================================

async function carregarResumosComentariosVendasNFE(
    vendas
) {

    if (
        !Array.isArray(
            vendas
        ) ||
        vendas.length ===
            0
    ) {

        return;
    }


    const ids =
        [
            ...new Set(

                vendas
                    .map(
                        venda =>
                            normalizarOrderIdML(
                                venda.id_venda_ml ||
                                venda.id
                            )
                    )
                    .filter(Boolean)
            )
        ];


    if (
        ids.length ===
        0
    ) {

        return;
    }


    const todosComentarios =
        [];


    // =====================================================
    // BUSCAR EM LOTES
    // =====================================================

    const TAMANHO_LOTE =
        100;


    for (
        let i = 0;
        i < ids.length;
        i += TAMANHO_LOTE
    ) {

        const lote =
            ids.slice(
                i,
                i +
                    TAMANHO_LOTE
            );


        const {
            data,
            error
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .select(`
                    id,
                    venda_id_ml,
                    comentario,
                    usuario_username,
                    usuario_nome,
                    criado_em,
                    editado_em
                `)
                .in(
                    'venda_id_ml',
                    lote
                )
                .order(
                    'criado_em',
                    {
                        ascending:
                            false
                    }
                );


        if (
            error
        ) {

            console.error(
                '❌ Erro carregando comentários:',
                error
            );


            throw error;
        }


        todosComentarios.push(
            ...(
                data ||
                []
            )
        );
    }


    // =====================================================
    // AGRUPAR POR VENDA
    // =====================================================

    const mapa =
        new Map();


    ids.forEach(
        id =>

            mapa.set(
                String(id),
                []
            )
    );


    todosComentarios.forEach(
        comentario => {

            const id =
                String(
                    comentario
                        .venda_id_ml
                );


            if (
                !mapa.has(
                    id
                )
            ) {

                mapa.set(
                    id,
                    []
                );
            }


            mapa
                .get(
                    id
                )
                .push(
                    comentario
                );
        }
    );


    // =====================================================
    // ATUALIZAR TELA
    // =====================================================

    mapa.forEach(
        (
            comentarios,
            vendaId
        ) => {

            renderizarResumoComentariosVendaNFE(
                vendaId,
                comentarios
            );
        }
    );
}


// =========================================================
// ABRIR MODAL
// =========================================================

async function abrirComentariosVendaNFE(
    vendaId
) {

    vendaId =
        normalizarOrderIdML(
            vendaId
        );


    if (
        !vendaId
    ) {

        showToast(
            'ID da venda inválido.',
            'error'
        );


        return;
    }


    const modal =
        garantirModalComentariosNFE();


    window
        ._comentariosVendaAtualNFE =
        vendaId;


    const titulo =
        document.getElementById(
            'tituloVendaComentariosNFE'
        );


    if (
        titulo
    ) {

        titulo.textContent =
            `Venda ${vendaId}`;
    }


    const textarea =
        document.getElementById(
            'novoComentarioVendaNFE'
        );


    if (
        textarea
    ) {

        textarea.value =
            '';


        textarea.focus();
    }


    const contador =
        document.getElementById(
            'contadorComentarioVendaNFE'
        );


    if (
        contador
    ) {

        contador.textContent =
            '0/2000';
    }


    modal.classList.remove(
        'hidden'
    );


    await carregarComentariosVendaNFE(
        vendaId
    );
}


// =========================================================
// FECHAR
// =========================================================

function fecharComentariosVendaNFE() {

    document
        .getElementById(
            'modalComentariosVendaNFE'
        )
        ?.classList
        .add(
            'hidden'
        );


    window
        ._comentariosVendaAtualNFE =
        null;
}


// =========================================================
// CARREGAR COMENTÁRIOS DE UMA VENDA
// =========================================================

async function carregarComentariosVendaNFE(
    vendaId
) {

    const lista =
        document.getElementById(
            'listaComentariosVendaNFE'
        );


    if (
        lista
    ) {

        lista.innerHTML = `

            <div
                style="
                    text-align:center;
                    padding:25px;
                    color:#6c757d;
                "
            >
                <span class="spinner"></span>
                Carregando comentários...
            </div>
        `;
    }


    try {

        const {
            data,
            error
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .select(`
                    id,
                    venda_id_ml,
                    comentario,
                    usuario_username,
                    usuario_nome,
                    criado_em,
                    editado_em
                `)
                .eq(
                    'venda_id_ml',
                    String(
                        vendaId
                    )
                )
                .order(
                    'criado_em',
                    {
                        ascending:
                            false
                    }
                );


        if (
            error
        ) {

            throw error;
        }


        const comentarios =
            Array.isArray(
                data
            )
                ? data
                : [];


        const usuarioAtual =
            obterUsuarioAtualComentariosNFE();


        // =================================================
        // SEM COMENTÁRIO
        // =================================================

        if (
            comentarios.length ===
            0
        ) {

            lista.innerHTML = `

                <div
                    style="
                        text-align:center;
                        padding:35px 15px;
                        color:#6c757d;
                    "
                >

                    <i
                        class="far fa-comments"
                        style="
                            font-size:30px;
                            margin-bottom:10px;
                            display:block;
                            color:#adb5bd;
                        "
                    ></i>

                    Nenhum comentário nesta venda.

                </div>
            `;

        } else {

            // =================================================
            // LISTA
            // =================================================

            lista.innerHTML =
                comentarios
                    .map(
                        comentario => {

                            const dono =
                                String(
                                    comentario
                                        .usuario_username ||
                                    ''
                                )
                                    .trim()
                                    .toLowerCase() ===
                                usuarioAtual.username;


                            const dataComentario =
                                formatarDataComentarioNFE(
                                    comentario.criado_em
                                );


                            const dataEditado =
                                comentario.editado_em
                                    ? formatarDataComentarioNFE(
                                        comentario.editado_em
                                    )
                                    : '';


                            return `

                                <div
                                    style="
                                        border:1px solid #dee2e6;
                                        border-radius:9px;
                                        padding:13px;
                                        margin-bottom:10px;
                                        background:white;
                                    "
                                >

                                    <div
                                        style="
                                            display:flex;
                                            justify-content:space-between;
                                            gap:10px;
                                            align-items:flex-start;
                                        "
                                    >

                                        <div>

                                            <strong>
                                                <i class="fas fa-user-circle"></i>

                                                ${escaparHTMLNFE(
                                                    comentario.usuario_nome ||
                                                    comentario.usuario_username ||
                                                    'Usuário'
                                                )}
                                            </strong>


                                            <div
                                                style="
                                                    font-size:10px;
                                                    color:#6c757d;
                                                    margin-top:2px;
                                                "
                                            >

                                                ${escaparHTMLNFE(
                                                    dataComentario
                                                )}

                                                ${
                                                    comentario.editado_em

                                                        ? `
                                                            • editado ${
                                                                escaparHTMLNFE(
                                                                    dataEditado
                                                                )
                                                            }
                                                        `

                                                        : ''
                                                }

                                            </div>

                                        </div>


                                        ${
                                            dono

                                                ? `

                                                    <div
                                                        style="
                                                            display:flex;
                                                            gap:4px;
                                                        "
                                                    >

                                                        <button
                                                            type="button"
                                                            class="btn btn-sm btn-warning"
                                                            onclick="editarComentarioVendaNFE(${Number(
                                                                comentario.id
                                                            )})"
                                                            title="Editar meu comentário"
                                                        >
                                                            <i class="fas fa-edit"></i>
                                                        </button>


                                                        <button
                                                            type="button"
                                                            class="btn btn-sm btn-danger"
                                                            onclick="excluirComentarioVendaNFE(${Number(
                                                                comentario.id
                                                            )})"
                                                            title="Excluir meu comentário"
                                                        >
                                                            <i class="fas fa-trash"></i>
                                                        </button>

                                                    </div>
                                                `

                                                : ''
                                        }

                                    </div>


                                    <div
                                        style="
                                            margin-top:11px;
                                            white-space:pre-wrap;
                                            word-break:break-word;
                                            line-height:1.45;
                                            color:#343a40;
                                        "
                                    >${escaparHTMLNFE(
                                        comentario.comentario
                                    )}</div>

                                </div>
                            `;
                        }
                    )
                    .join(
                        ''
                    );
        }


        // =================================================
        // ATUALIZAR TAMBÉM RESUMO NA TABELA
        // =================================================

        renderizarResumoComentariosVendaNFE(
            vendaId,
            comentarios
        );


        return comentarios;


    } catch (
        error
    ) {

        console.error(
            '❌ Erro carregando comentários da venda:',
            error
        );


        if (
            lista
        ) {

            lista.innerHTML = `

                <div
                    style="
                        text-align:center;
                        color:#dc3545;
                        padding:20px;
                    "
                >
                    Erro ao carregar comentários.
                </div>
            `;
        }


        return [];
    }
}


// =========================================================
// ADICIONAR COMENTÁRIO
// =========================================================

async function salvarNovoComentarioVendaNFE() {

    const vendaId =
        window
            ._comentariosVendaAtualNFE;


    if (
        !vendaId
    ) {

        showToast(
            'Venda não identificada.',
            'error'
        );


        return;
    }


    const usuario =
        obterUsuarioAtualComentariosNFE();


    if (
        !usuario.username
    ) {

        showToast(
            'Usuário não identificado. Faça login novamente.',
            'error'
        );


        return;
    }


    const textarea =
        document.getElementById(
            'novoComentarioVendaNFE'
        );


    const comentario =
        String(
            textarea?.value ||
            ''
        )
            .trim();


    if (
        !comentario
    ) {

        showToast(
            'Digite o comentário.',
            'warning'
        );


        textarea
            ?.focus();


        return;
    }


    if (
        comentario.length >
        2000
    ) {

        showToast(
            'O comentário pode ter no máximo 2000 caracteres.',
            'warning'
        );


        return;
    }


    const botao =
        document.getElementById(
            'btnSalvarComentarioVendaNFE'
        );


    const textoOriginal =
        botao?.innerHTML ||
        'Adicionar comentário';


    try {

        if (
            botao
        ) {

            botao.disabled =
                true;


            botao.innerHTML =
                '<span class="spinner"></span> Salvando...';
        }


        const {
            error
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .insert({

                    venda_id_ml:
                        String(
                            vendaId
                        ),

                    comentario:
                        comentario,

                    usuario_username:
                        usuario.username,

                    usuario_nome:
                        usuario.nome
                });


        if (
            error
        ) {

            throw error;
        }


        textarea.value =
            '';


        const contador =
            document.getElementById(
                'contadorComentarioVendaNFE'
            );


        if (
            contador
        ) {

            contador.textContent =
                '0/2000';
        }


        showToast(
            '✅ Comentário adicionado.',
            'success'
        );


        await carregarComentariosVendaNFE(
            vendaId
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro adicionando comentário:',
            error
        );


        showToast(
            `Erro ao adicionar comentário: ${error.message}`,
            'error'
        );


    } finally {

        if (
            botao
        ) {

            botao.disabled =
                false;


            botao.innerHTML =
                textoOriginal;
        }
    }
}


// =========================================================
// EDITAR COMENTÁRIO
// =========================================================

async function editarComentarioVendaNFE(
    comentarioId
) {

    const usuario =
        obterUsuarioAtualComentariosNFE();


    if (
        !usuario.username
    ) {

        showToast(
            'Usuário não identificado.',
            'error'
        );


        return;
    }


    try {

        // =================================================
        // BUSCAR COMENTÁRIO ORIGINAL
        // =================================================

        const {
            data:
                comentario,
            error:
                erroBusca
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .select(`
                    id,
                    venda_id_ml,
                    comentario,
                    usuario_username
                `)
                .eq(
                    'id',
                    comentarioId
                )
                .maybeSingle();


        if (
            erroBusca
        ) {

            throw erroBusca;
        }


        if (
            !comentario
        ) {

            showToast(
                'Comentário não encontrado.',
                'warning'
            );


            return;
        }


        // =================================================
        // SOMENTE DONO
        // =================================================

        if (
            String(
                comentario.usuario_username
            )
                .trim()
                .toLowerCase() !==
            usuario.username
        ) {

            showToast(
                '🚫 Você só pode editar seus próprios comentários.',
                'warning'
            );


            return;
        }


        const novoTexto =
            prompt(
                'Editar comentário:',
                comentario.comentario
            );


        if (
            novoTexto ===
            null
        ) {

            return;
        }


        const texto =
            String(
                novoTexto
            )
                .trim();


        if (
            !texto
        ) {

            showToast(
                'O comentário não pode ficar vazio.',
                'warning'
            );


            return;
        }


        if (
            texto.length >
            2000
        ) {

            showToast(
                'O comentário pode ter no máximo 2000 caracteres.',
                'warning'
            );


            return;
        }


        // =================================================
        // UPDATE
        //
        // Repare que também filtramos pelo username.
        // =================================================

        const {
            data:
                atualizado,
            error:
                erroUpdate
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .update({

                    comentario:
                        texto,

                    editado_em:
                        new Date()
                            .toISOString()
                })
                .eq(
                    'id',
                    comentarioId
                )
                .eq(
                    'usuario_username',
                    usuario.username
                )
                .select(
                    'id'
                );


        if (
            erroUpdate
        ) {

            throw erroUpdate;
        }


        if (
            !atualizado ||
            atualizado.length ===
                0
        ) {

            showToast(
                '🚫 Você não tem permissão para editar este comentário.',
                'warning'
            );


            return;
        }


        showToast(
            '✅ Comentário atualizado.',
            'success'
        );


        await carregarComentariosVendaNFE(
            comentario.venda_id_ml
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro editando comentário:',
            error
        );


        showToast(
            `Erro ao editar comentário: ${error.message}`,
            'error'
        );
    }
}


// =========================================================
// EXCLUIR COMENTÁRIO
// =========================================================

async function excluirComentarioVendaNFE(
    comentarioId
) {

    const usuario =
        obterUsuarioAtualComentariosNFE();


    if (
        !usuario.username
    ) {

        showToast(
            'Usuário não identificado.',
            'error'
        );


        return;
    }


    try {

        // =================================================
        // BUSCAR
        // =================================================

        const {
            data:
                comentario,
            error:
                erroBusca
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .select(`
                    id,
                    venda_id_ml,
                    comentario,
                    usuario_username
                `)
                .eq(
                    'id',
                    comentarioId
                )
                .maybeSingle();


        if (
            erroBusca
        ) {

            throw erroBusca;
        }


        if (
            !comentario
        ) {

            showToast(
                'Comentário não encontrado.',
                'warning'
            );


            return;
        }


        // =================================================
        // SOMENTE O DONO
        // =================================================

        if (
            String(
                comentario.usuario_username
            )
                .trim()
                .toLowerCase() !==
            usuario.username
        ) {

            showToast(
                '🚫 Você só pode excluir seus próprios comentários.',
                'warning'
            );


            return;
        }


        const confirmar =
            confirm(
                'Excluir este comentário?'
            );


        if (
            !confirmar
        ) {

            return;
        }


        // =================================================
        // DELETE COM ID + USUÁRIO
        // =================================================

        const {
            data:
                excluido,
            error:
                erroDelete
        } =
            await window
                .supabaseClient
                .from(
                    'vendas_nfe_comentarios'
                )
                .delete()
                .eq(
                    'id',
                    comentarioId
                )
                .eq(
                    'usuario_username',
                    usuario.username
                )
                .select(
                    'id'
                );


        if (
            erroDelete
        ) {

            throw erroDelete;
        }


        if (
            !excluido ||
            excluido.length ===
                0
        ) {

            showToast(
                '🚫 Você não tem permissão para excluir este comentário.',
                'warning'
            );


            return;
        }


        showToast(
            '✅ Comentário excluído.',
            'success'
        );


        await carregarComentariosVendaNFE(
            comentario.venda_id_ml
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro excluindo comentário:',
            error
        );


        showToast(
            `Erro ao excluir comentário: ${error.message}`,
            'error'
        );
    }
}


