// =========================================================
// NORMALIZAR MLB
// =========================================================

function normalizarMLBFullNFE(
    valor
) {

    const texto =
        String(
            valor ||
            ''
        )
            .trim()
            .toUpperCase();


    const match =
        texto.match(
            /MLB\d+/
        );


    return match
        ? match[0]
        : '';
}


// =========================================================
// NOME DA EXPOSIÇÃO
// =========================================================

function nomeListingTypeFullNFE(
    listingType
) {

    listingType =
        String(
            listingType ||
            ''
        )
            .trim()
            .toLowerCase();


    if (
        listingType ===
        'gold_special'
    ) {

        return 'Clássico';
    }


    if (
        listingType ===
            'gold_pro' ||
        listingType ===
            'gold_premium'
    ) {

        return 'Premium';
    }


    return (
        listingType ||
        'Não identificado'
    );
}


// =========================================================
// EXPOSIÇÃO ESPERADA PELO ESTOQUE FULL
//
// REGRA SOLICITADA:
//
// TOTAL = 1
// → CLÁSSICO
//
// TOTAL > 1
// → PREMIUM
//
// Exemplo:
//
// 3 variações com 1 cada
// TOTAL = 3
// → PREMIUM
// =========================================================

function obterListingTypeEsperadoFullNFE(
    estoqueTotalFull
) {

    estoqueTotalFull =
        Number(
            estoqueTotalFull ||
            0
        );


    if (
        estoqueTotalFull <=
        0
    ) {

        return null;
    }


    if (
        estoqueTotalFull ===
        1
    ) {

        return 'gold_special';
    }


    return 'gold_pro';
}


// =========================================================
// EXTRAIR SELLER SKU
// =========================================================

function extrairSellerSkuObjetoFullNFE(
    objeto
) {

    if (
        !objeto
    ) {

        return '';
    }


    const direto =
        objeto.seller_sku ||
        objeto.seller_custom_field ||
        objeto.sku ||
        '';


    if (
        direto
    ) {

        return String(
            direto
        ).trim();
    }


    const atributos =
        Array.isArray(
            objeto.attributes
        )
            ? objeto.attributes
            : [];


    const atributo =
        atributos.find(
            attr => {

                const id =
                    String(
                        attr?.id ||
                        ''
                    )
                        .trim()
                        .toUpperCase();


                return (
                    id ===
                        'SELLER_SKU' ||
                    id ===
                        'SKU'
                );
            }
        );


    return String(
        atributo
            ?.value_name ||
        atributo
            ?.value_id ||
        ''
    ).trim();
}


// =========================================================
// GET MERCADO LIVRE
// =========================================================

async function consultarGETMLFullNFE(
    url,
    token = null
) {

    token =
        token ||
        await obterTokenMLNFE();


    if (
        !token
    ) {

        throw new Error(
            'Token Mercado Livre não disponível'
        );
    }


    const proxyUrl =
        `${window.WORKER_URL}/api/ml/proxy?url=` +
        `${encodeURIComponent(url)}` +
        `&token=${encodeURIComponent(token)}`;


    const response =
        await fetch(
            proxyUrl,
            {
                cache:
                    'no-store'
            }
        );


    if (
        !response.ok
    ) {

        const texto =
            await response
                .text()
                .catch(
                    () => ''
                );


        throw new Error(
            `HTTP ${response.status}: ${texto}`
        );
    }


    const data =
        await response
            .json();


    return {

        data,

        response
    };
}


// =========================================================
// BUSCAR DETALHES DE UMA VARIAÇÃO
// =========================================================

async function buscarDetalheVariacaoFullNFE(
    mlb,
    variationId,
    token
) {

    const url =
        `https://api.mercadolibre.com/items/${encodeURIComponent(
            mlb
        )}/variations/${encodeURIComponent(
            variationId
        )}?include_attributes=all`;


    try {

        const {
            data
        } =
            await consultarGETMLFullNFE(
                url,
                token
            );


        return data;


    } catch (
        error
    ) {

        console.warn(
            `⚠️ Não foi possível detalhar variação ${variationId} de ${mlb}:`,
            error
        );


        return null;
    }
}


// =========================================================
// BUSCAR ITEM + TODOS OS USER PRODUCTS
// =========================================================

async function buscarEstruturaMLBFullNFE(
    mlb
) {

    mlb =
        normalizarMLBFullNFE(
            mlb
        );


    if (
        !mlb
    ) {

        throw new Error(
            'MLB inválido'
        );
    }


    const token =
        await obterTokenMLNFE();


    if (
        !token
    ) {

        throw new Error(
            'Token Mercado Livre não disponível'
        );
    }


    const {
        data:
            item
    } =
        await consultarGETMLFullNFE(

            `https://api.mercadolibre.com/items/${mlb}`,

            token
        );


    const unidades =
        [];


    // =====================================================
    // COM VARIAÇÕES
    // =====================================================

    if (
        Array.isArray(
            item.variations
        ) &&
        item.variations.length >
            0
    ) {

        for (
            const variacaoBase
            of item.variations
        ) {

            let variacao =
                variacaoBase;


            let userProductId =
                variacao
                    ?.user_product_id ||
                null;


            let sku =
                extrairSellerSkuObjetoFullNFE(
                    variacao
                );


            // =============================================
            // DETALHAR SE FALTAR UP OU SKU
            // =============================================

            if (
                !userProductId ||
                !sku
            ) {

                const detalhe =
                    await buscarDetalheVariacaoFullNFE(

                        mlb,

                        variacao.id,

                        token
                    );


                if (
                    detalhe
                ) {

                    variacao = {

                        ...variacao,

                        ...detalhe
                    };


                    userProductId =
                        detalhe
                            .user_product_id ||
                        userProductId;


                    sku =
                        extrairSellerSkuObjetoFullNFE(
                            detalhe
                        ) ||
                        sku;
                }
            }


            unidades.push({

                variation_id:
                    variacao.id,

                user_product_id:
                    userProductId,

                inventory_id:
                    variacao
                        .inventory_id ||
                    null,

                sku:
                    sku ||
                    'SEM_SKU',

                available_quantity_item:
                    Number(
                        variacao
                            .available_quantity ||
                        0
                    )
            });


            await new Promise(
                resolve =>
                    setTimeout(
                        resolve,
                        70
                    )
            );
        }


    } else {

        unidades.push({

            variation_id:
                null,

            user_product_id:
                item
                    .user_product_id ||
                null,

            inventory_id:
                item
                    .inventory_id ||
                null,

            sku:
                extrairSellerSkuObjetoFullNFE(
                    item
                ) ||
                'SEM_SKU',

            available_quantity_item:
                Number(
                    item
                        .available_quantity ||
                    0
                )
        });
    }


    return {

        item,

        unidades,

        token
    };
}


// =========================================================
// CONSULTAR ESTOQUE DE UM USER PRODUCT
// =========================================================

async function consultarEstoqueUserProductFullNFE(
    userProductId,
    token
) {

    if (
        !userProductId
    ) {

        return {

            success:
                false,

            user_product_id:
                null,

            estoque_full:
                null,

            estoque_local:
                null,

            locations:
                [],

            tem_meli_facility:
                false,

            error:
                'Sem user_product_id'
        };
    }


    try {

        const {
            data,
            response
        } =
            await consultarGETMLFullNFE(

                `https://api.mercadolibre.com/user-products/${encodeURIComponent(
                    userProductId
                )}/stock`,

                token
            );


        const locations =
            Array.isArray(
                data
                    ?.locations
            )
                ? data.locations
                : [];


        const fullLocations =
            locations.filter(
                location =>
                    String(
                        location
                            ?.type ||
                        ''
                    )
                        .toLowerCase() ===
                    'meli_facility'
            );


        const localLocations =
            locations.filter(
                location => {

                    const tipo =
                        String(
                            location
                                ?.type ||
                            ''
                        )
                            .toLowerCase();


                    return (
                        tipo ===
                            'selling_address' ||
                        tipo ===
                            'seller_warehouse'
                    );
                }
            );


        const estoqueFull =
            fullLocations.reduce(
                (
                    total,
                    location
                ) =>
                    total +
                    Number(
                        location
                            ?.quantity ||
                        0
                    ),
                0
            );


        const estoqueLocal =
            localLocations.reduce(
                (
                    total,
                    location
                ) =>
                    total +
                    Number(
                        location
                            ?.quantity ||
                        0
                    ),
                0
            );


        return {

            success:
                true,

            user_product_id:
                userProductId,

            estoque_full:
                estoqueFull,

            estoque_local:
                estoqueLocal,

            tem_meli_facility:
                fullLocations.length >
                0,

            locations,

            x_version:
                response
                    ?.headers
                    ?.get(
                        'x-version'
                    ) ||
                null,

            error:
                null
        };


    } catch (
        error
    ) {

        console.warn(
            `⚠️ Erro buscando stock do UP ${userProductId}:`,
            error
        );


        return {

            success:
                false,

            user_product_id:
                userProductId,

            estoque_full:
                null,

            estoque_local:
                null,

            locations:
                [],

            tem_meli_facility:
                false,

            error:
                error.message
        };
    }
}

function montarChaveAlertaEstoqueVendaNFE(
    vendaOuId,
    mlb
) {

    const vendaId =
        normalizarOrderIdML(
            typeof vendaOuId === 'object'
                ? (
                    vendaOuId?.id_venda_ml ||
                    vendaOuId?.id
                )
                : vendaOuId
        );


    mlb =
        normalizarMLBFullNFE(
            mlb
        );


    if (
        !vendaId ||
        !mlb
    ) {

        return '';
    }


    return `${vendaId}|${mlb}`;
}


// =========================================================
// DETALHES / VARIAÇÕES DESTE MLB QUE PARTICIPARAM DA VENDA
// =========================================================

function obterDetalhesVendaNoMLBNFE(
    situacao,
    venda,
    mlb
) {

    mlb =
        normalizarMLBFullNFE(
            mlb
        );


    const todos =
        Array.isArray(
            situacao?.detalhes
        )
            ? situacao.detalhes
            : [];


    const orderItems =
        Array.isArray(
            venda?.order_items
        )
            ? venda.order_items.filter(
                orderItem =>
                    normalizarMLBFullNFE(
                        orderItem
                            ?.item
                            ?.id
                    ) ===
                    mlb
            )
            : [];


    const variationIds =
        new Set(
            orderItems
                .map(
                    orderItem =>
                        orderItem
                            ?.item
                            ?.variation_id
                )
                .filter(
                    id =>
                        id !==
                            null &&
                        id !==
                            undefined
                )
                .map(
                    id =>
                        String(
                            id
                        )
                )
        );


    if (
        variationIds.size >
        0
    ) {

        const encontrados =
            todos.filter(
                detalhe =>
                    variationIds.has(
                        String(
                            detalhe
                                .variation_id
                        )
                    )
            );


        if (
            encontrados.length >
            0
        ) {

            return encontrados;
        }
    }


    const skus =
        new Set(
            orderItems
                .map(
                    orderItem =>
                        String(
                            orderItem
                                ?.item
                                ?.seller_sku ||
                            ''
                        )
                            .trim()
                            .toUpperCase()
                )
                .filter(Boolean)
        );


    if (
        skus.size >
        0
    ) {

        const porSku =
            todos.filter(
                detalhe =>
                    skus.has(
                        String(
                            detalhe.sku ||
                            ''
                        )
                            .trim()
                            .toUpperCase()
                    )
            );


        if (
            porSku.length >
            0
        ) {

            return porSku;
        }
    }


    if (
        todos.length ===
        1
    ) {

        return todos;
    }


    return todos;
}


// =========================================================
// RESUMO DO ESTOQUE ML DAS VARIAÇÕES VENDIDAS
// =========================================================

function obterResumoEstoqueAtualVendaNFE(
    situacao,
    venda,
    mlb
) {

    const detalhes =
        obterDetalhesVendaNoMLBNFE(
            situacao,
            venda,
            mlb
        );


    const estoquesAnuncio =
        detalhes
            .map(
                detalhe =>
                    Number(
                        detalhe
                            .available_quantity_item
                    )
            )
            .filter(
                Number.isFinite
            );


    const estoquesLocal =
        detalhes
            .map(
                detalhe =>
                    detalhe
                        .estoque_local_ml
            )
            .filter(
                valor =>
                    valor !==
                        null &&
                    valor !==
                        undefined &&
                    Number.isFinite(
                        Number(
                            valor
                        )
                    )
            )
            .map(Number);


    const estoqueAnuncioMin =
        estoquesAnuncio.length >
        0

            ? Math.min(
                ...estoquesAnuncio
            )

            : null;


    const estoqueAnuncioTotal =
        estoquesAnuncio.reduce(
            (
                total,
                quantidade
            ) =>
                total +
                quantidade,
            0
        );


    const estoqueLocalMin =
        estoquesLocal.length >
        0

            ? Math.min(
                ...estoquesLocal
            )

            : null;


    const estoqueLocalTotal =
        estoquesLocal.reduce(
            (
                total,
                quantidade
            ) =>
                total +
                quantidade,
            0
        );


    const anuncioTemFull =
        Boolean(
            situacao
                ?.item_ainda_fulfillment
        ) ||
        detalhes.some(
            detalhe =>
                detalhe
                    .tem_meli_facility ===
                true
        );


    return {

        detalhes,

        estoque_anuncio_min:
            estoqueAnuncioMin,

        estoque_anuncio_total:
            estoqueAnuncioTotal,

        estoque_local_min:
            estoqueLocalMin,

        estoque_local_total:
            estoqueLocalTotal,

        algum_anuncio_zerado:
            estoquesAnuncio.some(
                quantidade =>
                    quantidade ===
                    0
            ),

        algum_local_zerado:
            estoquesLocal.some(
                quantidade =>
                    quantidade ===
                    0
            ),

        todos_anuncio_positivos:
            estoquesAnuncio.length >
                0 &&
            estoquesAnuncio.every(
                quantidade =>
                    quantidade >
                    0
            ),

        todos_local_positivos:
            estoquesLocal.length >
                0 &&
            estoquesLocal.every(
                quantidade =>
                    quantidade >
                    0
            ),

        anuncio_tem_full:
            anuncioTemFull
    };
}


// =========================================================
// BUSCAR ESTOQUE INTERNO SOMENTE DOS ITENS DESTA VENDA
// =========================================================

async function buscarProdutosCadastroVendaNFE(
    situacao,
    venda,
    mlb,
    todasVariacoes = false
) {

    const detalhes =
        todasVariacoes

            ? (
                Array.isArray(
                    situacao?.detalhes
                )
                    ? situacao.detalhes
                    : []
            )

            : obterDetalhesVendaNoMLBNFE(
                situacao,
                venda,
                mlb
            );


    return await buscarProdutosCadastroMLBFullNFE({

        ...situacao,

        detalhes
    });
}


function calcularResumoCadastroAnuncioNFE(
    cadastro
) {

    const detalhes =
        Array.isArray(
            cadastro?.detalhes
        )
            ? cadastro.detalhes
            : [];


    if (
        detalhes.length === 0
    ) {

        return {

            tem_cadastro:
                false,

            todos_cadastrados:
                false,

            tem_estoque:
                false,

            algum_estoque_fisico:
                false,

            estoque_vendavel_real:
                false,

            quantidade_total_anuncio:
                null
        };
    }


    const grupos =
        new Map();


    detalhes.forEach(
        item => {

            const chave =
                String(
                    item?.sku_anuncio ||
                    'SEM_SKU'
                );


            if (
                !grupos.has(
                    chave
                )
            ) {

                grupos.set(
                    chave,
                    []
                );
            }


            grupos
                .get(
                    chave
                )
                .push(
                    item
                );
        }
    );


    let temCadastro =
        false;


    let todosCadastrados =
        true;


    let algumEstoqueFisico =
        false;


    let quantidadeTotal =
        0;


    for (
        const itens
        of grupos.values()
    ) {

        const naoCadastrados =
            itens.filter(
                item =>
                    item?.encontrado !==
                    true
            );


        const cadastrados =
            itens.filter(
                item =>
                    item?.encontrado ===
                    true
            );


        if (
            cadastrados.length >
            0
        ) {

            temCadastro =
                true;
        }


        // =================================================
        // SE ALGUM COMPONENTE DO SKU/KIT NÃO FOI
        // ENCONTRADO, NÃO PODEMOS AFIRMAR QUE EXISTE
        // ESTOQUE VENDÁVEL.
        // =================================================

        if (
            naoCadastrados.length >
                0 ||
            cadastrados.length ===
                0
        ) {

            todosCadastrados =
                false;

            continue;
        }


        const capacidades =
            cadastrados.map(
                item => {

                    const estoque =
                        Math.max(
                            0,
                            Number(
                                item
                                    ?.estoque_atual ||
                                0
                            )
                        );


                    const precisa =
                        Math.max(
                            1,
                            Number(
                                item
                                    ?.quantidade_por_anuncio ||
                                1
                            )
                        );


                    if (
                        estoque >
                        0
                    ) {

                        algumEstoqueFisico =
                            true;
                    }


                    // Exemplo:
                    //
                    // Kit precisa:
                    // 1 eixo
                    // 1 arruela
                    //
                    // eixo = 0
                    // arruela = 100
                    //
                    // capacidade do KIT = 0
                    return Math.floor(
                        estoque /
                        precisa
                    );
                }
            );


        quantidadeTotal +=
            Math.min(
                ...capacidades
            );
    }


    const estoqueVendavelReal =

        temCadastro ===
            true &&

        todosCadastrados ===
            true &&

        quantidadeTotal >
            0;


    return {

        tem_cadastro:
            temCadastro,

        todos_cadastrados:
            todosCadastrados,

        // IMPORTANTE:
        // agora significa estoque realmente vendável,
        // e não "qualquer componente tem estoque".
        tem_estoque:
            estoqueVendavelReal,

        algum_estoque_fisico:
            algumEstoqueFisico,

        estoque_vendavel_real:
            estoqueVendavelReal,

        quantidade_total_anuncio:
            todosCadastrados
                ? quantidadeTotal
                : null
    };
}


// =========================================================
// COMPACTAR DETALHES ANTES DE SALVAR ALERTA
// =========================================================

function compactarDetalhesMonitorEstoqueNFE(
    detalhes
) {

    return (
        Array.isArray(
            detalhes
        )
            ? detalhes
            : []
    )
        .map(
            detalhe => ({

                variation_id:
                    detalhe.variation_id ??
                    null,

                user_product_id:
                    detalhe.user_product_id ||
                    null,

                sku:
                    detalhe.sku ||
                    null,

                estoque_full:
                    detalhe.estoque_full ??
                    null,

                estoque_local_ml:
                    detalhe.estoque_local_ml ??
                    null,

                available_quantity_item:
                    detalhe.available_quantity_item ??
                    null,

                tem_meli_facility:
                    Boolean(
                        detalhe
                            .tem_meli_facility
                    ),

                consulta_ok:
                    Boolean(
                        detalhe
                            .consulta_ok
                    )
            })
        );
}

async function consultarSituacaoMLBFullNFE(
    mlb
) {

    mlb =
        normalizarMLBFullNFE(
            mlb
        );


    if (
        !mlb
    ) {

        throw new Error(
            'MLB inválido'
        );
    }


    const regraFixa =
        await obterRegraFixaTipoAnuncioNFE(
            mlb
        );


    const {
        item,
        unidades,
        token
    } =
        await buscarEstruturaMLBFullNFE(
            mlb
        );


    const detalhes =
        [];


    // =====================================================
    // CONSULTAR TODAS AS VARIAÇÕES / USER PRODUCTS
    //
    // MUITO IMPORTANTE:
    // FULL zerado é referente ao ANÚNCIO TODO,
    // não somente à variação que acabou de vender.
    // =====================================================

    for (
        let i = 0;
        i < unidades.length;
        i++
    ) {

        const unidade =
            unidades[
                i
            ];


        const estoque =
            await consultarEstoqueUserProductFullNFE(

                unidade
                    .user_product_id,

                token
            );


        detalhes.push({

            ...unidade,

            consulta_ok:
                estoque.success ===
                true,


            // =============================================
            // NÃO TRANSFORMAR FALHA DE CONSULTA EM ZERO.
            //
            // Esse era um dos riscos de gerar
            // FULL ZERADO incorretamente.
            // =============================================

            estoque_full:

                estoque.success ===
                    true &&

                Number.isFinite(
                    Number(
                        estoque
                            .estoque_full
                    )
                )

                    ? Number(
                        estoque
                            .estoque_full
                    )

                    : null,


            estoque_local_ml:

                estoque.success ===
                    true &&

                Number.isFinite(
                    Number(
                        estoque
                            .estoque_local
                    )
                )

                    ? Number(
                        estoque
                            .estoque_local
                    )

                    : null,


            tem_meli_facility:

                estoque.success ===
                    true

                    ? estoque
                        .tem_meli_facility ===
                        true

                    : null,


            locations:

                Array.isArray(
                    estoque.locations
                )

                    ? estoque.locations

                    : [],


            erro:
                estoque.error ||
                null
        });


        if (
            i <
            unidades.length -
                1
        ) {

            await new Promise(
                resolve =>
                    setTimeout(
                        resolve,
                        650
                    )
            );
        }
    }


    // =====================================================
    // TODAS AS VARIAÇÕES FORAM CONSULTADAS?
    // =====================================================

    const todosConsultados =

        detalhes.length >
            0 &&

        detalhes.every(
            detalhe =>
                detalhe
                    .consulta_ok ===
                true
        );


    // =====================================================
    // TOTAL FULL DO ANÚNCIO TODO
    // =====================================================

    const estoqueTotalFull =
        detalhes.reduce(
            (
                total,
                detalhe
            ) => {

                const numero =
                    Number(
                        detalhe
                            .estoque_full
                    );


                return (
                    total +
                    (
                        Number.isFinite(
                            numero
                        )
                            ? numero
                            : 0
                    )
                );
            },
            0
        );


    // =====================================================
    // TOTAL LOCAL ML DO ANÚNCIO TODO
    // =====================================================

    const estoqueTotalLocal =
        detalhes.reduce(
            (
                total,
                detalhe
            ) => {

                const numero =
                    Number(
                        detalhe
                            .estoque_local_ml
                    );


                return (
                    total +
                    (
                        Number.isFinite(
                            numero
                        )
                            ? numero
                            : 0
                    )
                );
            },
            0
        );


    // =====================================================
    // QUANTIDADE TOTAL DISPONÍVEL NO ANÚNCIO
    //
    // Soma todas as variações.
    // =====================================================

    const estoqueTotalAnuncioVariacoes =
        detalhes.reduce(
            (
                total,
                detalhe
            ) => {

                const quantidade =
                    Number(
                        detalhe
                            .available_quantity_item
                    );


                return (
                    total +
                    (
                        Number.isFinite(
                            quantidade
                        )
                            ? quantidade
                            : 0
                    )
                );
            },
            0
        );


    const estoqueTotalAnuncioItem =
        Number.isFinite(
            Number(
                item
                    ?.available_quantity
            )
        )

            ? Number(
                item
                    .available_quantity
            )

            : 0;


    const estoqueTotalAnuncio =
        Math.max(

            estoqueTotalAnuncioVariacoes,

            estoqueTotalAnuncioItem
        );


    // =====================================================
    // FULL ZEROU?
    //
    // SOMENTE TRUE SE:
    //
    // 1. todas as variações foram consultadas;
    // 2. todas as variações possuem FULL = 0.
    //
    // Se 1 variação tiver FULL = 2:
    // NÃO ZEROU O FULL DO ANÚNCIO.
    // =====================================================

    const todosFullZerados =

        todosConsultados ===
            true &&

        detalhes.every(
            detalhe =>
                Number(
                    detalhe
                        .estoque_full ||
                    0
                ) ===
                0
        );


    const algumaVariacaoFullComEstoque =

        todosConsultados ===
            true &&

        detalhes.some(
            detalhe =>
                Number(
                    detalhe
                        .estoque_full ||
                    0
                ) >
                0
        );


    // =====================================================
    // EXPOSIÇÃO ATUAL
    // =====================================================

    const listingTypeAtual =
        String(
            item
                ?.listing_type_id ||
            ''
        )
            .trim()
            .toLowerCase();


    // =====================================================
    // QUANTIDADE PARA REGRA DE EXPOSIÇÃO
    //
    // REGRA:
    //
    // 1 unidade  = CLÁSSICO
    // 2 ou mais  = PREMIUM
    //
    // Usa o estoque disponível do anúncio.
    // Se ML não retornar available_quantity corretamente,
    // usa FULL + LOCAL como fallback.
    // =====================================================

    const quantidadeBaseExposicao =

        estoqueTotalAnuncio >
            0

            ? estoqueTotalAnuncio

            : (
                estoqueTotalFull +
                estoqueTotalLocal
            );


    let listingTypeEsperado =
        null;


    let origemRegraExposicao =
        null;


    // =====================================================
    // REGRA FIXA GANHA SEMPRE
    // =====================================================

    if (
        regraFixa
    ) {

        listingTypeEsperado =
            regraFixa.tipo;


        origemRegraExposicao =
            'regra_fixa';


    } else if (
        quantidadeBaseExposicao >
        0
    ) {

        // Já existe no sistema e está correta:
        //
        // 1  -> gold_special = Clássico
        // 2+ -> gold_pro     = Premium
        listingTypeEsperado =
            obterListingTypeEsperadoFullNFE(
                quantidadeBaseExposicao
            );


        origemRegraExposicao =
            'estoque_anuncio';
    }


    // =====================================================
    // INFORMAÇÕES DE LOGÍSTICA DO ITEM
    //
    // Apenas diagnóstico.
    // =====================================================

    const logisticType =
        String(

            item
                ?.shipping
                ?.logistic_type ||

            item
                ?.logistic_type ||

            ''
        )
            .trim()
            .toLowerCase();


    const tags =
        [

            ...(
                Array.isArray(
                    item?.tags
                )
                    ? item.tags
                    : []
            ),

            ...(
                Array.isArray(
                    item
                        ?.shipping
                        ?.tags
                )
                    ? item.shipping.tags
                    : []
            )
        ]
            .map(
                tag =>
                    String(
                        tag ||
                        ''
                    )
                        .trim()
                        .toLowerCase()
            );


    const itemAindaFulfillment =

        logisticType ===
            'fulfillment' ||

        tags.includes(
            'fulfillment'
        );


    // =====================================================
    // ESTÁ REALMENTE NO FULL?
    //
    // Fonte utilizada para confirmação:
    //
    // /user-products/{UP}/stock
    //
    // Se ALGUMA variação ainda possui uma location
    // meli_facility, o anúncio ainda possui vínculo FULL.
    //
    // Isso funciona mesmo com quantity = 0.
    //
    // Se nenhuma possui meli_facility, consideramos
    // saída do FULL confirmada.
    //
    // Se alguma consulta falhou:
    // NÃO afirmamos que saiu do FULL.
    // =====================================================

    const aindaTemLocationFull =

        todosConsultados ===
            true

            ? detalhes.some(
                detalhe =>
                    detalhe
                        .tem_meli_facility ===
                    true
            )

            : null;


    const aindaEstaNoFull =

        todosConsultados ===
            true

            ? aindaTemLocationFull ===
                true

            : null;


    const saiuDoFull =

        todosConsultados ===
            true &&

        aindaEstaNoFull ===
            false;


    // =====================================================
    // EXPOSIÇÃO
    // =====================================================

    const exposicaoCorreta =

        listingTypeEsperado

            ? (
                listingTypeAtual ===
                listingTypeEsperado
            )

            : true;


    return {

        mlb,


        titulo:
            item
                ?.title ||
            '',


        item,


        detalhes,


        total_variacoes:
            detalhes.length,


        todos_consultados:
            todosConsultados,


        estoque_total_full:
            estoqueTotalFull,


        estoque_total_local_ml:
            estoqueTotalLocal,


        estoque_total_anuncio:
            estoqueTotalAnuncio,


        quantidade_base_exposicao:
            quantidadeBaseExposicao,


        todos_full_zerados:
            todosFullZerados,


        alguma_variacao_full_com_estoque:
            algumaVariacaoFullComEstoque,


        logistic_type:
            logisticType,


        item_ainda_fulfillment:
            itemAindaFulfillment,


        ainda_tem_location_full:
            aindaTemLocationFull,


        ainda_esta_no_full:
            aindaEstaNoFull,


        saiu_do_full:
            saiuDoFull,


        listing_type_atual:
            listingTypeAtual,


        listing_type_atual_nome:
            nomeListingTypeFullNFE(
                listingTypeAtual
            ),


        listing_type_esperado:
            listingTypeEsperado,


        listing_type_esperado_nome:
            nomeListingTypeFullNFE(
                listingTypeEsperado
            ),


        exposicao_correta:
            exposicaoCorreta,


        possui_regra_fixa:
            Boolean(
                regraFixa
            ),


        regra_fixa:
            regraFixa,


        origem_regra_exposicao:
            origemRegraExposicao
    };
}


// =========================================================
// BUSCAR PRODUTOS DO CADASTRO PARA TODOS OS SKUS DO MLB
// =========================================================

async function buscarProdutosCadastroMLBFullNFE(
    situacao
) {

    const detalhes =
        Array.isArray(
            situacao
                ?.detalhes
        )
            ? situacao.detalhes
            : [];


    const mapaProdutos =
        new Map();


    const resultado =
        [];


    for (
        const detalhe
        of detalhes
    ) {

        const skuAnuncio =
            String(
                detalhe
                    ?.sku ||
                ''
            ).trim();


        if (
            !skuAnuncio ||
            skuAnuncio ===
                'SEM_SKU'
        ) {

            resultado.push({

                sku_anuncio:
                    skuAnuncio ||
                    'SEM_SKU',

                encontrado:
                    false,

                motivo:
                    'Variação sem SKU'
            });


            continue;
        }


        let componentes =
            [];


        try {

            componentes =
                decomporSkuCompostoNFE(

                    skuAnuncio,

                    1
                ) ||
                [];

        } catch (
            error
        ) {

            console.warn(
                `⚠️ Erro decompondo ${skuAnuncio}:`,
                error
            );
        }


        if (
            componentes.length ===
            0
        ) {

            componentes = [
                {
                    sku:
                        skuAnuncio,

                    quantidade_venda:
                        1
                }
            ];
        }


        for (
            const componente
            of componentes
        ) {

            const skuComponente =
                String(
                    componente
                        ?.sku ||
                    ''
                ).trim();


            if (
                !skuComponente
            ) {

                continue;
            }


            try {

                const {
                    produto,
                    error
                } =
                    await buscarProdutoEstoquePorSkuNFE(
                        skuComponente
                    );


                if (
                    error ||
                    !produto
                ) {

                    resultado.push({

                        sku_anuncio:
                            skuAnuncio,

                        sku:
                            skuComponente,

                        encontrado:
                            false,

                        motivo:
                            'Não cadastrado no estoque'
                    });


                    continue;
                }


                const chave =
                    String(
                        produto.id ||
                        produto.sku
                    );


                if (
                    !mapaProdutos.has(
                        chave
                    )
                ) {

                    mapaProdutos.set(
                        chave,
                        produto
                    );
                }


                resultado.push({

                    sku_anuncio:
                        skuAnuncio,

                    sku:
                        produto.sku,

                    produto_id:
                        produto.id,

                    nome:
                        produto.nome ||
                        '',

                    encontrado:
                        true,

                    estoque_atual:
                        Number(
                            produto
                                .quantidade ||
                            0
                        ),

                    quantidade_por_anuncio:
                        Number(
                            componente
                                .quantidade_venda ||
                            1
                        )
                });


            } catch (
                error
            ) {

                resultado.push({

                    sku_anuncio:
                        skuAnuncio,

                    sku:
                        skuComponente,

                    encontrado:
                        false,

                    motivo:
                        error.message
                });
            }
        }
    }


    return {

        produtos:
            Array.from(
                mapaProdutos
                    .values()
            ),

        detalhes:
            resultado
    };
}

async function salvarEstadoFullNFE(
    estado
) {

    const mlb =
        normalizarMLBFullNFE(
            estado?.mlb
        );


    const vendaId =
        normalizarOrderIdML(
            estado
                ?.venda_id_origem
        );


    const chaveAlerta =
        String(
            estado
                ?.chave_alerta ||
            montarChaveAlertaEstoqueVendaNFE(
                vendaId,
                mlb
            )
        )
            .trim();


    if (
        !mlb ||
        !vendaId ||
        !chaveAlerta
    ) {

        return false;
    }


    const anterior =
        window
            ._estadosFullNFE
            .get(
                chaveAlerta
            ) ||
        {};


    const ativo =
        Boolean(
            estado.ativo
        );


    const payload = {

        chave_alerta:
            chaveAlerta,

        mlb,

        ativo,

        status:
            estado.status ||
            anterior.status ||
            'monitorando',

        venda_id_origem:
            vendaId,

        full_total:
            estado.full_total ??
            anterior.full_total ??
            null,

        listing_type_atual:
            estado.listing_type_atual ??
            anterior.listing_type_atual ??
            null,

        listing_type_esperado:
            estado.listing_type_esperado ??
            anterior.listing_type_esperado ??
            null,

        mensagem:
            estado.mensagem ??
            anterior.mensagem ??
            null,

        detalhes_variacoes:
            Array.isArray(
                estado.detalhes_variacoes
            )
                ? estado.detalhes_variacoes
                : (
                    Array.isArray(
                        anterior.detalhes_variacoes
                    )
                        ? anterior.detalhes_variacoes
                        : []
                ),

        estoque_local:
            Array.isArray(
                estado.estoque_local
            )
                ? estado.estoque_local
                : (
                    Array.isArray(
                        anterior.estoque_local
                    )
                        ? anterior.estoque_local
                        : []
                ),

        detalhes_sync:
            [],

        resumo_automatico: {

            ...(
                anterior.resumo_automatico ||
                {}
            ),

            ...(
                estado.resumo_automatico ||
                {}
            )
        },

        full_retirado_confirmado:
            Boolean(
                estado
                    .full_retirado_confirmado
            ),

        sync_local_executado:
            false,

        sync_local_sucesso:
            null,

        ultima_verificacao_em:
            new Date()
                .toISOString(),

        resolvido_em:
            ativo
                ? null
                : (
                    estado.resolvido_em ||
                    anterior.resolvido_em ||
                    new Date()
                        .toISOString()
                ),

        resolvido_por_username:
            estado
                .resolvido_por_username ??
            anterior
                .resolvido_por_username ??
            null,

        resolvido_por_nome:
            estado
                .resolvido_por_nome ??
            anterior
                .resolvido_por_nome ??
            null
    };


    // =====================================================
    // MEMÓRIA + CACHE PRIMEIRO
    // =====================================================

    window
        ._estadosFullNFE
        .set(
            chaveAlerta,
            payload
        );


    persistirEstadosFullLocalNFE();


    if (
        typeof aplicarEstadosFullTabelaNFE ===
        'function'
    ) {

        aplicarEstadosFullTabelaNFE();
    }


    // =====================================================
    // SUPABASE EM SEGUNDO PLANO DA OPERAÇÃO
    // =====================================================

    try {

        const {
            error
        } =
            await window
                .supabaseClient
                .from(
                    'alertas_full_nfe'
                )
                .upsert(
                    payload,
                    {
                        onConflict:
                            'chave_alerta'
                    }
                );


        if (
            error
        ) {

            throw error;
        }


        return true;


    } catch (
        error
    ) {

        console.error(
            `❌ Erro salvando alerta ${chaveAlerta}:`,
            error
        );


        return false;
    }
}


async function carregarEstadosFullNFE(
    consultarBanco = true
) {

    hidratarEstadosFullLocalNFE();


    if (
        typeof hidratarRegrasFixasTipoAnuncioLocalNFE ===
        'function'
    ) {

        hidratarRegrasFixasTipoAnuncioLocalNFE();
    }


    if (
        typeof reconciliarEstadosFullComRegrasFixasNFE ===
        'function'
    ) {

        reconciliarEstadosFullComRegrasFixasNFE();
    }


    if (
        !consultarBanco
    ) {

        return window
            ._estadosFullNFE;
    }


    try {

        const {
            data,
            error
        } =
            await window
                .supabaseClient
                .from(
                    'alertas_full_nfe'
                )
                .select('*');


        if (
            error
        ) {

            throw error;
        }


        const mapa =
            new Map();


        (
            Array.isArray(
                data
            )
                ? data
                : []
        )
            .forEach(
                estado => {

                    const chave =
                        String(
                            estado
                                ?.chave_alerta ||
                            ''
                        )
                            .trim();


                    if (
                        chave
                    ) {

                        mapa.set(
                            chave,
                            estado
                        );
                    }
                }
            );


        window._estadosFullNFE =
            mapa;


        reconciliarEstadosFullComRegrasFixasNFE();


        persistirEstadosFullLocalNFE();


        aplicarEstadosFullTabelaNFE();


        return mapa;


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Não foi possível atualizar alertas pelo Supabase:',
            error
        );


        return window
            ._estadosFullNFE;
    }
}


// =========================================================
// MLBs DA VENDA
// =========================================================

function obterMLBsVendaFullNFE(
    venda
) {

    const ids =
        [];


    if (
        typeof obterAnunciosVendaNFE ===
        'function'
    ) {

        const anuncios =
            obterAnunciosVendaNFE(
                venda
            );


        anuncios.forEach(
            anuncio => {

                const mlb =
                    normalizarMLBFullNFE(
                        anuncio.id
                    );


                if (
                    mlb
                ) {

                    ids.push(
                        mlb
                    );
                }
            }
        );
    }


    if (
        Array.isArray(
            venda?.order_items
        )
    ) {

        venda.order_items
            .forEach(
                orderItem => {

                    const mlb =
                        normalizarMLBFullNFE(
                            orderItem
                                ?.item
                                ?.id
                        );


                    if (
                        mlb
                    ) {

                        ids.push(
                            mlb
                        );
                    }
                }
            );
    }


    return [
        ...new Set(
            ids
        )
    ];
}

function instalarListenerRegrasFixasMonitorFullNFE() {

    if (
        window
            ._listenerRegrasFixasMonitorFullNFE
    ) {

        return;
    }


    window
        ._listenerRegrasFixasMonitorFullNFE =
        true;


    window.addEventListener(
        'wheeltech:regras-fixas-tipo-anuncio-atualizadas',
        event => {

            const regras =
                normalizarRegrasFixasTipoAnuncioNFE(
                    event
                        ?.detail
                        ?.regras ||
                    {}
                );


            window._regrasFixasTipoAnuncioNFE =
                regras;


            window._regrasFixasTipoAnuncioNFELidasEm =
                Date.now();


            reconciliarEstadosFullComRegrasFixasNFE();


            aplicarEstadosFullTabelaNFE();


            console.log(
                '🔒 Regras fixas atualizadas no monitor:',
                regras
            );
        }
    );
}


async function confirmarAjusteAnuncioFullNFE(
    chaveOuMlb
) {

    const texto =
        String(
            chaveOuMlb ||
            ''
        )
            .trim();


    let estado =

        window
            ._estadosFullNFE
            ?.get(
                texto
            ) ||

        null;


    // =====================================================
    // FALLBACK SE RECEBEU MLB EM VEZ DA CHAVE DO ALERTA
    // =====================================================

    if (
        !estado
    ) {

        const mlbRecebido =
            normalizarMLBFullNFE(
                texto
            );


        estado =
            Array.from(

                window
                    ._estadosFullNFE
                    ?.values?.() ||

                []
            )
                .find(
                    item =>

                        item
                            ?.ativo ===
                            true &&

                        normalizarMLBFullNFE(
                            item?.mlb
                        ) ===
                        mlbRecebido
                ) ||

            null;
    }


    if (
        !estado
    ) {

        showToast(
            '❌ Alerta não encontrado.',
            'error'
        );

        return;
    }


    const mlb =
        normalizarMLBFullNFE(
            estado.mlb
        );


    const vendaId =
        normalizarOrderIdML(
            estado
                .venda_id_origem
        );


    const venda =
        (
            Array.isArray(
                vendasPendentes
            )
                ? vendasPendentes
                : []
        )
            .find(
                item =>
                    normalizarOrderIdML(

                        item
                            ?.id_venda_ml ||

                        item
                            ?.id

                    ) ===
                    vendaId
            ) ||

        null;


    if (
        !mlb ||
        !venda
    ) {

        showToast(
            '❌ Venda ou anúncio não localizado na tela.',
            'error'
        );

        return;
    }


    try {

        showToast(
            `🔎 Conferindo novamente ${mlb} no Mercado Livre...`,
            'info'
        );


        // =====================================================
        // CONSULTA FRESCA
        // =====================================================

        const situacao =
            await consultarSituacaoMLBFullNFE(
                mlb
            );


        // =====================================================
        // NÃO ACEITAR COM CONSULTA PARCIAL
        //
        // Evita:
        // 1 variação = 0
        // outras não consultadas
        // → sistema acreditar que FULL zerou.
        // =====================================================

        if (
            situacao
                .todos_consultados !==
            true
        ) {

            showToast(
                '❌ Não foi possível consultar todas as variações do anúncio. O ajuste não será aceito.',
                'error'
            );

            return;
        }


        console.log(
            '🔎 VALIDAÇÃO AJUSTE MLB:',
            {

                mlb,

                total_variacoes:
                    situacao
                        .total_variacoes,

                estoque_anuncio:
                    situacao
                        .estoque_total_anuncio,

                estoque_full_total:
                    situacao
                        .estoque_total_full,

                estoque_local_total:
                    situacao
                        .estoque_total_local_ml,

                todos_full_zerados:
                    situacao
                        .todos_full_zerados,

                ainda_tem_location_full:
                    situacao
                        .ainda_tem_location_full,

                ainda_esta_no_full:
                    situacao
                        .ainda_esta_no_full,

                saiu_do_full:
                    situacao
                        .saiu_do_full,

                exposicao_atual:
                    situacao
                        .listing_type_atual,

                exposicao_esperada:
                    situacao
                        .listing_type_esperado
            }
        );


        // =====================================================
        // REPROCESSAR COM A CONSULTA NOVA
        // =====================================================

        const novoEstado =
            await processarMLBMonitorFullNFE(

                mlb,

                venda,

                {

                    forcar:
                        true,

                    situacaoPrecarregada:
                        situacao
                }
            );


        if (
            !novoEstado
        ) {

            showToast(
                '❌ Não foi possível validar o ajuste.',
                'error'
            );

            return;
        }


        const resumo =
            novoEstado
                .resumo_automatico ||
            {};


        const usuario =
            obterUsuarioOperacaoNFE();


        // =====================================================
        // FULL ZERADO MAS AINDA ESTÁ NO FULL
        //
        // NÃO ACEITAR.
        //
        // Mesmo com:
        // FULL = 0
        //
        // se ainda existe meli_facility:
        // continua vinculado ao FULL.
        // =====================================================

        if (
            novoEstado.status ===
            'full_zero_aguardando_ajuste'
        ) {

            showToast(
                '❌ Todas as variações FULL estão zeradas, mas o anúncio ainda possui localização meli_facility. Retire o anúncio do FULL e tente novamente.',
                'error'
            );

            return;
        }


        // =====================================================
        // ANÚNCIO CONTINUA ZERADO
        // =====================================================

        if (
            novoEstado.status ===
            'anuncio_zero'
        ) {

            // =============================================
            // TEM ESTOQUE INTERNO:
            //
            // NÃO PODE ACEITAR AJUSTADO.
            // =============================================

            if (
                resumo
                    .estoque_vendavel_real ===
                true
            ) {

                showToast(
                    `❌ O anúncio continua zerado no Mercado Livre e existem ${Number(
                        resumo
                            .estoque_cadastro_anuncio_total ||
                        0
                    )} un. vendáveis no estoque interno. Adicione estoque ao anúncio e clique em Ajustado novamente.`,
                    'error'
                );

                return;
            }


            // =============================================
            // NÃO HÁ ESTOQUE VENDÁVEL:
            //
            // pode aceitar permanecer zerado.
            // =============================================

            await salvarEstadoFullNFE({

                ...novoEstado,

                ativo:
                    false,

                status:
                    'anuncio_zero_aceito',

                mensagem:
                    'Anúncio zerado aceito porque não há estoque interno vendável para este anúncio.',

                resumo_automatico: {

                    ...resumo,

                    zero_anuncio_aceito:
                        true
                },

                resolvido_em:
                    new Date()
                        .toISOString(),

                resolvido_por_username:
                    usuario.username,

                resolvido_por_nome:
                    usuario.nome
            });


            aplicarEstadosFullTabelaNFE();


            showToast(
                '✅ Anúncio zerado confirmado. Não há estoque interno vendável.',
                'success'
            );


            return;
        }


        // =====================================================
        // DEPÓSITO LOCAL CONTINUA ZERADO
        // =====================================================

        if (
            novoEstado.status ===
            'deposito_zero'
        ) {

            if (
                resumo
                    .estoque_vendavel_real ===
                true
            ) {

                showToast(
                    `❌ O depósito/local continua zerado e existem ${Number(
                        resumo
                            .estoque_cadastro_anuncio_total ||
                        0
                    )} un. vendáveis no estoque interno. Adicione estoque ao depósito e tente novamente.`,
                    'error'
                );

                return;
            }


            // Sem estoque interno vendável:
            // pode permanecer zero.
            await salvarEstadoFullNFE({

                ...novoEstado,

                ativo:
                    false,

                status:
                    'deposito_zero_aceito_sem_cadastro',

                mensagem:
                    'Depósito zerado aceito porque não há estoque interno vendável.',

                resumo_automatico: {

                    ...resumo,

                    zero_deposito_aceito:
                        true
                },

                resolvido_em:
                    new Date()
                        .toISOString(),

                resolvido_por_username:
                    usuario.username,

                resolvido_por_nome:
                    usuario.nome
            });


            aplicarEstadosFullTabelaNFE();


            showToast(
                '✅ Depósito zerado confirmado. Não há estoque interno vendável.',
                'success'
            );


            return;
        }


        // =====================================================
        // EXPOSIÇÃO CONTINUA ERRADA
        // =====================================================

        if (
            novoEstado.status ===
            'exposicao_pendente'
        ) {

            showToast(
                `❌ A exposição ainda está ${nomeListingTypeFullNFE(
                    novoEstado
                        .listing_type_atual
                )}. O correto é ${nomeListingTypeFullNFE(
                    novoEstado
                        .listing_type_esperado
                )}.`,
                'error'
            );

            return;
        }


        // =====================================================
        // ESTÁ CORRETO AGORA
        // =====================================================

        if (
            novoEstado.ativo ===
            false
        ) {

            await salvarEstadoFullNFE({

                ...novoEstado,

                ativo:
                    false,

                resolvido_em:
                    new Date()
                        .toISOString(),

                resolvido_por_username:
                    usuario.username,

                resolvido_por_nome:
                    usuario.nome
            });


            aplicarEstadosFullTabelaNFE();


            if (
                novoEstado.status ===
                'full_zero_resolvido'
            ) {

                showToast(
                    '✅ Saída do FULL confirmada. O alerta foi encerrado.',
                    'success'
                );


            } else {

                showToast(
                    '✅ Ajuste confirmado. O alerta foi encerrado.',
                    'success'
                );
            }


            return;
        }


        aplicarEstadosFullTabelaNFE();


        showToast(
            '⚠️ O ajuste ainda não foi confirmado.',
            'warning'
        );


    } catch (
        error
    ) {

        console.error(
            `❌ Erro verificando ajuste ${mlb}:`,
            error
        );


        showToast(
            `❌ ${error.message}`,
            'error'
        );
    }
}

async function processarMLBMonitorFullNFE(
    mlb,
    venda,
    opcoes = {}
) {

    mlb =
        normalizarMLBFullNFE(
            mlb
        );


    const vendaId =
        normalizarOrderIdML(

            venda
                ?.id_venda_ml ||

            venda
                ?.id
        );


    const chaveAlerta =
        montarChaveAlertaEstoqueVendaNFE(
            vendaId,
            mlb
        );


    if (
        !mlb ||
        !vendaId ||
        !chaveAlerta ||
        !venda
    ) {

        return null;
    }


    try {

        const situacao =

            opcoes
                .situacaoPrecarregada ||

            await consultarSituacaoMLBFullNFE(
                mlb
            );


        const estadoAnterior =

            window
                ._estadosFullNFE
                ?.get(
                    chaveAlerta
                ) ||

            null;


        // =====================================================
        // CONSULTA INCOMPLETA
        //
        // NÃO criar alerta FULL ZERADO com informação parcial.
        //
        // Exemplo:
        //
        // 5 variações:
        // 1 consultada = FULL 0
        // 4 falharam
        //
        // NÃO podemos dizer que o anúncio inteiro zerou.
        // =====================================================

        if (
            situacao
                .todos_consultados !==
            true
        ) {

            if (
                estadoAnterior
            ) {

                return estadoAnterior;
            }


            const estadoErro = {

                chave_alerta:
                    chaveAlerta,

                mlb,

                venda_id_origem:
                    vendaId,

                ativo:
                    false,

                status:
                    'erro_consulta',

                full_total:
                    null,

                listing_type_atual:
                    situacao
                        .listing_type_atual ||
                    null,

                listing_type_esperado:
                    situacao
                        .listing_type_esperado ||
                    null,

                mensagem:
                    'Não foi possível consultar todas as variações do anúncio.',

                detalhes_variacoes:
                    compactarDetalhesMonitorEstoqueNFE(
                        situacao.detalhes
                    ),

                estoque_local:
                    [],

                resumo_automatico: {

                    contexto:
                        'erro_consulta',

                    estoque_full_atual:
                        situacao
                            .estoque_total_full,

                    estoque_local_ml_atual:
                        situacao
                            .estoque_total_local_ml,

                    estoque_anuncio_total_ml:
                        situacao
                            .estoque_total_anuncio
                },

                full_retirado_confirmado:
                    false
            };


            await salvarEstadoFullNFE(
                estadoErro
            );


            return estadoErro;
        }


        // =====================================================
        // MODALIDADE DA VENDA
        // =====================================================

        const vendaFull =

            Boolean(
                venda
                    ?._is_full
            ) ||

            detectarVendaFullNFE(
                venda
            );


        // =====================================================
        // ESTOQUE DAS VARIAÇÕES QUE PARTICIPARAM DESTA VENDA
        //
        // Para venda fora do FULL, é isso que usamos para
        // descobrir se aquela variação ficou zerada.
        // =====================================================

        const resumoVenda =
            obterResumoEstoqueAtualVendaNFE(

                situacao,

                venda,

                mlb
            );


        // =====================================================
        // ESTOQUE INTERNO
        //
        // SOMENTE produtos/SKUs ligados à venda.
        // =====================================================

        const cadastro =
            await buscarProdutosCadastroVendaNFE(

                situacao,

                venda,

                mlb,

                false
            );


        const resumoCadastro =
            calcularResumoCadastroAnuncioNFE(
                cadastro
            );


        const estoqueVendavelReal =

            resumoCadastro
                .estoque_vendavel_real ===
            true;


        // =====================================================
        // RESUMO COMUM
        // =====================================================

        const resumoAutomaticoBase = {

            venda_full:
                vendaFull,


            estoque_full_atual:
                Number(
                    situacao
                        .estoque_total_full ||
                    0
                ),


            estoque_local_ml_atual:
                Number(
                    situacao
                        .estoque_total_local_ml ||
                    0
                ),


            estoque_anuncio_total_ml:
                Number(
                    situacao
                        .estoque_total_anuncio ||
                    0
                ),


            // Estoque da variação vendida
            estoque_anuncio_venda:
                resumoVenda
                    .estoque_anuncio_min,


            estoque_local_venda:
                resumoVenda
                    .estoque_local_min,


            exposicao_atual:
                situacao
                    .listing_type_atual ||
                '',


            exposicao_atual_nome:
                situacao
                    .listing_type_atual_nome ||
                '',


            exposicao_esperada:
                situacao
                    .listing_type_esperado ||
                '',


            exposicao_esperada_nome:
                situacao
                    .listing_type_esperado_nome ||
                '',


            origem_regra_exposicao:
                situacao
                    .origem_regra_exposicao ||
                '',


            possui_regra_fixa:
                situacao
                    .possui_regra_fixa ===
                true,


            regra_fixa_nome:
                situacao
                    .regra_fixa
                    ?.nome ||
                null,


            regra_fixa_tipo:
                situacao
                    .regra_fixa
                    ?.tipo ||
                null,


            // =============================================
            // ESTOQUE INTERNO
            // =============================================

            estoque_cadastro_encontrado:
                resumoCadastro
                    .tem_cadastro ===
                true,


            todos_cadastrados:
                resumoCadastro
                    .todos_cadastrados ===
                true,


            tem_estoque_cadastro:
                estoqueVendavelReal,


            estoque_vendavel_real:
                estoqueVendavelReal,


            estoque_cadastro_anuncio_total:
                resumoCadastro
                    .quantidade_total_anuncio,


            // =============================================
            // FULL
            // =============================================

            saiu_do_full:
                situacao
                    .saiu_do_full ===
                true,


            ainda_esta_no_full:
                situacao
                    .ainda_esta_no_full ===
                true,


            todas_variacoes_full_zeradas:
                situacao
                    .todos_full_zerados ===
                true
        };


        const estadoBase = {

            chave_alerta:
                chaveAlerta,

            mlb,

            venda_id_origem:
                vendaId,

            full_total:
                Number(
                    situacao
                        .estoque_total_full ||
                    0
                ),

            listing_type_atual:
                situacao
                    .listing_type_atual ||
                null,

            listing_type_esperado:
                situacao
                    .listing_type_esperado ||
                null,

            detalhes_variacoes:
                compactarDetalhesMonitorEstoqueNFE(
                    situacao.detalhes
                ),

            // Aqui ficam os dados do estoque interno,
            // usados pelo card.
            estoque_local:

                Array.isArray(
                    cadastro
                        ?.detalhes
                )

                    ? cadastro.detalhes

                    : [],

            full_retirado_confirmado:
                false
        };


        // =====================================================
        // SALVAR + RETORNAR
        // =====================================================

        const salvarERetornar =
            async parcial => {

                const estado = {

                    ...estadoBase,

                    ...parcial,

                    resumo_automatico: {

                        ...resumoAutomaticoBase,

                        ...(
                            parcial
                                .resumo_automatico ||
                            {}
                        )
                    }
                };


                await salvarEstadoFullNFE(
                    estado
                );


                return estado;
            };


        // =====================================================
        // VENDA FULL
        // =====================================================

        if (
            vendaFull
        ) {

            // =================================================
            // FULL ESGOTOU O ANÚNCIO TODO?
            //
            // NÃO usa somente a variação vendida.
            //
            // Exemplo:
            //
            // Variação A = 0
            // Variação B = 2
            //
            // todos_full_zerados = FALSE
            //
            // portanto NÃO mostra FULL ESGOTADO.
            // =================================================

            if (
                situacao
                    .todos_full_zerados ===
                true
            ) {

                const quantidadeCadastro =
                    Number(
                        resumoCadastro
                            .quantidade_total_anuncio ||
                        0
                    );


                // Quando zerou no ML, podemos recomendar
                // exposição com base no estoque interno.
                //
                // Regra fixa continua ganhando.
                const esperadoComEstoqueInterno =

                    situacao
                        .regra_fixa
                        ?.tipo ||

                    (
                        quantidadeCadastro >
                        0

                            ? obterListingTypeEsperadoFullNFE(
                                quantidadeCadastro
                            )

                            : (
                                situacao
                                    .listing_type_esperado ||
                                null
                            )
                    );


                // =================================================
                // Ainda possui meli_facility?
                //
                // SIM = continua no FULL.
                // NÃO = saída do FULL confirmada.
                // =================================================

                const aindaNoFull =
                    situacao
                        .ainda_esta_no_full ===
                    true;


                return await salvarERetornar({

                    ativo:
                        aindaNoFull,

                    status:

                        aindaNoFull

                            ? 'full_zero_aguardando_ajuste'

                            : 'full_zero_resolvido',

                    listing_type_esperado:
                        esperadoComEstoqueInterno,

                    mensagem:

                        aindaNoFull

                            ? 'Todas as variações do anúncio ficaram com estoque FULL zerado. Retire o anúncio do FULL.'

                            : 'Saída do FULL confirmada.',

                    full_retirado_confirmado:
                        !aindaNoFull,

                    resumo_automatico: {

                        contexto:
                            'full_zero',

                        exposicao_esperada:
                            esperadoComEstoqueInterno ||
                            '',

                        exposicao_esperada_nome:

                            esperadoComEstoqueInterno

                                ? nomeListingTypeFullNFE(
                                    esperadoComEstoqueInterno
                                )

                                : ''
                    }
                });
            }


            // =================================================
            // SE CHEGOU AQUI:
            //
            // PELO MENOS UMA VARIAÇÃO AINDA TEM FULL.
            //
            // Logo NÃO existe alerta FULL ZERADO.
            // =================================================


            // =================================================
            // EXPOSIÇÃO
            // =================================================

            if (
                situacao
                    .listing_type_esperado &&

                situacao
                    .exposicao_correta ===
                false
            ) {

                return await salvarERetornar({

                    ativo:
                        true,

                    status:
                        'exposicao_pendente',

                    mensagem:
                        'A exposição do anúncio não corresponde ao estoque atual.',

                    resumo_automatico: {

                        contexto:
                            'full_exposicao'
                    }
                });
            }


            return await salvarERetornar({

                ativo:
                    false,

                status:
                    'exposicao_ok',

                mensagem:
                    'Estoque FULL e exposição conferidos.',

                resumo_automatico: {

                    contexto:
                        'full_exposicao'
                }
            });
        }


        // =====================================================
        // VENDA FORA DO FULL
        //
        // Agora verificamos especificamente a(s)
        // variação(ões) que participaram desta venda.
        // =====================================================

        const anuncioZerado =

            resumoVenda
                .algum_anuncio_zerado ===
                true ||

            resumoVenda
                .estoque_anuncio_min ===
                0;


        const depositoZerado =

            resumoVenda
                .algum_local_zerado ===
                true ||

            resumoVenda
                .estoque_local_min ===
                0;


        // =====================================================
        // ANÚNCIO ZERADO
        // =====================================================

        if (
            anuncioZerado
        ) {

            // Se o usuário já confirmou que pode permanecer
            // em zero por não existir estoque vendável,
            // não fazer o mesmo alerta reaparecer no F5.
            const jaAceitoSemEstoque =

                estadoAnterior
                    ?.ativo ===
                    false &&

                estadoAnterior
                    ?.status ===
                    'anuncio_zero_aceito' &&

                estoqueVendavelReal ===
                    false;


            return await salvarERetornar({

                ativo:
                    !jaAceitoSemEstoque,

                status:

                    jaAceitoSemEstoque

                        ? 'anuncio_zero_aceito'

                        : 'anuncio_zero',

                mensagem:

                    estoqueVendavelReal

                        ? 'O anúncio está zerado e existe estoque interno disponível.'

                        : 'O anúncio está zerado.',

                resumo_automatico: {

                    contexto:
                        'estoque_normal'
                }
            });
        }


        // =====================================================
        // DEPÓSITO LOCAL ZERADO
        //
        // Venda ME / fora do FULL.
        //
        // Pode existir estoque FULL no mesmo MLB.
        // Mesmo assim o depósito local zerado deve alertar.
        // =====================================================

        if (
            depositoZerado
        ) {

            const jaAceitoSemEstoque =

                estadoAnterior
                    ?.ativo ===
                    false &&

                estadoAnterior
                    ?.status ===
                    'deposito_zero_aceito_sem_cadastro' &&

                estoqueVendavelReal ===
                    false;


            return await salvarERetornar({

                ativo:
                    !jaAceitoSemEstoque,

                status:

                    jaAceitoSemEstoque

                        ? 'deposito_zero_aceito_sem_cadastro'

                        : 'deposito_zero',

                mensagem:

                    estoqueVendavelReal

                        ? 'O depósito/local do anúncio está zerado e existe estoque interno disponível.'

                        : 'O depósito/local do anúncio está zerado.',

                resumo_automatico: {

                    contexto:
                        'deposito_zero'
                }
            });
        }


        // =====================================================
        // EXPOSIÇÃO
        //
        // 1 = Clássico
        // 2+ = Premium
        // =====================================================

        if (
            situacao
                .listing_type_esperado &&

            situacao
                .exposicao_correta ===
            false
        ) {

            return await salvarERetornar({

                ativo:
                    true,

                status:
                    'exposicao_pendente',

                mensagem:
                    'A exposição do anúncio está incorreta.',

                resumo_automatico: {

                    contexto:
                        'estoque_exposicao'
                }
            });
        }


        // =====================================================
        // TUDO CORRETO
        // =====================================================

        return await salvarERetornar({

            ativo:
                false,

            status:
                'ok',

            mensagem:
                'Estoque do anúncio e exposição conferidos.',

            resumo_automatico: {

                contexto:
                    'estoque_normal'
            }
        });


    } catch (
        error
    ) {

        console.error(
            `❌ Erro processando MLB ${mlb}:`,
            error
        );


        return null;
    }
}


async function confirmarExposicaoFullNFE(
    mlb,
    chaveAlerta = null
) {

    if (
        chaveAlerta
    ) {

        return await confirmarAjusteAnuncioFullNFE(
            chaveAlerta
        );
    }


    return await confirmarAjusteAnuncioFullNFE(
        mlb
    );
}


