// =========================================================
// HTML DETALHES VARIAÇÕES
// =========================================================

function montarVariacoesFullHtmlNFE(
    estado
) {

    const detalhes =
        normalizarArrayJsonNFE(
            estado
                ?.detalhes_variacoes
        );


    if (
        detalhes.length ===
        0
    ) {

        return '';
    }


    return detalhes
        .map(
            detalhe => {

                const sku =
                    detalhe.sku ||
                    'SEM_SKU';


                const estoque =
                    detalhe.estoque_full;


                return `

                    <div
                        style="
                            display:flex;
                            justify-content:space-between;
                            gap:8px;
                            font-size:9px;
                            margin-top:2px;
                        "
                    >
                        <span>
                            ${escaparHTMLNFE(
                                sku
                            )}
                        </span>

                        <strong>
                            ${
                                estoque ===
                                    null ||
                                estoque ===
                                    undefined

                                    ? 'N/I'

                                    : Number(
                                        estoque
                                    )
                            }
                        </strong>
                    </div>
                `;
            }
        )
        .join('');
}


function montarEstoqueLocalFullHtmlNFE(
    estado
) {

    const detalhes =
        normalizarArrayJsonNFE(
            estado
                ?.estoque_local
        );


    if (
        detalhes.length ===
        0
    ) {

        return `
            <div
                style="
                    font-size:9px;
                    color:#6c757d;
                    margin-top:4px;
                "
            >
                Produto não localizado no cadastro.
            </div>
        `;
    }


    const unicos =
        new Map();


    detalhes.forEach(
        item => {

            const chave =
                item.produto_id ||
                item.sku ||
                item.sku_anuncio ||
                Math.random();


            if (
                !unicos.has(
                    chave
                )
            ) {

                unicos.set(
                    chave,
                    item
                );
            }
        }
    );


    const cadastrados =
        Array.from(
            unicos.values()
        )
            .filter(
                item =>
                    item.encontrado ===
                    true
            );


    if (
        cadastrados.length ===
        0
    ) {

        return `
            <div
                style="
                    font-size:9px;
                    color:#721c24;
                    margin-top:4px;
                    font-weight:700;
                "
            >
                Produto não cadastrado no estoque.
            </div>
        `;
    }


    return cadastrados
        .map(
            (
                item,
                index
            ) => {

                const nome =
                    item.nome ||
                    (
                        cadastrados.length >
                        1

                            ? `Produto ${index + 1}`

                            : 'Estoque no cadastro'
                    );


                return `
                    <div
                        style="
                            font-size:9px;
                            margin-top:3px;
                        "
                    >
                        ${escaparHTMLNFE(
                            nome
                        )}

                        :

                        <strong>
                            ${Number(
                                item.estoque_atual ||
                                0
                            )}
                            un.
                        </strong>
                    </div>
                `;
            }
        )
        .join('');
}

function reconciliarEstadosFullComRegrasFixasNFE() {

    const estados =
        window
            ._estadosFullNFE ||
        new Map();


    if (
        estados.size ===
        0
    ) {

        return;
    }


    hidratarRegrasFixasTipoAnuncioLocalNFE();


    let mudou =
        false;


    estados.forEach(
        (
            estado,
            chave
        ) => {

            const contexto =
                estado
                    ?.resumo_automatico
                    ?.contexto ||
                '';


            if (
                ![
                    'full_exposicao',
                    'full_zero'
                ].includes(
                    contexto
                )
            ) {

                return;
            }


            const regraFixa =
                obterRegraFixaTipoAnuncioLocalNFE(
                    estado.mlb
                );


            let quantidadeBase =
                null;


            if (
                contexto ===
                'full_zero'
            ) {

                quantidadeBase =
                    estado
                        ?.resumo_automatico
                        ?.estoque_cadastro_anuncio_total ??
                    null;


            } else {

                quantidadeBase =
                    Number(
                        estado.full_total ||
                        0
                    );
            }


            let esperado =
                regraFixa
                    ?.tipo ||
                null;


            if (
                !esperado &&
                quantidadeBase !==
                    null &&
                Number(
                    quantidadeBase
                ) >
                    0
            ) {

                esperado =
                    obterListingTypeEsperadoFullNFE(
                        quantidadeBase
                    );
            }


            const atual =
                String(
                    estado
                        .listing_type_atual ||
                    ''
                )
                    .trim()
                    .toLowerCase();


            const novo = {

                ...estado,

                listing_type_esperado:
                    esperado,

                resumo_automatico: {

                    ...(
                        estado
                            .resumo_automatico ||
                        {}
                    ),

                    possui_regra_fixa:
                        Boolean(
                            regraFixa
                        ),

                    regra_fixa_nome:
                        regraFixa
                            ?.nome ||
                        null,

                    regra_fixa_tipo:
                        regraFixa
                            ?.tipo ||
                        null
                }
            };


            // =============================================
            // EXPOSIÇÃO COM FULL > 0
            // =============================================

            if (
                contexto ===
                'full_exposicao' &&
                esperado
            ) {

                const correto =
                    atual ===
                    esperado;


                novo.ativo =
                    !correto;


                novo.status =
                    correto
                        ? 'exposicao_ok'
                        : 'exposicao_pendente';
            }


            estados.set(
                chave,
                novo
            );


            mudou =
                true;
        }
    );


    if (
        mudou
    ) {

        persistirEstadosFullLocalNFE();
    }
}

function persistirEstadosFullLocalNFE() {

    try {

        const estados =
            Array.from(
                (
                    window._estadosFullNFE ||
                    new Map()
                )
                    .values()
            );


        localStorage.setItem(
            'nfe_alertas_estoque_v2',
            JSON.stringify(
                estados
            )
        );


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Erro salvando cache de alertas de estoque:',
            error
        );
    }
}

function hidratarEstadosFullLocalNFE() {

    try {

        const bruto =
            localStorage.getItem(
                'nfe_alertas_estoque_v2'
            );


        if (
            !bruto
        ) {

            return window
                ._estadosFullNFE;
        }


        const estados =
            JSON.parse(
                bruto
            );


        if (
            !Array.isArray(
                estados
            )
        ) {

            return window
                ._estadosFullNFE;
        }


        const mapa =
            new Map();


        estados.forEach(
            estado => {

                const chave =
                    String(
                        estado
                            ?.chave_alerta ||
                        ''
                    )
                        .trim();


                if (
                    chave
                ) {

                    mapa.set(
                        chave,
                        estado
                    );
                }
            }
        );


        window._estadosFullNFE =
            mapa;


        return mapa;


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Cache de alertas inválido:',
            error
        );


        return window
            ._estadosFullNFE;
    }
}


// =========================================================
// CARREGAR REGRAS FIXAS LOCALMENTE - SEM ASYNC
// =========================================================

function hidratarRegrasFixasTipoAnuncioLocalNFE() {

    try {

        const bruto =
            localStorage.getItem(
                'regras_fixas_tipo_anuncio_ml'
            );


        if (
            !bruto
        ) {

            return window
                ._regrasFixasTipoAnuncioNFE;
        }


        window._regrasFixasTipoAnuncioNFE =
            normalizarRegrasFixasTipoAnuncioNFE(
                bruto
            );


        console.log(
            '⚡ Regras fixas carregadas instantaneamente:',
            window
                ._regrasFixasTipoAnuncioNFE
        );


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Erro lendo regras fixas locais:',
            error
        );
    }


    return window
        ._regrasFixasTipoAnuncioNFE;
}


// =========================================================
// REGRA FIXA SINCRONA
//
// Usada ANTES de qualquer consulta de rede.
// =========================================================

function obterRegraFixaTipoAnuncioLocalNFE(
    mlb
) {

    mlb =
        normalizarMLBRegraFixaNFE(
            mlb
        );


    if (
        !mlb
    ) {

        return null;
    }


    const regras =
        window
            ._regrasFixasTipoAnuncioNFE ||
        hidratarRegrasFixasTipoAnuncioLocalNFE();


    if (
        regras
            ?.classico
            ?.includes(
                mlb
            )
    ) {

        return {

            encontrado:
                true,

            mlb,

            tipo:
                'gold_special',

            nome:
                'Clássico',

            regra_fixa:
                true
        };
    }


    if (
        regras
            ?.premium
            ?.includes(
                mlb
            )
    ) {

        return {

            encontrado:
                true,

            mlb,

            tipo:
                'gold_pro',

            nome:
                'Premium',

            regra_fixa:
                true
        };
    }


    return null;
}


// =========================================================
// GARANTIR CÉLULA "ESTOQUE ANÚNCIO"
//
// FUNCIONA MESMO NA VERSÃO EM QUE A TD AINDA NÃO
// FOI INSERIDA PELO renderizarVendasNFETabela.
// =========================================================

function garantirCelulaEstoqueAnuncioMonitorFullNFE(
    tr
) {

    let td =
        tr.querySelector(
            'td[data-coluna-nfe="estoque_anuncio"]'
        );


    if (
        td
    ) {

        return td;
    }


    const indice =
        COLUNAS_VENDAS_NFE.findIndex(
            coluna =>
                coluna.id ===
                'estoque_anuncio'
        );


    if (
        indice <
        0
    ) {

        return null;
    }


    let cells =
        Array.from(
            tr.querySelectorAll(
                ':scope > td'
            )
        );


    if (
        cells.length ===
        0
    ) {

        return null;
    }


    // =====================================================
    // A LINHA TEM UMA TD A MENOS:
    // INSERIR ESTOQUE ANÚNCIO
    // =====================================================

    if (
        cells.length ===
        COLUNAS_VENDAS_NFE.length -
            1
    ) {

        td =
            document.createElement(
                'td'
            );


        td.dataset.colunaNfe =
            'estoque_anuncio';


        td.style.verticalAlign =
            'middle';


        td.style.minWidth =
            '115px';


        const referencia =
            cells[
                indice
            ] ||
            null;


        tr.insertBefore(
            td,
            referencia
        );


        return td;
    }


    cells =
        Array.from(
            tr.querySelectorAll(
                ':scope > td'
            )
        );


    td =
        cells[
            indice
        ] ||
        null;


    if (
        td
    ) {

        td.dataset.colunaNfe =
            'estoque_anuncio';
    }


    return td;
}

// =========================================================
// NORMALIZAR MLB
// =========================================================

function normalizarMLBRegraFixaNFE(
    valor
) {

    const texto =
        String(
            valor ||
            ''
        )
            .trim()
            .toUpperCase();


    const match =
        texto.match(
            /MLB\d+/
        );


    return match
        ? match[0]
        : '';
}


// =========================================================
// NORMALIZAR OBJETO DAS REGRAS
// =========================================================

function normalizarRegrasFixasTipoAnuncioNFE(
    valor
) {

    let regras =
        valor;


    if (
        typeof regras ===
        'string'
    ) {

        try {

            regras =
                JSON.parse(
                    regras
                );

        } catch (
            error
        ) {

            regras = {};
        }
    }


    if (
        !regras ||
        typeof regras !==
            'object'
    ) {

        regras = {};
    }


    const classico =
        [
            ...new Set(
                (
                    Array.isArray(
                        regras.classico
                    )
                        ? regras.classico
                        : []
                )
                    .map(
                        normalizarMLBRegraFixaNFE
                    )
                    .filter(Boolean)
            )
        ];


    const premium =
        [
            ...new Set(
                (
                    Array.isArray(
                        regras.premium
                    )
                        ? regras.premium
                        : []
                )
                    .map(
                        normalizarMLBRegraFixaNFE
                    )
                    .filter(Boolean)
            )
        ];


    return {
        classico,
        premium
    };
}


async function carregarRegrasFixasTipoAnuncioNFE(
    forcar = false
) {

    const agora =
        Date.now();


    // =====================================================
    // SEMPRE HIDRATAR LOCAL PRIMEIRO
    // =====================================================

    hidratarRegrasFixasTipoAnuncioLocalNFE();


    // =====================================================
    // CACHE CURTO
    // =====================================================

    if (
        !forcar &&
        window
            ._regrasFixasTipoAnuncioNFELidasEm >
            0 &&
        agora -
            window
                ._regrasFixasTipoAnuncioNFELidasEm <
            60 *
            1000
    ) {

        return window
            ._regrasFixasTipoAnuncioNFE;
    }


    try {

        let regras =
            null;


        // =================================================
        // USAR A FUNÇÃO ORIGINAL DA GESTÃO DE ESTOQUE
        // =================================================

        if (
            typeof window
                .carregarRegrasFixasTipoAnuncioML ===
            'function'
        ) {

            regras =
                await window
                    .carregarRegrasFixasTipoAnuncioML();
        }


        // =================================================
        // FALLBACK DIRETO NO SUPABASE
        // =================================================

        if (
            !regras
        ) {

            const {
                data,
                error
            } =
                await window
                    .supabaseClient
                    .from(
                        'configuracoes_sistema'
                    )
                    .select(
                        'chave, valor'
                    )
                    .eq(
                        'chave',
                        'regras_fixas_tipo_anuncio_ml'
                    )
                    .maybeSingle();


            if (
                error
            ) {

                throw error;
            }


            regras =
                data?.valor ||
                null;
        }


        if (
            regras
        ) {

            window
                ._regrasFixasTipoAnuncioNFE =
                normalizarRegrasFixasTipoAnuncioNFE(
                    regras
                );


            localStorage.setItem(
                'regras_fixas_tipo_anuncio_ml',
                JSON.stringify(
                    window
                        ._regrasFixasTipoAnuncioNFE
                )
            );
        }


        window
            ._regrasFixasTipoAnuncioNFELidasEm =
            agora;


        return window
            ._regrasFixasTipoAnuncioNFE;


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Erro atualizando regras fixas no monitor FULL:',
            error
        );


        return window
            ._regrasFixasTipoAnuncioNFE;
    }
}


async function obterRegraFixaTipoAnuncioNFE(
    mlb,
    forcar = false
) {

    mlb =
        normalizarMLBRegraFixaNFE(
            mlb
        );


    if (
        !mlb
    ) {

        return null;
    }


    // =====================================================
    // PRIMEIRO: LOCAL / INSTANTÂNEO
    // =====================================================

    let regra =
        obterRegraFixaTipoAnuncioLocalNFE(
            mlb
        );


    if (
        regra &&
        !forcar
    ) {

        return regra;
    }


    // =====================================================
    // DEPOIS: FONTE OFICIAL
    // =====================================================

    await carregarRegrasFixasTipoAnuncioNFE(
        forcar
    );


    regra =
        obterRegraFixaTipoAnuncioLocalNFE(
            mlb
        );


    return regra;
}


