    function vendaEstaCanceladaNFE(
    venda
) {

    if (
        !venda
    ) {

        return false;
    }


    // =====================================================
    // PACK
    //
    // Se qualquer order do pack estiver cancelada,
    // bloqueamos emissão/baixa do conjunto.
    // =====================================================

    if (
        Array.isArray(
            venda._membros_pack
        ) &&
        venda._membros_pack.length >
            0
    ) {

        const algumCancelado =
            venda._membros_pack.some(
                membro => {

                    const status =
                        String(
                            membro?._ml_status ||
                            membro?.ml_status ||
                            membro?.status ||
                            ''
                        )
                            .trim()
                            .toLowerCase();


                    return (
                        membro?._venda_cancelada ===
                            true ||
                        membro?.venda_cancelada ===
                            true ||
                        status ===
                            'cancelled' ||
                        status ===
                            'canceled'
                    );
                }
            );


        if (
            algumCancelado
        ) {

            return true;
        }
    }


    const status =
        String(
            venda._ml_status ||
            venda.ml_status ||
            venda.status ||
            ''
        )
            .trim()
            .toLowerCase();


    return (
        venda._venda_cancelada ===
            true ||
        venda.venda_cancelada ===
            true ||
        status ===
            'cancelled' ||
        status ===
            'canceled'
    );
}

function vendaFullPrecisaMudarParaClassicoNFE(
    venda
) {
    const snapshots =
        Array.isArray(
            venda?._estoque_anuncio_pos_venda
        )
            ? venda._estoque_anuncio_pos_venda
            : [];

    return snapshots.some(item => {
        const estoqueDeposito =
            Number(
                item
                    ?.quantidade_deposito_restante ??
                item
                    ?.quantidade_anuncio_restante ??
                item
                    ?.quantidade_restante
            );

        const estoqueFull =
            Number(
                item
                    ?.quantidade_full_restante
            );

        const depositoFicouUm =
            Number.isFinite(
                estoqueDeposito
            ) &&
            estoqueDeposito === 1;

        const fullFicouUm =
            Number.isFinite(
                estoqueFull
            ) &&
            estoqueFull === 1;

        const listingType =
            String(
                item?.listing_type_id ||
                ''
            )
                .trim()
                .toLowerCase();

        const nomeExposicao =
            String(
                item?.listing_type_nome ||
                ''
            )
                .trim()
                .toLowerCase();

        const estaPremium =
            listingType === 'gold_pro' ||
            listingType === 'gold_premium' ||
            nomeExposicao.includes(
                'premium'
            );

        return (
            estaPremium &&
            (
                depositoFicouUm ||
                fullFicouUm
            )
        );
    });
}


