window._clientesAvulsaNFE =
    [];


async function carregarClientesAvulsaNFE() {

    const busca =
        document.getElementById(
            'avulsaClienteBusca'
        );

    const clienteId =
        document.getElementById(
            'avulsaClienteId'
        );

    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );


    if (
        !busca ||
        !clienteId ||
        !resultados
    ) {

        console.warn(
            '⚠️ Campos de pesquisa de cliente da NF-e avulsa não encontrados'
        );

        return false;
    }


    try {

        busca.disabled =
            true;

        busca.placeholder =
            'Carregando clientes...';


        const response =
            await fetch(
                `${window.API_BASE_URL}/nfe/clientes`,
                {
                    method:
                        'GET',

                    headers: {
                        'Accept':
                            'application/json'
                    },

                    cache:
                        'no-store'
                }
            );


        if (
            !response.ok
        ) {

            throw new Error(
                `HTTP ${response.status}`
            );
        }


        const data =
            await response.json();


        if (
            data.success ===
            false
        ) {

            throw new Error(
                data.error ||
                'Erro ao carregar clientes'
            );
        }


        window._clientesAvulsaNFE =
            Array.isArray(
                data.clientes
            )
                ? data.clientes
                : [];


        console.log(
            `👤 ${window._clientesAvulsaNFE.length} cliente(s) disponíveis para NF-e avulsa`
        );


        busca.disabled =
            false;

        busca.placeholder =
            'Digite o nome, CPF ou CNPJ do cliente...';


        // =============================================
        // EVENTO DE PESQUISA
        // =============================================

        busca.oninput =
            function () {

                pesquisarClienteAvulsaNFE(
                    this.value
                );
            };


        busca.onfocus =
            function () {

                if (
                    this.value.trim()
                ) {

                    pesquisarClienteAvulsaNFE(
                        this.value
                    );
                }
            };


        return true;


    } catch (
        error
    ) {

        console.error(
            '❌ Erro carregando clientes para NF-e avulsa:',
            error
        );


        busca.disabled =
            false;

        busca.placeholder =
            'Erro ao carregar clientes';


        return false;
    }
}


function pesquisarClienteAvulsaNFE(
    termo
) {

    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );


    if (!resultados) {

        return;
    }


    const pesquisa =
        String(
            termo ||
            ''
        )
            .trim()
            .toLowerCase();


    if (
        pesquisa.length <
        1
    ) {

        resultados.style.display =
            'none';

        resultados.innerHTML =
            '';

        return;
    }


    const somenteNumeros =
        pesquisa.replace(
            /\D/g,
            ''
        );


    const clientes =
        Array.isArray(
            window._clientesAvulsaNFE
        )
            ? window._clientesAvulsaNFE
            : [];


    const encontrados =
        clientes
            .filter(
                cliente => {

                    const nome =
                        String(
                            cliente.nome ||
                            ''
                        )
                            .toLowerCase();


                    const documento =
                        String(
                            cliente.documento ||
                            ''
                        )
                            .replace(
                                /\D/g,
                                ''
                            );


                    const cidade =
                        String(
                            cliente.cidade ||
                            ''
                        )
                            .toLowerCase();


                    return (

                        nome.includes(
                            pesquisa
                        ) ||

                        cidade.includes(
                            pesquisa
                        ) ||

                        (
                            somenteNumeros &&
                            documento.includes(
                                somenteNumeros
                            )
                        )
                    );
                }
            )
            .slice(
                0,
                15
            );


    if (
        encontrados.length ===
        0
    ) {

        resultados.innerHTML = `

            <div
                style="
                    padding:12px;
                    color:#6c757d;
                    text-align:center;
                "
            >
                Nenhum cliente encontrado.
            </div>
        `;


        resultados.style.display =
            'block';

        return;
    }


    resultados.innerHTML =
        encontrados
            .map(
                cliente => {

                    const documento =
                        escaparHTMLCadastroNFE(
                            cliente.documento ||
                            ''
                        );

                    const cidade =
                        escaparHTMLCadastroNFE(
                            cliente.cidade ||
                            ''
                        );

                    const uf =
                        escaparHTMLCadastroNFE(
                            cliente.uf ||
                            ''
                        );


                    return `

                        <div
                            class="resultado-cliente-avulsa"
                            data-cliente-id="${Number(cliente.id)}"
                            style="
                                padding:10px 12px;
                                cursor:pointer;
                                border-bottom:1px solid #eee;
                            "
                            onmouseover="
                                this.style.background='#f5f7f9'
                            "
                            onmouseout="
                                this.style.background='white'
                            "
                            onclick="
                                selecionarClienteAvulsaNFE(${Number(cliente.id)})
                            "
                        >

                            <div
                                style="
                                    font-weight:600;
                                "
                            >
                                ${escaparHTMLCadastroNFE(
                                    cliente.nome ||
                                    'Cliente'
                                )}
                            </div>


                            <div
                                style="
                                    font-size:12px;
                                    color:#6c757d;
                                    margin-top:2px;
                                "
                            >

                                ${documento || 'Sem documento'}

                                ${
                                    cidade
                                        ? ` • ${cidade}${uf ? `/${uf}` : ''}`
                                        : ''
                                }

                            </div>

                        </div>
                    `;
                }
            )
            .join(
                ''
            );


    resultados.style.display =
        'block';
}


function selecionarClienteAvulsaNFE(
    id
) {

    const clientes =
        Array.isArray(
            window._clientesAvulsaNFE
        )
            ? window._clientesAvulsaNFE
            : [];


    const cliente =
        clientes.find(
            item =>
                String(
                    item.id
                ) ===
                String(
                    id
                )
        );


    if (!cliente) {

        showToast(
            'Cliente não encontrado',
            'warning'
        );

        return;
    }


    const campoId =
        document.getElementById(
            'avulsaClienteId'
        );

    const busca =
        document.getElementById(
            'avulsaClienteBusca'
        );

    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );

    const selecionado =
        document.getElementById(
            'avulsaClienteSelecionado'
        );


    if (
        campoId
    ) {

        campoId.value =
            String(
                cliente.id
            );
    }


    if (
        busca
    ) {

        busca.value =
            cliente.nome ||
            '';
    }


    if (
        resultados
    ) {

        resultados.style.display =
            'none';

        resultados.innerHTML =
            '';
    }


    if (
        selecionado
    ) {

        selecionado.innerHTML = `

            <div
                style="
                    display:flex;
                    justify-content:space-between;
                    gap:10px;
                    align-items:center;
                "
            >

                <div>

                    <strong>
                        <i class="fas fa-check-circle"></i>
                        ${escaparHTMLCadastroNFE(
                            cliente.nome ||
                            ''
                        )}
                    </strong>

                    <div
                        style="
                            color:#6c757d;
                            margin-top:3px;
                        "
                    >

                        ${escaparHTMLCadastroNFE(
                            cliente.documento ||
                            ''
                        )}

                        ${
                            cliente.cidade
                                ? ` • ${escaparHTMLCadastroNFE(
                                    cliente.cidade
                                )}/${escaparHTMLCadastroNFE(
                                    cliente.uf ||
                                    ''
                                )}`
                                : ''
                        }

                    </div>

                </div>


                <button
                    type="button"
                    class="btn btn-sm btn-outline-secondary"
                    onclick="limparClienteSelecionadoAvulsaNFE()"
                >
                    Trocar
                </button>

            </div>
        `;


        selecionado.style.display =
            'block';
    }


    console.log(
        '✅ Cliente selecionado para NF-e avulsa:',
        cliente
    );
}


function limparClienteSelecionadoAvulsaNFE() {

    const campoId =
        document.getElementById(
            'avulsaClienteId'
        );

    const busca =
        document.getElementById(
            'avulsaClienteBusca'
        );

    const resultados =
        document.getElementById(
            'avulsaClienteResultados'
        );

    const selecionado =
        document.getElementById(
            'avulsaClienteSelecionado'
        );


    if (
        campoId
    ) {

        campoId.value =
            '';
    }


    if (
        busca
    ) {

        busca.value =
            '';

        busca.focus();
    }


    if (
        resultados
    ) {

        resultados.innerHTML =
            '';

        resultados.style.display =
            'none';
    }


    if (
        selecionado
    ) {

        selecionado.innerHTML =
            '';

        selecionado.style.display =
            'none';
    }
}


