async function baixarXMLNFE(
    chaveAcesso
) {

    try {

        const chave =
            String(
                chaveAcesso ||
                ''
            )
                .replace(
                    /\D/g,
                    ''
                );


        if (
            chave.length !==
            44
        ) {

            showToast(
                '❌ Chave da NF-e inválida.',
                'error'
            );

            return;
        }


        showToast(
            '🔄 Preparando XML autorizado...',
            'info'
        );


        // =====================================================
        // PEDIR XML PROCESSADO AO BACKEND
        //
        // Se for NF-e antiga, o backend consulta SEFAZ,
        // monta o nfeProc e salva no banco.
        // =====================================================

        const response =
            await fetch(
                `${window.API_BASE_URL}/nfe/buscar-xml?chave=${encodeURIComponent(
                    chave
                )}`,
                {
                    cache:
                        'no-store'
                }
            );


        let data =
            {};


        try {

            data =
                await response.json();

        } catch (
            error
        ) {

            throw new Error(
                `Servidor retornou resposta inválida. HTTP ${response.status}`
            );
        }


        if (
            !response.ok
        ) {

            throw new Error(
                data.error ||
                `Erro HTTP ${response.status}`
            );
        }


        if (
            !data.xml
        ) {

            throw new Error(
                'XML não encontrado.'
            );
        }


        let xml =
            String(
                data.xml
            )
                .trim();


        // =====================================================
        // GARANTIR DECLARAÇÃO
        // =====================================================

        if (
            !xml.startsWith(
                '<?xml'
            )
        ) {

            xml =
                '<?xml version="1.0" encoding="UTF-8"?>' +
                xml;
        }


        // =====================================================
        // VALIDAÇÃO ANTES DO DOWNLOAD
        // =====================================================

        const possuiNfeProc =
            /<nfeProc\b/i.test(
                xml
            );


        const possuiNFe =
            /<(?:\w+:)?NFe\b/i.test(
                xml
            );


        const possuiAssinatura =
            /<(?:\w+:)?Signature\b/i.test(
                xml
            );


        const possuiProtNFe =
            /<(?:\w+:)?protNFe\b/i.test(
                xml
            );


        const possuiNProt =
            /<(?:\w+:)?nProt>/i.test(
                xml
            );


        console.log(
            '🧾 XML para download:',
            {
                chave,

                nfeProc:
                    possuiNfeProc,

                NFe:
                    possuiNFe,

                assinatura:
                    possuiAssinatura,

                protNFe:
                    possuiProtNFe,

                nProt:
                    possuiNProt,

                recuperadoSEFAZ:
                    data.recuperado_sefaz ===
                    true
            }
        );


        // =====================================================
        // NÃO DEIXAR BAIXAR XML INCOMPLETO
        //
        // É justamente o problema que estava acontecendo.
        // =====================================================

        if (
            !possuiNfeProc ||
            !possuiNFe ||
            !possuiAssinatura ||
            !possuiProtNFe ||
            !possuiNProt
        ) {

            console.error(
                '❌ XML incompleto:',
                xml.substring(
                    0,
                    1000
                )
            );


            throw new Error(
                'O XML ainda não está completo/autorizado. O download foi bloqueado para evitar enviar um arquivo inválido ao Mercado Livre.'
            );
        }


        // =====================================================
        // COMPACTAR SOMENTE ESPAÇOS ENTRE TAGS
        //
        // NÃO altera o conteúdo assinado.
        // =====================================================

        xml =
            xml.replace(
                />\s+</g,
                '><'
            );


        // =====================================================
        // DOWNLOAD
        // =====================================================

        const blob =
            new Blob(
                [
                    xml
                ],
                {
                    type:
                        'application/xml;charset=utf-8'
                }
            );


        const url =
            URL.createObjectURL(
                blob
            );


        const a =
            document.createElement(
                'a'
            );


        a.href =
            url;


        // Nome padrão comum de NF-e processada
        a.download =
            `${chave}-procNFe.xml`;


        document.body
            .appendChild(
                a
            );


        a.click();


        document.body
            .removeChild(
                a
            );


        setTimeout(
            () =>
                URL.revokeObjectURL(
                    url
                ),
            5000
        );


        showToast(
            data.recuperado_sefaz ===
                true

                ? '✅ XML autorizado recuperado da SEFAZ e baixado.'

                : '✅ XML autorizado baixado.',
            'success'
        );


    } catch (
        error
    ) {

        console.error(
            '❌ Erro ao baixar XML autorizado:',
            error
        );


        showToast(
            `❌ Não foi possível preparar o XML: ${error.message}`,
            'error'
        );
    }
}

// =========================================================
// DATA/HORA CORRETA PARA NF-e / EVENTOS SEFAZ
// Timezone oficial usado pelo sistema: America/Sao_Paulo
// Exemplo:
// 2026-08-13T10:20:35-03:00
// =========================================================

function obterDataHoraNFeBrasil(data = new Date()) {
    const timeZone = 'America/Sao_Paulo';

    const formatter = new Intl.DateTimeFormat(
        'en-CA',
        {
            timeZone,
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hourCycle: 'h23',
            timeZoneName: 'longOffset'
        }
    );

    const partes = formatter.formatToParts(data);

    const valores = {};

    for (const parte of partes) {
        valores[parte.type] = parte.value;
    }

    let offset = '-03:00';

    if (valores.timeZoneName) {
        const match = valores.timeZoneName.match(
            /GMT([+-]\d{2}):?(\d{2})/
        );

        if (match) {
            offset = `${match[1]}:${match[2]}`;
        }
    }

    const resultado =
        `${valores.year}-` +
        `${valores.month}-` +
        `${valores.day}T` +
        `${valores.hour}:` +
        `${valores.minute}:` +
        `${valores.second}` +
        `${offset}`;

    return resultado;
}

async function cancelarNFE(chaveAcesso) {
    const justificativa = prompt('Informe a justificativa para cancelamento:');
    if (!justificativa) return;
    try {
        const response = await fetch(`${window.API_BASE_URL}/nfe/cancelar`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chaveAcesso, justificativa })
        });
        const result = await response.json();
        if (result.success) {
            window.showToast('NF-e cancelada com sucesso', 'success');
            await carregarNFesEmitidas();
        } else {
            window.showToast('Erro ao cancelar: ' + result.error, 'error');
        }
    } catch (error) {
        window.showToast('Erro de comunicação', 'error');
    }
}

// ===================== TRANSPORTADORAS =====================
async function carregarTransportadoras() {
    const tbody = document.getElementById('transportadorasBody');
    if (!tbody) return;
    tbody.innerHTML = '<tr><td colspan="4" class="text-center"><div class="spinner"></div> Carregando...</td></tr>';
    try {
        const response = await fetch(`${window.API_BASE_URL}/nfe/transportadoras`);
        const data = await response.json();
        if (!data.success) throw new Error(data.error);
        const transportadoras = data.transportadoras || [];
        if (!transportadoras.length) {
            tbody.innerHTML = '<td><td colspan="4" class="text-center">Nenhuma transportadora cadastrada</td></tr>';
            return;
        }
        tbody.innerHTML = transportadoras.map(t => `
            <tr>
                <td>${t.nome}</td>
                <td>${t.cnpj}</td>
                <td>${t.ie || '-'}</td>
                <td><button class="btn btn-sm btn-danger" onclick="excluirTransportadora(${t.id})">Excluir</button></td>
            </tr>`).join('');
        const select = document.getElementById('avulsaTransportadoraId');
        if (select) select.innerHTML = '<option value="">Selecione</option>' + transportadoras.map(t => `<option value="${t.id}">${t.nome}</option>`).join('');
    } catch (error) {
        tbody.innerHTML = '<tr><td colspan="4" class="text-center text-danger">Erro ao carregar</td></tr>';
    }
}

async function excluirTransportadora(id) {
    if (!confirm('Excluir esta transportadora?')) return;
    try {
        const response = await fetch(`${window.API_BASE_URL}/nfe/transportadoras/${id}`, { method: 'DELETE' });
        if (response.ok) {
            window.showToast('Transportadora excluída', 'success');
            await carregarTransportadoras();
        } else {
            window.showToast('Erro ao excluir', 'error');
        }
    } catch (error) {
        window.showToast('Erro de comunicação', 'error');
    }
}

