function fecharModalTransportadora() {
    const modal = document.getElementById('modalNovaTransportadora');
    if (modal) modal.classList.add('hidden');
}

async function salvarNovaTransportadora() {
    const nome = document.getElementById('novaTransportadoraNome').value.trim();
    const cnpj = document.getElementById('novaTransportadoraCnpj').value.trim().replace(/\D/g, '');
    const ie = document.getElementById('novaTransportadoraIe').value.trim();
    const endereco = document.getElementById('novaTransportadoraEndereco').value.trim();
    const cidade = document.getElementById('novaTransportadoraCidade').value.trim();
    const uf = document.getElementById('novaTransportadoraUf').value.trim().toUpperCase();

    if (!nome || !cnpj) {
        showToast('Nome e CNPJ são obrigatórios', 'warning');
        return;
    }
    if (cnpj.length !== 14) {
        showToast('CNPJ deve ter 14 dígitos', 'warning');
        return;
    }

    const payload = { nome, cnpj, ie, endereco, cidade, uf };

    try {
        const response = await fetch(`${window.API_BASE_URL}/nfe/transportadoras`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const result = await response.json();
        if (result.success) {
            showToast('Transportadora cadastrada com sucesso!', 'success');
            fecharModalTransportadora();
            await carregarTransportadoras();
            await carregarTransportadorasSelect();
        } else {
            showToast('Erro: ' + result.error, 'error');
        }
    } catch (error) {
        console.error(error);
        showToast('Erro ao salvar transportadora', 'error');
    }
}

// =========================================================
// NORMALIZAÇÃO DE ID
// =========================================================

function normalizarOrderIdML(valor) {

    if (
        valor === null ||
        valor === undefined
    ) {
        return '';
    }

    return String(valor)
        .trim()
        .replace(/^ML(?=\d)/i, '');
}

function variantesOrderIdML(valor) {

    const id =
        normalizarOrderIdML(valor);

    if (!id) {
        return [];
    }

    return [
        id,
        `ML${id}`
    ];
}

// =========================================================
// PARSE DAS INFORMAÇÕES DE ENVIO
// =========================================================

function parseInformacoesEnvioNFE(venda) {

    let info =
        venda?.informacoes_envio ||
        {};

    if (
        typeof info ===
        'string'
    ) {

        try {

            info =
                JSON.parse(info);

        } catch (error) {

            info = {};
        }
    }

    if (
        !info ||
        typeof info !==
            'object'
    ) {

        return {};
    }

    return info;
}

// =========================================================
// DATA DA VENDA
// =========================================================

function obterDataVendaNFE(venda) {

    const valor =
        venda?.data_venda ||
        venda?.date_created ||
        venda?.created_at ||
        null;

    if (!valor) {
        return null;
    }

    const match =
        String(valor).match(
            /(\d{4}-\d{2}-\d{2})/
        );

    return match
        ? match[1]
        : null;
}

// =========================================================
// DATA E HORA EM QUE A VENDA FOI REALIZADA
// =========================================================

function formatarDataHoraVendaNFE(venda) {

    const valor =
        venda?.date_created ||
        venda?.data_venda ||
        venda?.created_at ||
        null;


    if (!valor) {

        return {
            data: '-',
            hora: ''
        };
    }


    try {

        const texto =
            String(valor).trim();


        // =====================================================
        // SE VIER APENAS YYYY-MM-DD
        // =====================================================

        const somenteData =
            texto.match(
                /^(\d{4})-(\d{2})-(\d{2})$/
            );


        if (somenteData) {

            return {

                data:
                    `${somenteData[3]}/${somenteData[2]}/${somenteData[1]}`,

                hora:
                    ''
            };
        }


        // =====================================================
        // DATA/HORA COMPLETA DO MERCADO LIVRE
        // =====================================================

        const data =
            new Date(
                texto
            );


        if (
            Number.isNaN(
                data.getTime()
            )
        ) {

            return {
                data: '-',
                hora: ''
            };
        }


        return {

            data:
                data.toLocaleDateString(
                    'pt-BR',
                    {
                        timeZone:
                            'America/Sao_Paulo'
                    }
                ),

            hora:
                data.toLocaleTimeString(
                    'pt-BR',
                    {
                        hour:
                            '2-digit',

                        minute:
                            '2-digit',

                        timeZone:
                            'America/Sao_Paulo'
                    }
                )
        };


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Erro formatando data da venda:',
            valor,
            error
        );


        return {
            data: '-',
            hora: ''
        };
    }
}

async function carregarTransportadorasSelect() {

    console.log(
        '🚚 Carregando transportadoras no MODAL NOVO...'
    );

    // =====================================================
    // BUSCAR ESPECIFICAMENTE NO MODAL NOVO
    // =====================================================

    const modal =
        document.getElementById(
            'modalEdicaoProdutos'
        );

    if (!modal) {

        console.error(
            '❌ Modal de emissão não encontrado'
        );

        return false;
    }

    const select =
        modal.querySelector(
            '#nfeTransportadora'
        );

    if (!select) {

        console.error(
            '❌ Select de transportadora não encontrado dentro do modal'
        );

        return false;
    }

    try {

        select.disabled = true;

        select.innerHTML = `
            <option value="">
                ⏳ Carregando transportadoras...
            </option>
        `;

        const url =
            `${window.API_BASE_URL}/nfe/transportadoras`;

        console.log(
            '🚚 URL:',
            url
        );

        const response =
            await fetch(
                url,
                {
                    method: 'GET',

                    headers: {
                        'Accept':
                            'application/json'
                    },

                    cache:
                        'no-store'
                }
            );

        console.log(
            '🚚 HTTP:',
            response.status
        );

        if (!response.ok) {

            throw new Error(
                `HTTP ${response.status}`
            );
        }

        const data =
            await response.json();

        console.log(
            '🚚 Dados recebidos:',
            data
        );

        if (!data.success) {

            throw new Error(
                data.error ||
                'API retornou success=false'
            );
        }

        const transportadoras =
            Array.isArray(
                data.transportadoras
            )
                ? data.transportadoras
                : [];

        console.log(
            `🚚 ${transportadoras.length} transportadoras encontradas`
        );

        if (
            transportadoras.length === 0
        ) {

            select.innerHTML = `
                <option value="">
                    Nenhuma transportadora cadastrada
                </option>
            `;

            select.disabled = false;

            return true;
        }

        // =====================================================
        // PRIMEIRA OPÇÃO
        // =====================================================

        select.innerHTML = '';

        const optionInicial =
            document.createElement(
                'option'
            );

        optionInicial.value = '';

        optionInicial.textContent =
            'Selecione uma transportadora';

        select.appendChild(
            optionInicial
        );

        // =====================================================
        // TRANSPORTADORAS
        // =====================================================

        transportadoras.forEach(
            transportadora => {

                const option =
                    document.createElement(
                        'option'
                    );

                option.value =
                    String(
                        transportadora.id
                    );

                let texto =
                    transportadora.nome ||
                    'Transportadora';

                if (
                    transportadora.cnpj
                ) {

                    texto +=
                        ` - ${transportadora.cnpj}`;
                }

                option.textContent =
                    texto;

                select.appendChild(
                    option
                );
            }
        );

        select.disabled = false;

        console.log(
            '✅ Select preenchido:',
            select.options.length,
            'opções'
        );

        return true;

    } catch (error) {

        console.error(
            '❌ Erro ao carregar transportadoras:',
            error
        );

        select.innerHTML = `
            <option value="">
                ❌ Erro ao carregar transportadoras
            </option>
        `;

        select.disabled = false;

        return false;
    }
}

async function carregarClientes() {

    const tbody =
        document.getElementById(
            'clientesBody'
        );


    if (!tbody) {
        return;
    }


    tbody.innerHTML = `
        <tr>
            <td colspan="4" class="text-center">
                <div class="spinner"></div>
                Carregando...
            </td>
        </tr>
    `;


    try {

        const response =
            await fetch(
                `${window.API_BASE_URL}/nfe/clientes`,
                {
                    cache:
                        'no-store'
                }
            );


        const data =
            await response.json();


        if (
            !response.ok ||
            !data.success
        ) {

            throw new Error(
                data.error ||
                'Erro ao carregar clientes'
            );
        }


        const clientes =
            Array.isArray(
                data.clientes
            )
                ? data.clientes
                : [];


        if (
            clientes.length === 0
        ) {

            tbody.innerHTML = `
                <tr>
                    <td
                        colspan="4"
                        class="text-center"
                    >
                        Nenhum cliente cadastrado
                    </td>
                </tr>
            `;

            return;
        }


        tbody.innerHTML =
            clientes
                .map(
                    cliente => `

                        <tr>

                            <td>
                                ${escaparHTMLCadastroNFE(
                                    cliente.nome ||
                                    ''
                                )}
                            </td>


                            <td>
                                ${escaparHTMLCadastroNFE(
                                    cliente.documento ||
                                    '-'
                                )}
                            </td>


                            <td>

                                ${escaparHTMLCadastroNFE(
                                    cliente.logradouro ||
                                    ''
                                )}

                                ${
                                    cliente.numero
                                        ? `, ${escaparHTMLCadastroNFE(
                                            cliente.numero
                                        )}`
                                        : ''
                                }

                                ${
                                    cliente.cidade
                                        ? ` - ${escaparHTMLCadastroNFE(
                                            cliente.cidade
                                        )}`
                                        : ''
                                }

                            </td>


                            <td
                                style="
                                    white-space:nowrap;
                                "
                            >

                                <button
                                    type="button"
                                    class="btn btn-sm btn-info"
                                    onclick="visualizarCliente(${Number(
                                        cliente.id
                                    )})"
                                    title="Visualizar cliente"
                                >
                                    <i class="fas fa-eye"></i>
                                </button>


                                <button
                                    type="button"
                                    class="btn btn-sm btn-warning"
                                    onclick="editarClienteNFE(${Number(
                                        cliente.id
                                    )})"
                                    title="Editar cliente"
                                >
                                    <i class="fas fa-edit"></i>
                                </button>


                                <button
                                    type="button"
                                    class="btn btn-sm btn-danger"
                                    onclick="excluirCliente(${Number(
                                        cliente.id
                                    )})"
                                    title="Excluir cliente"
                                >
                                    <i class="fas fa-trash"></i>
                                </button>

                            </td>

                        </tr>
                    `
                )
                .join(
                    ''
                );


        // =====================================================
        // ATUALIZAR SELECT ANTIGO, CASO EXISTA
        // =====================================================

        const select =
            document.getElementById(
                'avulsaClienteId'
            );


        if (
            select &&
            select.tagName === 'SELECT'
        ) {

            select.innerHTML =
                '<option value="">Selecione</option>' +

                clientes
                    .map(
                        cliente =>
                            `<option value="${cliente.id}">${escaparHTMLCadastroNFE(
                                cliente.nome
                            )} (${escaparHTMLCadastroNFE(
                                cliente.documento ||
                                ''
                            )})</option>`
                    )
                    .join(
                        ''
                    );
        }


    } catch (error) {

        console.error(
            '❌ Erro carregando clientes:',
            error
        );


        tbody.innerHTML = `
            <tr>
                <td
                    colspan="4"
                    class="text-center text-danger"
                >
                    Erro ao carregar clientes
                </td>
            </tr>
        `;
    }
}

async function excluirCliente(id) {
    if (!confirm('Excluir este cliente?')) return;
    try {
        const response = await fetch(`${window.API_BASE_URL}/nfe/clientes/${id}`, { method: 'DELETE' });
        if (response.ok) {
            window.showToast('Cliente excluído', 'success');
            await carregarClientes();
        } else {
            window.showToast('Erro ao excluir', 'error');
        }
    } catch (error) {
        window.showToast('Erro de comunicação', 'error');
    }
}

window.visualizarCliente = async function(id) {
    try {
        const response = await fetch(`${API_BASE_URL}/nfe/clientes/${id}`);
        const data = await response.json();
        if (!data.success) throw new Error(data.error);
        const cliente = data.cliente;

        const modalContent = `
            <div style="padding: 10px;">
                <h4>${cliente.nome}</h4>
                <p><strong>Documento:</strong> ${cliente.documento || '-'}</p>
                <p><strong>Endereço:</strong> ${cliente.logradouro || ''}, ${cliente.numero || 'S/N'} - ${cliente.bairro || ''}</p>
                <p><strong>Cidade/UF:</strong> ${cliente.cidade || ''} / ${cliente.uf || ''}</p>
                <p><strong>CEP:</strong> ${cliente.cep || ''}</p>
            </div>
        `;

        showModalDialog('Detalhes do Cliente', modalContent);
    } catch (error) {
        console.error('Erro ao buscar cliente:', error);
        showToast('Erro ao carregar dados do cliente', 'error');
    }
};

window.editarClienteNFE = async function editarClienteNFE(id) {
    try {
        id = Number(id);
        if (!id) {
            throw new Error('ID do cliente inválido');
        }

        console.log(`✏️ Abrindo edição do cliente ${id}`);

        // =====================================================
        // BUSCAR CLIENTE COMPLETO
        // =====================================================

        const response =
            await fetch(
                `${window.API_BASE_URL}/nfe/clientes/${id}`,
                {
                    method:
                        'GET',

                    headers: {
                        'Accept':
                            'application/json'
                    },

                    cache:
                        'no-store'
                }
            );


        const data =
            await response.json();


        if (
            !response.ok ||
            !data.success ||
            !data.cliente
        ) {

            throw new Error(
                data.error ||
                'Cliente não encontrado'
            );
        }


        const cliente =
            data.cliente;


        // =====================================================
        // ABRIR O MESMO MODAL DO CADASTRO
        // =====================================================

        abrirModalCadastroClienteNFE();


        const modal =
            document.getElementById(
                'modalCadastroClienteNFE'
            );


        if (!modal) {

            throw new Error(
                'Modal de cliente não encontrado'
            );
        }


        // =====================================================
        // INFORMAR QUE ESTAMOS EDITANDO
        // =====================================================

        modal.dataset.clienteId =
            String(
                id
            );


        // =====================================================
        // TÍTULO
        // =====================================================

        const titulo =
            modal.querySelector(
                'h3'
            );


        if (titulo) {

            titulo.innerHTML = `
                <i class="fas fa-user-edit"></i>
                Editar Cliente
            `;
        }


        // =====================================================
        // PREENCHER CAMPOS
        // =====================================================

        const preencher =
            (
                seletor,
                valor
            ) => {

                const campo =
                    modal.querySelector(
                        seletor
                    );


                if (campo) {

                    campo.value =
                        valor ??
                        '';
                }
            };


        preencher(
            '#cadClienteNome',
            cliente.nome
        );


        preencher(
            '#cadClienteDocumento',
            String(
                cliente.documento ||
                ''
            )
                .replace(
                    /\D/g,
                    ''
                )
        );


        preencher(
            '#cadClienteLogradouro',
            cliente.logradouro
        );


        preencher(
            '#cadClienteNumero',
            cliente.numero ||
            'S/N'
        );


        preencher(
            '#cadClienteBairro',
            cliente.bairro
        );


        preencher(
            '#cadClienteCidade',
            cliente.cidade
        );


        preencher(
            '#cadClienteUF',
            String(
                cliente.uf ||
                ''
            )
                .toUpperCase()
        );


        preencher(
            '#cadClienteCEP',
            String(
                cliente.cep ||
                ''
            )
                .replace(
                    /\D/g,
                    ''
                )
        );


        // =====================================================
        // BOTÃO
        // =====================================================

        const botao =
            modal.querySelector(
                '#btnSalvarCadastroClienteNFE'
            );


        if (botao) {

            botao.innerHTML = `
                <i class="fas fa-save"></i>
                Salvar Alterações
            `;
        }


        // =====================================================
        // FOCO
        // =====================================================

        setTimeout(
            () =>
                modal
                    .querySelector(
                        '#cadClienteNome'
                    )
                    ?.focus(),
            100
        );


    } catch (error) {

        console.error(
            '❌ Erro abrindo edição do cliente:',
            error
        );


        showToast(
            `Erro ao editar cliente: ${error.message}`,
            'error'
        );
    }
};

async function emitirNFEAvulsa(
    event = null
) {

    const clienteId =
        document
            .getElementById(
                'avulsaClienteId'
            )
            ?.value;


    const cfop =
        document
            .getElementById(
                'avulsaCfop'
            )
            ?.value;


    const naturezaOperacao =
        document
            .getElementById(
                'avulsaNatOp'
            )
            ?.value;

            const entradaDevolucao =
    (
        normalizarNaturezaAvulsaNFE(
            naturezaOperacao
        ) ===
        'entrada de devolucao'
    );


const chaveNFeReferenciada =
    String(
        document
            .getElementById(
                'avulsaChaveNFeReferenciada'
            )
            ?.value ||
        ''
    )
        .replace(
            /\D/g,
            ''
        );


    const transportadoraId =
        document
            .getElementById(
                'avulsaTransportadoraId'
            )
            ?.value ||
        null;


    const modalidadeFrete =
        document
            .getElementById(
                'avulsaModFrete'
            )
            ?.value ||
        '9';


    // =====================================================
    // VALIDAÇÕES
    // =====================================================

    if (!clienteId) {

        showToast(
            'Selecione um cliente',
            'warning'
        );

        document
            .getElementById(
                'avulsaClienteBusca'
            )
            ?.focus();

        return;
    }


    if (!cfop) {

        showToast(
            'Selecione o CFOP',
            'warning'
        );

        return;
    }


    if (
        !naturezaOperacao
    ) {

        showToast(
            'Selecione a Natureza da Operação',
            'warning'
        );

        return;
    }

    // =====================================================
// DEVOLUÇÃO PRECISA REFERENCIAR A NF-E ORIGINAL
// =====================================================

if (
    entradaDevolucao &&
    chaveNFeReferenciada.length !==
        44
) {

    showToast(
        'Informe os 44 dígitos da chave de acesso da NF-e de saída que está sendo devolvida.',
        'warning'
    );


    document
        .getElementById(
            'avulsaChaveNFeReferenciada'
        )
        ?.focus();


    return;
}

    if (
    !Array.isArray(
        window._itensAvulsaNFE
    ) ||
    window._itensAvulsaNFE.length === 0
) {

    showToast(
        'Adicione pelo menos um produto à NF-e',
        'warning'
    );

    document
        .getElementById(
            'avulsaProdutoBusca'
        )
        ?.focus();

    return;
}


atualizarProdutosJSONAvulsaNFE();


    // =====================================================
    // PRODUTOS
    // =====================================================

    let produtos;


    try {

        produtos =
            JSON.parse(
                document
                    .getElementById(
                        'avulsaProdutos'
                    )
                    ?.value ||
                '[]'
            );


        if (
            !Array.isArray(
                produtos
            ) ||
            produtos.length ===
                0
        ) {

            throw new Error(
                'Produtos inválidos'
            );
        }


    } catch (
        error
    ) {

        showToast(
            'Produtos inválidos. Use um array JSON válido.',
            'error'
        );

        return;
    }


    // =====================================================
    // PAYLOAD
    // =====================================================

const dados = {

    cliente: {

        id:
            clienteId
    },

    produtos,

    cfop,

    natureza_operacao:
        naturezaOperacao,

    modalidade_frete:
        modalidadeFrete,

    transportadora_id:
        transportadoraId,


    // =================================================
    // DEVOLUÇÃO
    // =================================================

    finalidade_nfe:
        entradaDevolucao
            ? '4'
            : '1',

    chave_nfe_referenciada:
        entradaDevolucao
            ? chaveNFeReferenciada
            : null
};


    console.log(
        '📤 NF-e avulsa:',
        dados
    );


    // =====================================================
    // BOTÃO
    // =====================================================

    const btn =
        event?.currentTarget ||
        event?.target ||
        document.querySelector(
            '[onclick*="emitirNFEAvulsa"]'
        );


    const original =
        btn?.innerHTML ||
        '';


    if (
        btn
    ) {

        btn.disabled =
            true;

        btn.innerHTML =
            '<span class="spinner"></span> Emitindo...';
    }


    try {

        const response =
            await fetch(
                `${window.API_BASE_URL}/nfe/emitir-avulsa`,
                {
                    method:
                        'POST',

                    headers: {
                        'Content-Type':
                            'application/json'
                    },

                    body:
                        JSON.stringify(
                            dados
                        )
                }
            );


// =====================================================
// LER RESPOSTA COMPLETA DO BACKEND
// =====================================================

const respostaTexto =
    await response.text();


let result =
    {};


if (
    respostaTexto
) {

    try {

        result =
            JSON.parse(
                respostaTexto
            );

    } catch {

        result = {
            raw:
                respostaTexto
        };
    }
}


console.log(
    '📥 Resposta /nfe/emitir-avulsa:',
    {
        status:
            response.status,

        ok:
            response.ok,

        result,

        respostaTexto
    }
);


if (
    !response.ok ||
    result.success ===
        false
) {

    let detalheErro =
        result.error ||
        result.message ||
        result.details ||
        result.detail ||
        result.raw ||
        respostaTexto ||
        `Erro HTTP ${response.status}`;


    if (
        typeof detalheErro ===
        'object'
    ) {

        try {

            detalheErro =
                JSON.stringify(
                    detalheErro
                );

        } catch {

            detalheErro =
                String(
                    detalheErro
                );
        }
    }


    throw new Error(
        `HTTP ${response.status}: ${detalheErro}`
    );
}


        showToast(
            '✅ NF-e avulsa emitida com sucesso!',
            'success'
        );


        await limparFormAvulsa();


        try {

            await carregarNFesEmitidas();

        } catch {}


    } catch (
        error
    ) {

        console.error(
            '❌ Erro na NF-e avulsa:',
            error
        );


        showToast(
            `Erro ao emitir NF-e: ${error.message}`,
            'error'
        );


    } finally {

        if (
            btn
        ) {

            btn.disabled =
                false;

            btn.innerHTML =
                original;
        }
    }
}

async function limparFormAvulsa() {

    // =====================================================
    // CLIENTE
    // =====================================================

    limparClienteSelecionadoAvulsaNFE();


    // =====================================================
    // PRODUTOS
    // =====================================================

    window._itensAvulsaNFE =
        [];


    renderizarProdutosAvulsaNFE();


    const buscaProduto =
        document.getElementById(
            'avulsaProdutoBusca'
        );


    if (
        buscaProduto
    ) {

        buscaProduto.value =
            '';
    }


    const resultadosProduto =
        document.getElementById(
            'avulsaProdutoResultados'
        );


    if (
        resultadosProduto
    ) {

        resultadosProduto.innerHTML =
            '';

        resultadosProduto.style.display =
            'none';
    }


    // =====================================================
    // TRANSPORTADORA
    // =====================================================

    const transportadora =
        document.getElementById(
            'avulsaTransportadoraId'
        );


    if (
        transportadora
    ) {

        transportadora.value =
            '';
    }


    // =====================================================
    // FRETE
    // =====================================================

    const modalidade =
        document.getElementById(
            'avulsaModFrete'
        );


    if (
        modalidade
    ) {

        modalidade.value =
            '9';
    }


    // =====================================================
    // RESTAURAR PADRÕES
    // =====================================================

    try {

        await Promise.all([

            preencherSelectCFOPAvulsaNFE(),

            preencherSelectNaturezaAvulsaNFE(),

            preencherSelectTransportadoraAvulsaNFE(),

            carregarProdutosAvulsaNFE()
        ]);


    } catch (
        error
    ) {

        console.warn(
            '⚠️ Erro restaurando formulário avulso:',
            error
        );
    }
}

