function garantirEstruturaCadastrosNFE() {

    let aba =
        document.getElementById(
            'abaCadastros'
        );


    // =====================================================
    // CRIAR ABA CASO NÃO EXISTA
    // =====================================================

    if (!aba) {

        const referencia =
            document.getElementById(
                'abaClientes'
            ) ||
            document.getElementById(
                'abaTransportadoras'
            ) ||
            document.getElementById(
                'abaAvulsa'
            ) ||
            document.getElementById(
                'abaVendas'
            );


        if (!referencia) {

            console.error(
                '❌ Não foi possível localizar a área NF-e para criar Cadastros'
            );

            return null;
        }


        aba =
            document.createElement(
                'div'
            );

        aba.id =
            'abaCadastros';

        aba.className =
            'hidden';


        const pai =
            referencia.parentElement;


        pai.appendChild(
            aba
        );
    }


    // =====================================================
    // GARANTIR ESTRUTURA INTERNA
    //
    // IMPORTANTE:
    // não basta #abaCadastros existir.
    // =====================================================

    if (
        !aba.querySelector(
            '#cadastrosNFEConteudo'
        ) ||
        !aba.querySelector(
            '#cadNFEBtnTransportadoras'
        )
    ) {

        aba.innerHTML = `

            <div class="card">

                <div
                    style="
                        display:flex;
                        justify-content:space-between;
                        align-items:center;
                        margin-bottom:20px;
                    "
                >

                    <div>

                        <h3 style="margin:0;">
                            <i class="fas fa-cogs"></i>
                            Cadastros NF-e
                        </h3>

                        <small style="color:#6c757d;">
                            Cadastre aqui os dados utilizados
                            nas emissões de NF-e.
                        </small>

                    </div>

                </div>


                <div
                    style="
                        display:grid;
                        grid-template-columns:repeat(auto-fit,minmax(190px,1fr));
                        gap:10px;
                        margin-bottom:22px;
                    "
                >

                    <button
                        type="button"
                        class="btn btn-outline-primary"
                        id="cadNFEBtnTransportadoras"
                        data-tipo="transportadoras"
                    >
                        <i class="fas fa-truck"></i>
                        Transportadoras
                    </button>


                    <button
                        type="button"
                        class="btn btn-outline-primary"
                        id="cadNFEBtnClientes"
                        data-tipo="clientes"
                    >
                        <i class="fas fa-user"></i>
                        Clientes
                    </button>


                    <button
                        type="button"
                        class="btn btn-outline-primary"
                        id="cadNFEBtnNaturezas"
                        data-tipo="naturezas"
                    >
                        <i class="fas fa-file-alt"></i>
                        Natureza da Operação
                    </button>


                    <button
                        type="button"
                        class="btn btn-outline-primary"
                        id="cadNFEBtnCFOPs"
                        data-tipo="cfops"
                    >
                        <i class="fas fa-list-ol"></i>
                        CFOP
                    </button>

                </div>


                <div
                    id="cadastrosNFEConteudo"
                ></div>

            </div>
        `;
    }


    // =====================================================
    // EVENTOS
    //
    // NÃO DEPENDER DE onclick NO HTML.
    // =====================================================

    const botoes =
        aba.querySelectorAll(
            '[data-tipo]'
        );


    botoes.forEach(
        botao => {

            botao.onclick =
                async event => {

                    event.preventDefault();

                    const tipo =
                        botao.dataset.tipo;


                    await mostrarCadastroNFE(
                        tipo
                    );
                };
        }
    );


    return aba;
}

// =========================================================
// HELPERS - CADASTROS NF-e
// =========================================================

function escaparHTMLCadastroNFE(
    valor
) {

    return String(
        valor ??
        ''
    )
        .replace(
            /&/g,
            '&amp;'
        )
        .replace(
            /</g,
            '&lt;'
        )
        .replace(
            />/g,
            '&gt;'
        )
        .replace(
            /"/g,
            '&quot;'
        )
        .replace(
            /'/g,
            '&#039;'
        );
}


