async function salvarCadastroClienteNFE() {

    const modal =
        document.getElementById(
            'modalCadastroClienteNFE'
        );


    if (!modal) {

        showToast(
            'Modal de cliente não encontrado',
            'error'
        );

        return;
    }


    // =====================================================
    // SABER SE É EDIÇÃO
    // =====================================================

    const clienteId =
        Number(
            modal.dataset.clienteId ||
            0
        );


    const editando =
        clienteId >
        0;


    // =====================================================
    // CAMPOS
    // =====================================================

    const nome =
        document
            .getElementById(
                'cadClienteNome'
            )
            ?.value
            .trim() ||
        '';


    const documento =
        String(
            document
                .getElementById(
                    'cadClienteDocumento'
                )
                ?.value ||
            ''
        )
            .replace(
                /\D/g,
                ''
            );


    const logradouro =
        document
            .getElementById(
                'cadClienteLogradouro'
            )
            ?.value
            .trim() ||
        '';


    const numero =
        document
            .getElementById(
                'cadClienteNumero'
            )
            ?.value
            .trim() ||
        'S/N';


    const bairro =
        document
            .getElementById(
                'cadClienteBairro'
            )
            ?.value
            .trim() ||
        '';


    const cidade =
        document
            .getElementById(
                'cadClienteCidade'
            )
            ?.value
            .trim() ||
        '';


    const uf =
        String(
            document
                .getElementById(
                    'cadClienteUF'
                )
                ?.value ||
            ''
        )
            .trim()
            .toUpperCase();


    const cep =
        String(
            document
                .getElementById(
                    'cadClienteCEP'
                )
                ?.value ||
            ''
        )
            .replace(
                /\D/g,
                ''
            );


    // =====================================================
    // VALIDAÇÕES
    // =====================================================

    if (!nome) {

        showToast(
            'Informe o nome do cliente',
            'warning'
        );

        return;
    }


    if (
        documento.length !== 11 &&
        documento.length !== 14
    ) {

        showToast(
            'CPF/CNPJ deve possuir 11 ou 14 dígitos',
            'warning'
        );

        return;
    }


    if (
        uf &&
        uf.length !== 2
    ) {

        showToast(
            'UF deve possuir 2 letras',
            'warning'
        );

        return;
    }


    if (
        cep &&
        cep.length !== 8
    ) {

        showToast(
            'CEP deve possuir 8 dígitos',
            'warning'
        );

        return;
    }


    // =====================================================
    // PAYLOAD
    // =====================================================

    const payload = {

        nome,

        documento,

        logradouro,

        numero,

        bairro,

        cidade,

        uf,

        cep
    };


    const botao =
        document.getElementById(
            'btnSalvarCadastroClienteNFE'
        );


    const textoOriginal =
        botao?.innerHTML ||
        'Salvar';


    if (botao) {

        botao.disabled =
            true;


        botao.innerHTML =
            '<span class="spinner"></span> Salvando...';
    }


    try {

        // =====================================================
        // EDIÇÃO
        // =====================================================

        if (editando) {

            console.log(
                `✏️ Atualizando cliente ${clienteId}:`,
                payload
            );


            const response =
                await fetch(
                    `${window.API_BASE_URL}/nfe/clientes/${clienteId}`,
                    {
                        method:
                            'PUT',

                        headers: {
                            'Content-Type':
                                'application/json'
                        },

                        body:
                            JSON.stringify(
                                payload
                            )
                    }
                );


            let result =
                {};


            try {

                result =
                    await response.json();

            } catch {}


            if (
                !response.ok ||
                result.success === false
            ) {

                throw new Error(
                    result.error ||
                    result.message ||
                    `Erro HTTP ${response.status}`
                );
            }


            showToast(
                'Cliente atualizado com sucesso!',
                'success'
            );


        // =====================================================
        // NOVO CLIENTE
        // =====================================================

        } else {

            const resultado =
                await salvarClienteNoBanco({
                    nome,
                    documento,
                    logradouro,
                    endereco:
                        logradouro,
                    numero,
                    bairro,
                    cidade,
                    uf,
                    cep
                });


            if (
                !resultado ||
                !resultado.success
            ) {

                throw new Error(
                    resultado?.error ||
                    'Não foi possível cadastrar o cliente'
                );
            }


            if (
                resultado.existente
            ) {

                showToast(
                    'Cliente já estava cadastrado',
                    'info'
                );

            } else {

                showToast(
                    'Cliente cadastrado com sucesso!',
                    'success'
                );
            }
        }


        // =====================================================
        // FECHAR
        // =====================================================

        fecharModalCadastroClienteNFE();


        // =====================================================
        // ATUALIZAR ABA CLIENTES
        // =====================================================

        try {

            await carregarClientes();

        } catch (
            error
        ) {

            console.warn(
                '⚠️ Não foi possível atualizar aba Clientes:',
                error
            );
        }


        // =====================================================
        // ATUALIZAR CADASTROS
        // =====================================================

        try {

            await carregarCadastroClientesNFE();

        } catch (
            error
        ) {

            console.warn(
                '⚠️ Não foi possível atualizar cadastro de clientes:',
                error
            );
        }


        // =====================================================
        // ATUALIZAR CLIENTES DA EMISSÃO AVULSA
        // =====================================================

        try {

            await carregarClientesAvulsaNFE();

        } catch (
            error
        ) {

            console.warn(
                '⚠️ Não foi possível atualizar clientes da NF-e avulsa:',
                error
            );
        }


    } catch (
        error
    ) {

        console.error(
            '❌ Erro ao salvar cliente:',
            error
        );


        showToast(
            `Erro ao salvar cliente: ${error.message}`,
            'error'
        );


    } finally {

        const botaoAtual =
            document.getElementById(
                'btnSalvarCadastroClienteNFE'
            );


        if (botaoAtual) {

            botaoAtual.disabled =
                false;


            botaoAtual.innerHTML =
                textoOriginal;
        }
    }
}


